Yes — then the clean model is **not 32 independent ITO cells**. It is:

**32 correlated optical modes → one ITO axis/modulator → focusing optics → camera → intensity integrated over an area.**

The camera is measuring an **area-integrated intensity**, while the ITO axis changes the optical field between measurements.

Below are the complete matched Arduino and Python programs.

### 1. Arduino `.ino`

This keeps the serial protocol simple: Python sends a **1D binary valve pattern**. Set `AXIS_LENGTH` to the number of independently controllable positions on your actual ITO axis.

```cpp
/*
    1-AXIS ITO OPTICAL BENCH CONTROLLER

    Python sends:

        BEGIN 32
        01010101010101010101010101010101
        END

    or, for another axis length:

        BEGIN 128
        010101...
        END

    The Arduino stores the complete 1D pattern and then
    applies it to the external ITO/light-valve electronics.

    IMPORTANT:
    Do NOT connect an ITO electrode directly to Arduino GPIO
    unless the electrical design explicitly permits it.

    Replace setITOCell() with the actual external driver.
*/

#include <Arduino.h>
#include <string.h>

#define AXIS_LENGTH 32

uint8_t pattern[AXIS_LENGTH];

bool receivingPattern = false;

int currentLength = 0;


// ============================================================
// SETUP
// ============================================================

void setup()
{
    Serial.begin(115200);

    memset(
        pattern,
        0,
        sizeof(pattern)
    );

    initialiseITOHardware();

    Serial.println("ITO_READY");
}


// ============================================================
// MAIN LOOP
// ============================================================

void loop()
{
    if (Serial.available())
    {
        String line =
            Serial.readStringUntil('\n');

        line.trim();

        if (line.length() == 0)
            return;

        processLine(line);
    }
}


// ============================================================
// SERIAL PROTOCOL
// ============================================================

void processLine(String &line)
{
    // --------------------------------------------------------
    // BEGIN
    // --------------------------------------------------------

    if (line.startsWith("BEGIN"))
    {
        int space =
            line.indexOf(' ');

        if (space < 0)
        {
            Serial.println("ERROR BEGIN");
            return;
