        currentLength = 0;

        receivingPattern = true;

        Serial.println("BEGIN_OK");

        return;
    }


    // --------------------------------------------------------
    // END
    // --------------------------------------------------------

    if (line == "END")
    {
        if (!receivingPattern)
        {
            Serial.println(
                "ERROR NO_PATTERN"
            );

            return;
