            else
            {
                Serial.println(
                    "ERROR INVALID_BIT"
                );

                receivingPattern = false;

                return;
            }
        }

        currentLength =
            AXIS_LENGTH;

        return;
    }

    Serial.println(
        "ERROR UNKNOWN_COMMAND"
    );
}


// ============================================================
// APPLY ITO
// ============================================================

void applyITO()
{
    for (
        int i = 0;
