        )
    )

    axes[0, 0].set_title(
        "32-mode field amplitude"
    )

    # --------------------------------------------------------
    # FIELD PHASE
    # --------------------------------------------------------

    axes[0, 1].imshow(
        np.angle(
            result["field"]
        ),
        cmap="twilight"
    )

    axes[0, 1].set_title(
        "32-mode field phase"
    )

    # --------------------------------------------------------
    # ITO AXIS
    # --------------------------------------------------------

    axes[0, 2].imshow(
        result["ito"][
            None,
            :
        ],
        aspect="auto",
        interpolation="nearest"
    )

    axes[0, 2].set_title(
        "1D ITO axis"
    )

    axes[0, 2].set_xlabel(
        "ITO position"
    )

    # --------------------------------------------------------
    # CAMERA
    # --------------------------------------------------------

    axes[1, 0].imshow(
        result["camera"],
        cmap="gray"
    )

    axes[1, 0].set_title(
        "Camera intensity"
    )

    # ROI

    x0 = detector.cfg.roi_x0
    x1 = detector.cfg.roi_x1

    y0 = detector.cfg.roi_y0
    y1 = detector.cfg.roi_y1

    axes[1, 0].plot(
        [x0, x1, x1, x0, x0],
        [y0, y0, y1, y1, y0],
        linewidth=2
    )

    # --------------------------------------------------------
    # AREA INTENSITY
    # --------------------------------------------------------

    series = (
        detector.series()
    )

    axes[1, 1].plot(
        series
    )

    axes[1, 1].set_title(
        "Area-integrated intensity"
    )

    axes[1, 1].set_xlabel(
        "Measurement"
    )

    axes[1, 1].set_ylabel(
        "I_area"
    )

    # --------------------------------------------------------
    # AUTOCORRELATION
    # --------------------------------------------------------

    if len(series) > 2:

        centered = (
            series
            -
            np.mean(series)
        )

        autocorrelation = (
            np.correlate(
                centered,
                centered,
                mode="full"
            )
        )

        autocorrelation = (
            autocorrelation[
                len(series)-1:
            ]
        )

        if (
            autocorrelation[0]
            >
            EPS
        ):

            autocorrelation /= (
                autocorrelation[0]
            )

        axes[1, 2].plot(
            autocorrelation
        )

    axes[1, 2].set_title(
        "Area-intensity autocorrelation"
    )

    axes[1, 2].set_xlabel(
        "Lag"
    )

    plt.tight_layout()

    plt.show()


