def compare_correlated_vs_independent(
    shots,
    seed
):

    """
    Compare area-integrated intensity statistics
    between:

        1. strongly correlated modes
        2. independent modes

    The comparison is intentionally performed using
    ONLY the measured area intensity.
    """

    correlated_cfg = (
        OpticalConfig(
            phase_correlation=0.90,
            amplitude_correlation=0.75
        )
    )

    independent_cfg = (
        OpticalConfig(
            phase_correlation=0.0,
            amplitude_correlation=0.0
        )
    )

    correlated = OpticalBench(
        correlated_cfg,
        seed=seed
    )

    independent = OpticalBench(
        independent_cfg,
        seed=seed
    )

    correlated_series = []

    independent_series = []

    for n in range(
        shots
    ):

        a = correlated.measure(
            phase_control=0.02
        )

        b = independent.measure(
            phase_control=0.02
        )

        correlated_series.append(
            a["area_intensity"]
        )

        independent_series.append(
            b["area_intensity"]
        )

    correlated_series = np.asarray(
        correlated_series
    )

    independent_series = np.asarray(
        independent_series
    )

    print()
    print(
        "=========================================="
    )
    print(
        "AREA-INTENSITY STATISTICAL COMPARISON"
    )
    print(
        "=========================================="
    )

    print()

    print(
        "CORRELATED 32-MODE FIELD"
    )

    print(
        "mean     :",
        np.mean(
            correlated_series
        )
    )

    print(
        "variance :",
        np.var(
            correlated_series
        )
    )

    print(
        "std      :",
        np.std(
            correlated_series
        )
    )

    print()

    print(
        "INDEPENDENT 32-MODE FIELD"
    )

    print(
        "mean     :",
        np.mean(
            independent_series
        )
    )

    print(
        "variance :",
        np.var(
            independent_series
        )
    )

    print(
        "std      :",
        np.std(
            independent_series
        )
    )

    print()

    # --------------------------------------------------------
    # Plot distributions
    # --------------------------------------------------------

    import matplotlib.pyplot as plt

    plt.figure(
        figsize=(10, 5)
    )

    plt.hist(
        correlated_series,
        bins=40,
        alpha=0.6,
        label="correlated"
    )

    plt.hist(
        independent_series,
        bins=40,
        alpha=0.6,
        label="independent"
    )

    plt.xlabel(
        "Area-integrated intensity"
    )

    plt.ylabel(
        "Count"
    )

    plt.title(
        "Area-intensity distributions"
    )

    plt.legend()

    plt.tight_layout()

    plt.show()


