# ============================================================
# SOFTMAX
# ============================================================

def softmax(values, beta=6.0):

    values = np.asarray(
        values,
        dtype=np.float64
    )

    logits = values * beta

    logits -= np.max(logits)

    exp_values = np.exp(
        logits
    )

    return (
        exp_values /
        np.sum(exp_values)
    )


# ============================================================
# ENTROPY
# ============================================================

def entropy(probabilities):

    p = np.asarray(
        probabilities,
        dtype=np.float64
    )

    p = p[p > 1e-12]

    if len(p) == 0:
        return 0.0

    return float(
        -np.sum(
            p * np.log2(p)
        )
    )


def normalized_entropy(probabilities):

    p = np.asarray(
        probabilities,
        dtype=np.float64
    )

    if len(p) <= 1:
        return 0.0

    h = entropy(p)

    maximum = math.log2(
        len(p)
    )

    return float(
        h / maximum
    )


