        if torch.cuda.is_available():

            self.device = torch.device(
                "cuda"
            )

            self.model.to(
                self.device
            )

            print(
                "Using CUDA"
            )

        else:

            self.device = torch.device(
                "cpu"
            )

            print(
                "Using CPU"
            )

    @torch.no_grad()
    def detect(
        self,
        frame
    ):

        rgb = cv2.cvtColor(
            frame,
            cv2.COLOR_BGR2RGB
        )

        tensor = torch.from_numpy(
            rgb
        ).permute(
            2,
            0,
            1
        )

        tensor = self.transform(
            tensor
        )

        tensor = tensor.to(
            self.device
        )

        prediction = self.model(
            [tensor]
        )[0]

        detections = []

        for box, label, score in zip(
            prediction["boxes"],
            prediction["labels"],
            prediction["scores"]
        ):

            confidence = float(
                score
            )

            if confidence < DETECTION_THRESHOLD:
                continue

            x1, y1, x2, y2 = (
                box.detach()
                .cpu()
                .numpy()
                .tolist()
            )

            detections.append({

                "label":
                    self.labels[
                        int(label)
                    ],

                "confidence":
                    confidence,

                "box":
                    (
                        x1,
                        y1,
                        x2,
                        y2
                    )
            })

        return detections


# ============================================================
# ACTION MODEL
# ============================================================

def get_action_distribution(
    label,
    confidence
):

    affordances = AFFORDANCES.get(

        label,

        {
            "observe": 0.20,
            "approach": 0.40,
            "interact": 0.60,
        }
    )

    actions = list(
        affordances.keys()
    )

    scores = []

    for action in actions:

        q = affordances[action]

        scores.append(
            q * confidence
        )

    probabilities = softmax(
        scores,
        beta=6.0
    )

    return dict(
        zip(
            actions,
            probabilities
        )
    )


# ============================================================
# DISTORTIONS
# ============================================================

def blur(
    image,
    strength
):

    kernel = int(
        3 + strength * 41
    )

    if kernel % 2 == 0:
        kernel += 1

    return cv2.GaussianBlur(
        image,
        (
            kernel,
            kernel
        ),
        0
    )


def gaussian_noise(
    image,
    strength
):

    sigma = (
        70.0 * strength
    )

    noise = np.random.normal(
        0,
        sigma,
        image.shape
    )

    result = (
        image.astype(
            np.float32
        )
        + noise
    )

    return np.clip(
        result,
        0,
        255
    ).astype(
        np.uint8
    )


def pixelate(
    image,
    strength
):

    h, w = image.shape[:2]

    factor = max(
        2,
        int(
            2 + 45 * strength
        )
    )

    small = cv2.resize(
        image,
        (
            max(1, w // factor),
            max(1, h // factor)
        ),
        interpolation=cv2.INTER_AREA
    )

    return cv2.resize(
        small,
        (w, h),
        interpolation=cv2.INTER_NEAREST
    )


def contrast_loss(
    image,
    strength
):

    alpha = (
        1.0
        - 0.9 * strength
    )

    mean = np.mean(
        image,
        axis=(0, 1),
        keepdims=True
    )

    result = (
        image.astype(
            np.float32
        )
        - mean
    ) * alpha + mean

    return np.clip(
        result,
        0,
        255
    ).astype(
        np.uint8
    )


def jpeg_distortion(
    image,
    strength
):

    quality = int(
        100
        - 95 * strength
    )

    quality = max(
        3,
        quality
    )

    success, encoded = cv2.imencode(
        ".jpg",
        image,
        [
            cv2.IMWRITE_JPEG_QUALITY,
            quality
        ]
    )

    if not success:
        return image

    return cv2.imdecode(
        encoded,
        cv2.IMREAD_COLOR
    )


def combined_distortion(
    image,
    strength
):

    result = blur(
        image,
        strength * 0.45
    )

    result = gaussian_noise(
        result,
        strength * 0.45
    )

    result = pixelate(
        result,
        strength * 0.25
    )

    result = contrast_loss(
        result,
        strength * 0.40
    )

    return result


def distort(
    image,
    strength,
    mode
):

    if mode == "blur":
        return blur(
            image,
            strength
        )

    if mode == "noise":
        return gaussian_noise(
            image,
            strength
        )

    if mode == "pixel":
        return pixelate(
            image,
            strength
        )

    if mode == "contrast":
        return contrast_loss(
            image,
            strength
        )

    if mode == "jpeg":
        return jpeg_distortion(
            image,
            strength
        )

    if mode == "combined":
        return combined_distortion(
            image,
            strength
        )

    raise ValueError(
        mode
    )


# ============================================================
# TARGET SELECTION
# ============================================================

def strongest_object(
    detections,
    target
):

    candidates = [
        d
        for d in detections
        if d["label"] == target
    ]

    if not candidates:
        return None

    return max(
        candidates,
        key=lambda d:
        d["confidence"]
    )


# ============================================================
# DISTORTION EXPERIMENT
# ============================================================

def run_distortion_experiment(
    frame,
    detector,
    target,
    mode,
    steps,
    repeats
):

    strengths = np.linspace(
        0.0,
        1.0,
        steps
    )

    results = []

    for strength in strengths:

        confidence_values = []

        action_values = []

        entropy_values = []

        detections = []

        actions = []

        for _ in range(
            repeats
        ):

            distorted = distort(
                frame,
                float(strength),
                mode
            )

            objects = detector.detect(
                distorted
            )

            target_object = (
                strongest_object(
                    objects,
                    target
                )
            )

            if target_object is None:

                confidence = 0.0
                action_probability = 0.0
                h = 1.0
                action = None

            else:

                confidence = (
                    target_object[
                        "confidence"
                    ]
                )

                action_distribution = (
                    get_action_distribution(
                        target,
                        confidence
                    )
                )

                action = max(
                    action_distribution,
                    key=action_distribution.get
                )

                action_probability = (
                    action_distribution[
                        action
                    ]
                )

                h = normalized_entropy(
                    list(
                        action_distribution.values()
                    )
                )

            confidence_values.append(
                confidence
            )

            action_values.append(
                action_probability
            )

            entropy_values.append(
                h
            )

            detections.append(
                confidence > 0
            )

            actions.append(
                action
            )

        results.append({

            "distortion":
                float(strength),

            "confidence_mean":
                float(
                    np.mean(
                        confidence_values
                    )
                ),

            "confidence_std":
                float(
                    np.std(
                        confidence_values
                    )
                ),

            "confidence_min":
                float(
                    np.min(
                        confidence_values
                    )
                ),

            "confidence_max":
                float(
                    np.max(
                        confidence_values
                    )
                ),

            "action_mean":
                float(
                    np.mean(
                        action_values
                    )
                ),

            "action_std":
                float(
                    np.std(
                        action_values
                    )
                ),

            "entropy_mean":
                float(
                    np.mean(
                        entropy_values
                    )
                ),

            "detection_rate":
                float(
                    np.mean(
                        detections
                    )
                ),

            "actions":
                actions
        })

    return results


# ============================================================
# CURVE METRICS
# ============================================================

def calculate_auc(
    x,
    y
):

    return float(
        np.trapezoid(
            y,
            x
        )
    )


def threshold_crossing(
    x,
    y,
    threshold
):

    for xi, yi in zip(
        x,
        y
    ):

        if yi < threshold:

            return float(xi)

    return 1.0


def slope(
    x,
    y
):

    if len(x) < 2:
        return 0.0

    m, _ = np.polyfit(
        x,
        y,
        1
    )

    return float(m)


# ============================================================
# STATISTICS
# ============================================================

def summarize(
    results
):

    x = np.array([
        r["distortion"]
        for r in results
    ])

    confidence = np.array([
        r["confidence_mean"]
        for r in results
    ])

    action = np.array([
        r["action_mean"]
        for r in results
    ])

    entropy_values = np.array([
        r["entropy_mean"]
        for r in results
    ])

    detection = np.array([
        r["detection_rate"]
        for r in results
    ])

    stats = {

        "confidence_auc":
            calculate_auc(
                x,
                confidence
            ),

        "action_auc":
            calculate_auc(
                x,
                action
            ),

        "entropy_auc":
            calculate_auc(
                x,
                entropy_values
            ),

        "confidence_slope":
            slope(
                x,
                confidence
            ),

        "action_slope":
            slope(
                x,
                action
            ),

        "entropy_slope":
            slope(
                x,
                entropy_values
            ),

        "action_threshold_75":
            threshold_crossing(
                x,
                action,
                0.75
            ),

        "action_threshold_50":
            threshold_crossing(
                x,
                action,
                0.50
            ),

        "action_threshold_25":
            threshold_crossing(
                x,
                action,
                0.25
            ),

        "recognition_threshold_50":
            threshold_crossing(
                x,
                confidence,
                0.50
            ),

        "detection_threshold_50":
            threshold_crossing(
                x,
                detection,
                0.50
            ),

        "initial_confidence":
            float(
                confidence[0]
            ),

        "final_confidence":
            float(
                confidence[-1]
            ),

        "initial_action":
            float(
                action[0]
            ),

        "final_action":
            float(
                action[-1]
            ),

        "confidence_drop":
            float(
                confidence[0]
                - confidence[-1]
            ),

        "action_drop":
            float(
                action[0]
                - action[-1]
            ),

        "initial_entropy":
            float(
                entropy_values[0]
            ),

        "final_entropy":
            float(
                entropy_values[-1]
            )
    }

    return stats


