# ============================================================
# SOFTMAX
# ============================================================

def softmax(
    values,
    beta=6.0
):

    values = np.asarray(
        values,
        dtype=np.float64
    )

    logits = (
        values * beta
    )

    logits -= np.max(
        logits
    )

    exp_values = np.exp(
        logits
    )

    return (
        exp_values
        / np.sum(exp_values)
    )


# ============================================================
# ACTION DISTRIBUTION
# ============================================================

def action_distribution(
    obj
):

    affordances = AFFORDANCES.get(
        obj.label,
        {
            "observe": 0.20,
            "approach": 0.40,
            "interact": 0.60,
        }
    )

    actions = list(
        affordances.keys()
    )

    scores = []

    for action in actions:

        q = affordances[action]

        scores.append(
            q * obj.confidence
        )

    probabilities = softmax(
        scores
    )

    return dict(
        zip(
            actions,
            probabilities
        )
    )


# ============================================================
# ENTROPY
# ============================================================

def entropy(
    probabilities
):

    p = np.asarray(
        probabilities,
        dtype=np.float64
    )

    p = p[
        p > 1e-12
    ]

    return float(
        -np.sum(
            p * np.log2(p)
        )
    )


def normalized_entropy(
    probabilities
):

    p = np.asarray(
        probabilities,
        dtype=np.float64
    )

    h = entropy(
        p
    )

    maximum = math.log2(
        len(p)
    )

    if maximum <= 0:

        return 0.0

    return (
        h / maximum
    )


# ============================================================
# DISTORTIONS
# ============================================================

def blur(
    image,
    strength
):

    kernel = int(
        3 + 45 * strength
    )

    if kernel % 2 == 0:

        kernel += 1

    return cv2.GaussianBlur(
        image,
        (
            kernel,
            kernel
        ),
        0
    )


def noise(
    image,
    strength
):

    sigma = (
        strength * 70
    )

    n = np.random.normal(
        0,
        sigma,
        image.shape
    )

    result = (
        image.astype(
            np.float32
        )
        + n
    )

    return np.clip(
        result,
        0,
        255
    ).astype(
        np.uint8
    )


def pixelate(
    image,
    strength
):

    h, w = image.shape[:2]

    factor = max(
        2,
        int(
            2 + 45 * strength
        )
    )

    small = cv2.resize(
        image,
        (
            max(1, w // factor),
            max(1, h // factor)
        ),
        interpolation=cv2.INTER_AREA
    )

    return cv2.resize(
        small,
        (w, h),
        interpolation=cv2.INTER_NEAREST
    )


def contrast(
    image,
    strength
):

    alpha = (
        1.0
        - 0.90 * strength
    )

    mean = np.mean(
        image,
        axis=(0, 1),
        keepdims=True
    )

    result = (
        image.astype(
            np.float32
        )
        - mean
    ) * alpha + mean

    return np.clip(
        result,
        0,
        255
    ).astype(
        np.uint8
    )


def brightness(
    image,
    strength
):

    factor = (
        1.0
        - 0.85 * strength
    )

    result = (
        image.astype(
            np.float32
        )
        * factor
    )

    return np.clip(
        result,
        0,
        255
    ).astype(
        np.uint8
    )


def jpeg(
    image,
    strength
):

    quality = int(
        100
        - 95 * strength
    )

    quality = max(
        3,
        quality
    )

    success, encoded = cv2.imencode(
        ".jpg",
        image,
        [
            cv2.IMWRITE_JPEG_QUALITY,
            quality
        ]
    )

    if not success:

        return image

    return cv2.imdecode(
        encoded,
        cv2.IMREAD_COLOR
    )


def combined(
    image,
    strength
):

    result = blur(
        image,
        strength * 0.5
    )

    result = noise(
        result,
        strength * 0.5
    )

    result = pixelate(
        result,
        strength * 0.35
    )

    result = contrast(
        result,
        strength * 0.5
    )

    return result


def distort(
    image,
    strength,
    mode
):

    if mode == "blur":
        return blur(
            image,
            strength
        )

    if mode == "noise":
        return noise(
            image,
            strength
        )

    if mode == "pixel":
        return pixelate(
            image,
            strength
        )

    if mode == "contrast":
        return contrast(
            image,
            strength
        )

    if mode == "brightness":
        return brightness(
            image,
            strength
        )

    if mode == "jpeg":
        return jpeg(
            image,
            strength
        )

    if mode == "combined":
        return combined(
            image,
            strength
        )

    raise ValueError(
        f"Unknown distortion: {mode}"
    )


# ============================================================
# TARGET MATCHING
# ============================================================

def strongest_target(
    objects,
    target_label
):

    matching = [
        obj
        for obj in objects
        if obj.label == target_label
    ]

    if not matching:

        return None

    return max(
        matching,
        key=lambda obj:
        obj.confidence
    )


# ============================================================
# FRAME ANALYSIS
# ============================================================

def analyze_frame(
    detector,
    frame,
    target_label
):

    objects = detector.recognize(
        frame
    )

    target = strongest_target(
        objects,
        target_label
    )

    if target is None:

        return {
            "detected": False,
            "confidence": 0.0,
            "actions": {},
            "best_action": None,
            "action_probability": 0.0,
            "entropy": 0.0,
            "normalized_entropy": 0.0,
            "object_count": len(objects),
        }

    actions = action_distribution(
        target
    )

    best_action = max(
        actions,
        key=actions.get
    )

    probabilities = list(
        actions.values()
    )

    return {
        "detected": True,

        "confidence":
            target.confidence,

        "actions":
            actions,

        "best_action":
            best_action,

        "action_probability":
            actions[best_action],

        "entropy":
            entropy(
                probabilities
            ),

        "normalized_entropy":
            normalized_entropy(
                probabilities
            ),

        "object_count":
            len(objects),
    }


# ============================================================
# STATISTICAL HELPERS
# ============================================================

def mean(x):

    if len(x) == 0:
        return 0.0

    return float(
        np.mean(x)
    )


def std(x):

    if len(x) < 2:
        return 0.0

    return float(
        np.std(
            x,
            ddof=1
        )
    )


def median(x):

    if len(x) == 0:
        return 0.0

    return float(
        np.median(x)
    )


def percentile(
    x,
    q
):

    if len(x) == 0:
        return 0.0

    return float(
        np.percentile(
            x,
            q
        )
    )


def coefficient_variation(
    x
):

    m = mean(x)

    if abs(m) < 1e-12:
        return 0.0

    return (
        std(x) / abs(m)
    )


# ============================================================
# BOOTSTRAP CONFIDENCE INTERVAL
# ============================================================

def bootstrap_ci(
    values,
    statistic=np.mean,
    iterations=2000,
    confidence=0.95
):

    values = np.asarray(
        values,
        dtype=np.float64
    )

    if len(values) == 0:

        return (
            0.0,
            0.0
        )

    samples = []

    for _ in range(
        iterations
    ):

        sample = np.random.choice(
            values,
            size=len(values),
            replace=True
        )

        samples.append(
            statistic(sample)
        )

    alpha = (
        1.0 - confidence
    )

    low = np.percentile(
        samples,
        100 * alpha / 2
    )

    high = np.percentile(
        samples,
        100 * (1 - alpha / 2)
    )

    return (
        float(low),
        float(high)
    )


# ============================================================
# CURVE STATISTICS
# ============================================================

def curve_auc(
    x,
    y
):

    if len(x) < 2:

        return 0.0

    return float(
        np.trapezoid(
            y,
            x
        )
    )


def first_threshold(
    x,
    y,
    threshold
):

    x = np.asarray(x)
    y = np.asarray(y)

    indices = np.where(
        y < threshold
    )[0]

    if len(indices) == 0:

        return 1.0

    return float(
        x[
            indices[0]
        ]
    )


def curve_slope(
    x,
    y
):

    x = np.asarray(x)
    y = np.asarray(y)

    if len(x) < 2:

        return 0.0

    slope, _ = np.polyfit(
        x,
        y,
        1
    )

    return float(
        slope
    )


# ============================================================
# ACTION SWITCHING
# ============================================================

def action_switch_count(
    actions
):

    if not actions:

        return 0

    switches = 0

    previous = actions[0]

    for action in actions[1:]:

        if action != previous:

            switches += 1

        previous = action

    return switches


# ============================================================
# EXPERIMENT
# ============================================================

class ImageExperiment:

    def __init__(
        self,
        detector
    ):

        self.detector = detector

    def run(
        self,
        image,
        target_label,
        mode,
        steps=DEFAULT_STEPS,
        repeats=DEFAULT_REPEATS
    ):

        strengths = np.linspace(
            0.0,
            1.0,
            steps
        )

        rows = []

        for strength in strengths:

            print()
            print(
                f"Distortion={strength:.2f}"
            )

            for repeat in range(
                repeats
            ):

                distorted = distort(
                    image,
                    float(strength),
                    mode
                )

                result = analyze_frame(
                    self.detector,
                    distorted,
                    target_label
                )

                row = {
                    "distortion":
                        float(strength),

                    "repeat":
                        repeat,

                    "detected":
                        result["detected"],

                    "confidence":
                        result["confidence"],

                    "best_action":
                        result["best_action"],

                    "action_probability":
                        result[
                            "action_probability"
                        ],

                    "entropy":
                        result["entropy"],

                    "normalized_entropy":
                        result[
                            "normalized_entropy"
                        ],

                    "object_count":
                        result["object_count"],

                    "actions":
                        result["actions"],
                }

                rows.append(
                    row
                )

                print(
                    f"  repeat={repeat + 1} "
                    f"confidence="
                    f"{result['confidence']:.3f} "
                    f"action="
                    f"{str(result['best_action']):>12} "
                    f"P="
                    f"{result['action_probability']:.3f} "
                    f"H="
                    f"{result['normalized_entropy']:.3f}"
                )

        return rows


# ============================================================
# AGGREGATE STATISTICS
# ============================================================

def aggregate_statistics(
    rows
):

    distortion_values = sorted(
        set(
            r["distortion"]
            for r in rows
        )
    )

    aggregate = []

    for d in distortion_values:

        subset = [
            r
            for r in rows
            if abs(
                r["distortion"] - d
            ) < 1e-9
        ]

        confidence = np.array([
            r["confidence"]
            for r in subset
        ])

        action_probability = np.array([
            r["action_probability"]
            for r in subset
        ])

        entropy_values = np.array([
            r["normalized_entropy"]
            for r in subset
        ])

        detection_rate = np.mean([
            r["detected"]
            for r in subset
        ])

        aggregate.append({

            "distortion":
                float(d),

            "confidence_mean":
                mean(confidence),

            "confidence_std":
                std(confidence),

            "confidence_median":
                median(confidence),

            "confidence_p05":
                percentile(
                    confidence,
                    5
                ),

            "confidence_p95":
                percentile(
                    confidence,
                    95
                ),

            "action_mean":
                mean(
                    action_probability
                ),

            "action_std":
                std(
                    action_probability
                ),

            "action_median":
                median(
                    action_probability
                ),

            "action_p05":
                percentile(
                    action_probability,
                    5
                ),

            "action_p95":
                percentile(
                    action_probability,
                    95
                ),

            "entropy_mean":
                mean(
                    entropy_values
                ),

            "entropy_std":
                std(
                    entropy_values
                ),

            "detection_rate":
                float(
                    detection_rate
                ),
        })

    return aggregate


# ============================================================
# GLOBAL STATISTICS
# ============================================================

def calculate_global_statistics(
    aggregate,
    rows
):

    x = np.array([
        a["distortion"]
        for a in aggregate
    ])

    confidence = np.array([
        a["confidence_mean"]
        for a in aggregate
    ])

    action = np.array([
        a["action_mean"]
        for a in aggregate
    ])

    entropy_values = np.array([
        a["entropy_mean"]
        for a in aggregate
    ])

    detection = np.array([
        a["detection_rate"]
        for a in aggregate
    ])

    action_values = np.array([
        r["action_probability"]
        for r in rows
    ])

    confidence_values = np.array([
        r["confidence"]
        for r in rows
    ])

    # --------------------------------------------------------
    # AREA UNDER CURVES
    # --------------------------------------------------------

    confidence_auc = curve_auc(
        x,
        confidence
    )

    action_auc = curve_auc(
        x,
        action
    )

    entropy_auc = curve_auc(
        x,
        entropy_values
    )

    # --------------------------------------------------------
    # THRESHOLDS
    # --------------------------------------------------------

    action_50 = first_threshold(
        x,
        action,
        0.50
    )

    action_75 = first_threshold(
        x,
        action,
        0.75
    )

    action_25 = first_threshold(
        x,
        action,
        0.25
    )

    recognition_50 = first_threshold(
        x,
        confidence,
        0.50
    )

    recognition_25 = first_threshold(
        x,
        confidence,
        0.25
    )

    detection_50 = first_threshold(
        x,
        detection,
        0.50
    )

    # --------------------------------------------------------
    # SLOPES
    # --------------------------------------------------------

    confidence_slope = curve_slope(
        x,
        confidence
    )

    action_slope = curve_slope(
        x,
        action
    )

    entropy_slope = curve_slope(
        x,
        entropy_values
    )

    # --------------------------------------------------------
    # INITIAL / FINAL
    # --------------------------------------------------------

    initial_confidence = (
        confidence[0]
    )

    final_confidence = (
        confidence[-1]
    )

    initial_action = (
        action[0]
    )

    final_action = (
        action[-1]
    )

    # --------------------------------------------------------
    # EFFECT SIZES
    # --------------------------------------------------------

    confidence_drop = (
        initial_confidence
        - final_confidence
    )

    action_drop = (
        initial_action
        - final_action
    )

    # --------------------------------------------------------
    # BOOTSTRAP CIs
    # --------------------------------------------------------

    conf_ci = bootstrap_ci(
        confidence_values
    )

    action_ci = bootstrap_ci(
        action_values
    )

    return {

        "n_measurements":
            len(rows),

        "n_distortion_levels":
            len(aggregate),

        "confidence_auc":
            confidence_auc,

        "action_auc":
            action_auc,

        "entropy_auc":
            entropy_auc,

        "action_threshold_75":
            action_75,

        "action_threshold_50":
            action_50,

        "action_threshold_25":
            action_25,

        "recognition_threshold_50":
            recognition_50,

        "recognition_threshold_25":
            recognition_25,

        "detection_threshold_50":
            detection_50,

        "confidence_slope":
            confidence_slope,

        "action_slope":
            action_slope,

        "entropy_slope":
            entropy_slope,

        "initial_confidence":
            float(
                initial_confidence
            ),

        "final_confidence":
            float(
                final_confidence
            ),

        "confidence_drop":
            float(
                confidence_drop
            ),

        "initial_action_probability":
            float(
                initial_action
            ),

        "final_action_probability":
            float(
                final_action
            ),

        "action_probability_drop":
            float(
                action_drop
            ),

        "confidence_mean":
            mean(
                confidence_values
            ),

        "confidence_std":
            std(
                confidence_values
            ),

        "confidence_cv":
            coefficient_variation(
                confidence_values
            ),

        "action_mean":
            mean(
                action_values
            ),

        "action_std":
            std(
                action_values
            ),

        "action_cv":
            coefficient_variation(
                action_values
            ),

        "confidence_bootstrap_95":
            conf_ci,

        "action_bootstrap_95":
            action_ci,
    }


# ============================================================
# ACTION STABILITY
# ============================================================

def calculate_action_stability(
    rows
):

    by_repeat = {}

    for row in rows:

        repeat = row["repeat"]

        by_repeat.setdefault(
            repeat,
            []
        )

        by_repeat[
            repeat
        ].append(
            row
        )

    repeat_stabilities = []

    for repeat, values in (
        by_repeat.items()
    ):

        actions = [
            v["best_action"]
            for v in values
        ]

        actions = [
            a
            for a in actions
            if a is not None
        ]

        if len(actions) < 2:

            continue

        switches = (
            action_switch_count(
                actions
            )
        )

        possible = (
            len(actions) - 1
        )

        stability = (
            1.0
            - switches / possible
        )

        repeat_stabilities.append(
            stability
        )

    if not repeat_stabilities:

        return {
            "mean_stability": 0.0,
            "std_stability": 0.0
        }

    return {

        "mean_stability":
            mean(
                repeat_stabilities
            ),

        "std_stability":
            std(
                repeat_stabilities
            )
    }


# ============================================================
