    # --------------------------------------------------------

    detector = (
        VisualObjectSystem()
    )

    # --------------------------------------------------------
    # EXPERIMENT
    # --------------------------------------------------------

    experiment = ImageExperiment(
        detector
    )

    rows = experiment.run(
        image=image,
        target_label=args.target,
        mode=args.distortion,
        steps=args.steps,
        repeats=args.repeats
    )

    # --------------------------------------------------------
