from __future__ import annotations

import json
import math
import random
import re
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Tuple, Optional


# ============================================================
# CONFIGURATION
# ============================================================

CORPUS_PATH = "corpus.txt"
MODEL_PATH = "model.json"
GROUND_TRUTH_PATH = "ground_truth.jsonl"

PROMPT = "what is the capital of france"

MAX_NEW_TOKENS = 50
TEMPERATURE = 0.8
TOP_K = 20

MIN_COUNT = 1
INFLUENCE_TAU = 0.5

CURVE_NAME = "sigmoid"
CURVE_K = 8.0
CURVE_MIDPOINT = 0.5

# Chinese Room rebinding
REBIND_AFTER_GENERATION = True
CANDIDATE_LIMIT = 5

LEXICAL_WEIGHT = 0.45
VECTOR_WEIGHT = 0.55

ACCEPTANCE_THRESHOLD = 0.35
AMBIGUITY_MARGIN = 0.10

# Set True to retrain every run.
TRAIN_MODEL = True


# ============================================================
# TOKENIZATION
# ============================================================

TOKEN_RE = re.compile(
    r"[A-Za-z0-9_']+|[.,!?;:()\[\]{}\-]"
)


def tokenize(text: str) -> List[str]:
    return TOKEN_RE.findall(text.lower())


def split_sentences(text: str) -> List[str]:
    parts = re.split(
        r"(?<=[.!?])\s+|\n+",
        text.strip(),
    )

    return [
        part.strip()
        for part in parts
        if part.strip()
    ]


def safe_log(
    value: float,
    floor: float = 1e-12,
) -> float:
    return math.log(
        max(value, floor)
    )


# ============================================================
# VECTOR FUNCTIONS
# ============================================================

def cosine_similarity(
    a: Dict[str, float],
    b: Dict[str, float],
) -> float:

    if not a or not b:
        return 0.0

    common = set(a).intersection(b)

    dot = sum(
        a[k] * b[k]
        for k in common
    )

    norm_a = math.sqrt(
        sum(v * v for v in a.values())
    )

    norm_b = math.sqrt(
        sum(v * v for v in b.values())
    )

    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0

    return dot / (
        norm_a * norm_b
    )


def bag_of_words(
    tokens: Iterable[str],
) -> Counter:

    ignored = {
        "<bos>",
        "<eos>",
        "<unk>",
    }

    return Counter(
        token
        for token in tokens
        if token not in ignored
    )


def lexical_overlap(
    a: Iterable[str],
    b: Iterable[str],
) -> float:

    sa = set(a)
    sb = set(b)

    ignored = {
        "<bos>",
        "<eos>",
        "<unk>",
    }

    sa -= ignored
    sb -= ignored

    if not sa or not sb:
        return 0.0

    intersection = len(
        sa.intersection(sb)
    )

    union = len(
        sa.union(sb)
    )

    if union == 0:
        return 0.0

    return intersection / union


# ============================================================
# GROUND TRUTH
# ============================================================

@dataclass
class GroundTruthBinding:

    prompt: str
    ground_truth: str

    label: str = ""
    source: str = ""

    def to_dict(self) -> dict:
        return {
            "prompt": self.prompt,
            "ground_truth": self.ground_truth,
            "label": self.label,
            "source": self.source,
        }

    @classmethod
    def from_dict(
        cls,
        data: dict,
    ) -> "GroundTruthBinding":

        return cls(
            prompt=data["prompt"],
            ground_truth=data["ground_truth"],
            label=data.get(
                "label",
                "",
            ),
            source=data.get(
                "source",
                "",
            ),
        )


# ============================================================
# REBINDING RESULT
# ============================================================

@dataclass
class RebindingResult:

    generated_text: str

    potential_prompts: List[dict]

    rebound_prompt: Optional[str]

    rebound_ground_truth: Optional[str]

    rebound_label: Optional[str]

    grounding_score: float

    ambiguity: float

    semantic_overlap: float

    symbolic_overlap: float

    accepted: bool

    reason: str

    def to_dict(self) -> dict:

        return {
            "generated_text":
                self.generated_text,

            "potential_prompts":
                self.potential_prompts,

            "rebound_prompt":
                self.rebound_prompt,

            "rebound_ground_truth":
                self.rebound_ground_truth,

            "rebound_label":
                self.rebound_label,

            "grounding_score":
                self.grounding_score,

            "ambiguity":
                self.ambiguity,

            "semantic_overlap":
