# ============================================================
# CHINESE ROOM REBINDER
# ============================================================

@dataclass
class ChineseRoomRebinder:

    bindings: List[
        GroundTruthBinding
    ] = field(
        default_factory=list
    )

    lexical_weight: float = (
        LEXICAL_WEIGHT
    )

    vector_weight: float = (
        VECTOR_WEIGHT
    )

    acceptance_threshold: float = (
        ACCEPTANCE_THRESHOLD
    )

    ambiguity_margin: float = (
        AMBIGUITY_MARGIN
    )

    # --------------------------------------------------------
    # ADD BINDING
    # --------------------------------------------------------

    def add_binding(
        self,
        prompt: str,
        ground_truth: str,
        label: str = "",
        source: str = "",
    ) -> None:

        self.bindings.append(
            GroundTruthBinding(
                prompt=prompt,
                ground_truth=ground_truth,
                label=label,
                source=source,
            )
        )

    # --------------------------------------------------------
    # LOAD GROUND TRUTH
    # --------------------------------------------------------

    def load_jsonl(
        self,
        path: str | Path,
    ) -> None:

        path = Path(path)

        if not path.exists():
            return

        with path.open(
            "r",
            encoding="utf-8",
        ) as handle:

            for line in handle:

                line = line.strip()

                if not line:
                    continue

                data = json.loads(line)

                self.add_binding(
                    prompt=data["prompt"],
                    ground_truth=data[
                        "ground_truth"
                    ],
                    label=data.get(
                        "label",
                        "",
                    ),
                    source=data.get(
                        "source",
                        "",
                    ),
                )

    # --------------------------------------------------------
    # RETRIEVE POTENTIAL PROMPTS
    # --------------------------------------------------------

    def retrieve(
        self,
        generated_text: str,
        limit: int = 5,
    ) -> List[dict]:

        generated_tokens = tokenize(
            generated_text
        )

        generated_bow = bag_of_words(
            generated_tokens
        )

        generated_vector = {
            token: float(count)
            for token, count
            in generated_bow.items()
        }

        results = []

        for binding in self.bindings:

            prompt_tokens = tokenize(
                binding.prompt
            )

            prompt_bow = bag_of_words(
                prompt_tokens
            )

            prompt_vector = {
                token: float(count)
                for token, count
                in prompt_bow.items()
            }

            symbolic = lexical_overlap(
                generated_tokens,
                prompt_tokens,
            )

            vector_similarity = (
                cosine_similarity(
                    generated_vector,
                    prompt_vector,
                )
            )

            score = (
                self.lexical_weight
                * symbolic
                +
                self.vector_weight
                * vector_similarity
            )

            results.append(
                {
                    "prompt":
                        binding.prompt,

                    "ground_truth":
                        binding.ground_truth,

                    "label":
                        binding.label,

                    "source":
                        binding.source,

                    "symbolic_overlap":
                        symbolic,

                    "vector_similarity":
                        vector_similarity,

                    "score":
                        score,
                }
            )

        results.sort(
            key=lambda item:
                item["score"],
            reverse=True,
        )

        return results[:limit]

    # --------------------------------------------------------
    # REBIND
    # --------------------------------------------------------

    def rebind(
        self,
        generated_text: str,
        candidate_limit: int = 5,
    ) -> RebindingResult:

        candidates = self.retrieve(
            generated_text,
            candidate_limit,
        )

        if not candidates:

            return RebindingResult(
                generated_text=generated_text,
                potential_prompts=[],
                rebound_prompt=None,
                rebound_ground_truth=None,
                rebound_label=None,
                grounding_score=0.0,
                ambiguity=1.0,
                semantic_overlap=0.0,
                symbolic_overlap=0.0,
                accepted=False,
                reason=(
                    "No ground-truth "
                    "bindings available."
                ),
            )

        best = candidates[0]

        best_score = best["score"]

        if len(candidates) > 1:

            second_score = (
                candidates[1]["score"]
            )

        else:
            second_score = 0.0

        margin = (
            best_score
            - second_score
        )

        if best_score > 0.0:

            ambiguity = max(
                0.0,
                min(
                    1.0,
                    1.0
                    - margin
                    / best_score,
                ),
            )

        else:
            ambiguity = 1.0

        accepted = (
            best_score
            >= self.acceptance_threshold
            and (
                len(candidates) == 1
                or margin
                >= self.ambiguity_margin
            )
        )

        if accepted:

            reason = (
                "Highest-scoring symbolic "
                "association accepted."
            )

        elif (
            best_score
            < self.acceptance_threshold
        ):

            reason = (
                "No potential prompt "
                "reached the grounding "
                "threshold."
            )

        else:

            reason = (
                "Potential prompts were "
                "too similar to establish "
                "an unambiguous rebinding."
            )

        return RebindingResult(
            generated_text=generated_text,

            potential_prompts=candidates,

            rebound_prompt=(
                best["prompt"]
                if accepted
                else None
            ),

            rebound_ground_truth=(
                best["ground_truth"]
                if accepted
                else None
            ),

            rebound_label=(
                best["label"]
                if accepted
                else None
            ),

            grounding_score=best_score,

            ambiguity=ambiguity,

            semantic_overlap=(
                best["vector_similarity"]
            ),

            symbolic_overlap=(
                best["symbolic_overlap"]
            ),

            accepted=accepted,

            reason=reason,
        )


# ============================================================
# SPARSE SYMBOL MANIFEST
# ============================================================

@dataclass
class SparseSymbolManifest:

    eos_token: str = "<eos>"
    unk_token: str = "<unk>"

    min_count: int = 1

    influence_tau: float = 0.5

    curve_name: str = "sigmoid"
    curve_k: float = 8.0
    curve_midpoint: float = 0.5

    unigram: Counter = field(
        default_factory=Counter
    )

    bigram: Dict[
        str,
        Counter
    ] = field(
        default_factory=lambda:
            defaultdict(Counter)
    )

    trigram: Dict[
        str,
        Counter
    ] = field(
        default_factory=lambda:
            defaultdict(Counter)
    )

    lexical_vectors: Dict[
        str,
        Dict[str, float]
    ] = field(
        default_factory=dict
    )

    influence_vectors: Dict[
        str,
        Dict[str, float]
    ] = field(
        default_factory=dict
    )

    vocabulary: List[str] = field(
        default_factory=list
    )

    finalized: bool = False

    # --------------------------------------------------------
    # INGESTION
    # --------------------------------------------------------

    def ingest_text(
        self,
        text: str,
    ) -> None:

        for sentence in split_sentences(
            text
        ):

            words = tokenize(
                sentence
            )

            if not words:
                continue

            sequence = (
                ["<bos>", "<bos>"]
                + words
                + [self.eos_token]
            )

            self.add_sequence_words(
                sequence
            )

    def add_sequence_words(
        self,
        sequence: List[str],
    ) -> None:

        if len(sequence) < 3:
            return

        for token in sequence:
            self.unigram[token] += 1

        for left, right in zip(
            sequence,
            sequence[1:],
        ):

            self.bigram[left][
                right
            ] += 1

        for a, b, c in zip(
            sequence,
            sequence[1:],
            sequence[2:],
        ):

            self.trigram[
                f"{a}\t{b}"
            ][c] += 1

        self.finalized = False

    # --------------------------------------------------------
    # VOCABULARY
    # --------------------------------------------------------

    def register_vocabulary(
        self,
    ) -> None:

        self.vocabulary = sorted(
            token
            for token, count
            in self.unigram.items()
            if count >= self.min_count
        )

        if self.unk_token not in (
            self.vocabulary
        ):

            self.vocabulary.append(
                self.unk_token
            )

    # --------------------------------------------------------
    # LEXICAL VECTORS
    # --------------------------------------------------------

    def update_intrinsics(
        self,
    ) -> None:

        self.register_vocabulary()

        token_contexts = defaultdict(
            Counter
        )

        for context, counts in (
            self.bigram.items()
        ):

            for token, count in (
                counts.items()
            ):

                token_contexts[token][
                    context
                ] += count

        self.lexical_vectors = {}

        for token in self.vocabulary:

            counts = token_contexts.get(
                token,
                Counter(),
            )

            total = sum(counts.values())

            if total == 0:
                total = 1

            self.lexical_vectors[
                token
            ] = {
                context:
                    count / total
                for context, count
                in counts.items()
            }

    # --------------------------------------------------------
    # INFLUENCE
    # --------------------------------------------------------

    def build_influence_vectors(
        self,
    ) -> None:

        self.influence_vectors = {}

        for source in self.vocabulary:

            source_vector = (
                self.lexical_vectors.get(
                    source,
                    {},
                )
            )

            scores = {}

            for target in self.vocabulary:

                if source == target:
                    continue

                target_vector = (
                    self.lexical_vectors.get(
                        target,
                        {},
                    )
                )

                similarity = (
                    cosine_similarity(
                        source_vector,
                        target_vector,
                    )
                )

                if (
                    similarity
                    >= self.influence_tau
                ):

                    scores[target] = (
                        similarity
                    )

            self.influence_vectors[
                source
            ] = scores

    # --------------------------------------------------------
    # FINALIZE
    # --------------------------------------------------------

    def finalize(self) -> None:

        self.update_intrinsics()
        self.build_influence_vectors()

        self.finalized = True

    # --------------------------------------------------------
    # BACKOFF
    # --------------------------------------------------------

    def backoff_distributions(
        self,
        previous_token: str,
        previous_previous_token:
            str | None = None,
    ) -> Dict[str, float]:

        if (
            previous_previous_token
            is not None
        ):

            key = (
                f"{previous_previous_token}"
                f"\t{previous_token}"
            )

            counts = self.trigram.get(
                key
            )

            if counts:
                return self._normalize_counts(
                    counts
                )

        counts = self.bigram.get(
            previous_token
        )

        if counts:
            return self._normalize_counts(
                counts
            )

        return self._normalize_counts(
            self.unigram
        )

    @staticmethod
    def _normalize_counts(
        counts: Counter,
    ) -> Dict[str, float]:

        total = sum(counts.values())

        if total == 0:
            return {}

        return {
            token:
                count / total
            for token, count
            in counts.items()
        }

    # --------------------------------------------------------
    # PROMPT CONTEXT
    # --------------------------------------------------------

    def resolve_prompt_context(
        self,
        prompt: str,
    ) -> Tuple[str, str | None]:

        tokens = tokenize(prompt)

        if not tokens:
            return "<bos>", None

        previous = tokens[-1]

        previous_previous = (
            tokens[-2]
            if len(tokens) >= 2
            else None
        )

        return (
            previous,
            previous_previous,
        )

    # --------------------------------------------------------
    # CURVE
    # --------------------------------------------------------

    def curve_weight(
        self,
        p_eos: float,
    ) -> float:

        p_eos = min(
            1.0,
            max(
                0.0,
                p_eos,
            ),
        )

        if self.curve_name == "linear":

            return 1.0 - p_eos

        if self.curve_name == "inverse":

            return 1.0 / (
                1.0 + p_eos
            )

        if self.curve_name == "sigmoid":

            z = (
                self.curve_k
                * (
                    p_eos
                    - self.curve_midpoint
                )
            )

            return 1.0 / (
                1.0
                + math.exp(z)
            )

        raise ValueError(
            f"Unknown curve: "
            f"{self.curve_name}"
        )

    # --------------------------------------------------------
    # NEXT TOKEN SCORING
    # --------------------------------------------------------

    def score_next_token(
        self,
        prompt: str,
        candidate_limit: int = 64,
    ) -> Dict[str, float]:

        if not self.finalized:
            self.finalize()

        previous, previous_previous = (
            self.resolve_prompt_context(
                prompt
            )
        )

        base = self.backoff_distributions(
            previous,
            previous_previous,
        )

        if not base:
            return {}

        candidates = sorted(
            base,
            key=base.get,
            reverse=True,
        )[:candidate_limit]

        similarities = {}

        source = self.lexical_vectors.get(
            previous,
            {},
        )

        for token in candidates:

            similarities[token] = (
                cosine_similarity(
                    source,
                    self.lexical_vectors.get(
                        token,
                        {},
                    ),
                )
            )

        influences = {
            token:
                self.influence_vectors.get(
                    previous,
                    {},
                ).get(
                    token,
                    0.0,
                )
            for token in candidates
        }

        p_eos = base.get(
            self.eos_token,
            0.0,
        )

        weight = self.curve_weight(
            p_eos
        )

        scores = {}

        for token in candidates:

            score = (
                safe_log(
                    base[token]
                )
                +
                weight
                * 0.35
                * similarities.get(
                    token,
                    0.0,
                )
                +
                weight
                * 0.65
                * influences.get(
                    token,
                    0.0,
                )
            )

            scores[token] = score

        return scores

    # --------------------------------------------------------
    # PROBABILITIES
    # --------------------------------------------------------

    def probabilities(
        self,
        prompt: str,
        temperature: float = 1.0,
        candidate_limit: int = 64,
    ) -> Dict[str, float]:

        scores = self.score_next_token(
            prompt,
            candidate_limit,
        )

        if not scores:
            return {}

        temperature = max(
            temperature,
            1e-5,
        )

        scaled = {
            token:
                score / temperature
            for token, score
            in scores.items()
        }

        maximum = max(
            scaled.values()
        )

        exponentials = {
            token:
                math.exp(
                    score - maximum
                )
            for token, score
            in scaled.items()
        }

        total = sum(
            exponentials.values()
        )

        return {
            token:
                value / total
            for token, value
            in exponentials.items()
        }

    # --------------------------------------------------------
    # SAMPLING
    # --------------------------------------------------------

    def sample_next(
        self,
        prompt: str,
        temperature: float = 0.8,
        top_k: int = 20,
    ) -> str:

        probabilities = self.probabilities(
            prompt,
            temperature,
            max(top_k, 1),
        )

        if not probabilities:
            return self.eos_token

        items = sorted(
            probabilities.items(),
            key=lambda item:
                item[1],
            reverse=True,
        )[:top_k]

        tokens = [
            token
            for token, _
            in items
        ]

        weights = [
            weight
            for _, weight
            in items
        ]

        return random.choices(
            tokens,
            weights=weights,
            k=1,
        )[0]

    # --------------------------------------------------------
    # GENERATE
    # --------------------------------------------------------

    def generate(
        self,
        prompt: str,
        max_new_tokens: int = 50,
        temperature: float = 0.8,
        top_k: int = 20,
    ) -> str:

        generated = tokenize(
            prompt
        )

        for _ in range(
            max_new_tokens
        ):

            current_prompt = (
                " ".join(generated)
            )

            token = self.sample_next(
                current_prompt,
                temperature,
                top_k,
            )

            if token == self.eos_token:
                break

            generated.append(token)

        return self.detokenize(
            generated
        )

    # --------------------------------------------------------
    # DETOKENIZE
    # --------------------------------------------------------

    @staticmethod
    def detokenize(
        tokens: List[str],
    ) -> str:

        text = " ".join(tokens)

        text = re.sub(
            r"\s+([.,!?;:)\]}])",
            r"\1",
            text,
        )

        text = re.sub(
            r"([(\[{])\s+",
            r"\1",
            text,
        )

        return text

    # --------------------------------------------------------
    # SERIALIZATION
    # --------------------------------------------------------

    def to_dict(self) -> dict:

        return {
            "eos_token":
                self.eos_token,

            "unk_token":
                self.unk_token,

            "min_count":
                self.min_count,

            "influence_tau":
                self.influence_tau,

            "curve_name":
                self.curve_name,

            "curve_k":
                self.curve_k,

            "curve_midpoint":
                self.curve_midpoint,

            "unigram":
                dict(self.unigram),

            "bigram": {
                key: dict(value)
                for key, value
                in self.bigram.items()
            },

            "trigram": {
                key: dict(value)
                for key, value
                in self.trigram.items()
            },

            "lexical_vectors":
                self.lexical_vectors,

            "influence_vectors":
                self.influence_vectors,

            "vocabulary":
                self.vocabulary,

            "finalized":
                self.finalized,
        }

    @classmethod
    def from_dict(
        cls,
        data: dict,
    ) -> "SparseSymbolManifest":

        model = cls(
            eos_token=data[
                "eos_token"
            ],
            unk_token=data[
                "unk_token"
            ],
            min_count=data[
                "min_count"
            ],
            influence_tau=data[
                "influence_tau"
            ],
            curve_name=data[
                "curve_name"
            ],
            curve_k=data[
                "curve_k"
            ],
            curve_midpoint=data[
                "curve_midpoint"
            ],
        )

        model.unigram = Counter(
            data["unigram"]
        )

        model.bigram = defaultdict(
            Counter,
            {
                key: Counter(value)
                for key, value
                in data["bigram"].items()
            },
        )

        model.trigram = defaultdict(
            Counter,
            {
                key: Counter(value)
                for key, value
                in data["trigram"].items()
            },
        )

        model.lexical_vectors = data[
            "lexical_vectors"
        ]

        model.influence_vectors = data[
            "influence_vectors"
        ]

        model.vocabulary = data[
            "vocabulary"
        ]

        model.finalized = data[
            "finalized"
        ]

        return model

    def save_json(
        self,
        path: str | Path,
    ) -> None:

        Path(path).write_text(
            json.dumps(
                self.to_dict(),
                indent=2,
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )

    @classmethod
    def load_json(
        cls,
        path: str | Path,
    ) -> "SparseSymbolManifest":

        data = json.loads(
            Path(path).read_text(
                encoding="utf-8",
            )
        )

        return cls.from_dict(data)


# ============================================================
# MODEL TRAINING
# ============================================================

def train_model() -> SparseSymbolManifest:

    corpus = Path(
        CORPUS_PATH
    )

    if not corpus.exists():

        raise FileNotFoundError(
            f"Corpus not found: "
            f"{CORPUS_PATH}"
        )

    print()
    print("=== TRAINING ===")

    text = corpus.read_text(
        encoding="utf-8"
    )

    model = SparseSymbolManifest(
        curve_name=CURVE_NAME,
        curve_k=CURVE_K,
        curve_midpoint=CURVE_MIDPOINT,
        min_count=MIN_COUNT,
        influence_tau=INFLUENCE_TAU,
    )

    model.ingest_text(text)
    model.finalize()

    model.save_json(
        MODEL_PATH
    )

    print(
        f"Saved: {MODEL_PATH}"
    )

    print(
        f"Vocabulary: "
        f"{len(model.vocabulary)}"
    )

    print(
        f"Unigrams: "
        f"{len(model.unigram)}"
    )

    print(
        f"Bigrams: "
        f"{len(model.bigram)}"
    )

    print(
        f"Trigrams: "
        f"{len(model.trigram)}"
    )

    return model


# ============================================================
# CHINESE ROOM DISPLAY
# ============================================================

def display_rebinding(
