static void rect(
    HDC dc,
    int x,
    int y,
    int w,
    int h,
    COLORREF color
)
{
    HBRUSH brush = CreateSolidBrush(color);

    RECT r;
    r.left   = x;
    r.top    = y;
    r.right  = x + w;
    r.bottom = y + h;

    FillRect(dc, &r, brush);

    DeleteObject(brush);
}


static void outline(
    HDC dc,
    int x,
    int y,
    int w,
    int h,
    COLORREF color
)
{
    HPEN pen = CreatePen(
        PS_SOLID,
        1,
        color
    );

    HGDIOBJ old = SelectObject(
        dc,
        pen
    );

    Rectangle(
        dc,
        x,
        y,
        x + w,
        y + h
    );

    SelectObject(
        dc,
        old
    );

    DeleteObject(pen);
}


static void text(
    HDC dc,
    int x,
    int y,
    const char *s,
    COLORREF color,
    int size
)
{
    HFONT font = CreateFontA(
        size,
        0,
        0,
        0,
        FW_NORMAL,
        FALSE,
        FALSE,
        FALSE,
        DEFAULT_CHARSET,
        OUT_DEFAULT_PRECIS,
        CLIP_DEFAULT_PRECIS,
        CLEARTYPE_QUALITY,
        DEFAULT_PITCH,
        "Segoe UI"
    );

    HGDIOBJ old = SelectObject(
        dc,
        font
    );

    SetBkMode(
        dc,
        TRANSPARENT
    );

    SetTextColor(
        dc,
        color
    );

    TextOutA(
        dc,
        x,
        y,
        s,
        (int)strlen(s)
    );

    SelectObject(
        dc,
        old
    );

    DeleteObject(font);
}


