static int init_directx(void)
{
    RECT r;

    GetClientRect(
        hwnd,
        &r
    );

    screen_w = r.right - r.left;
    screen_h = r.bottom - r.top;

    DXGI_SWAP_CHAIN_DESC sd;

    ZeroMemory(
        &sd,
        sizeof(sd)
    );

    sd.BufferCount = 2;

    sd.BufferDesc.Width =
        screen_w;

    sd.BufferDesc.Height =
        screen_h;

    sd.BufferDesc.Format =
        DXGI_FORMAT_R8G8B8A8_UNORM;

    sd.BufferUsage =
        DXGI_USAGE_RENDER_TARGET_OUTPUT;

    sd.OutputWindow =
        hwnd;

    sd.SampleDesc.Count = 1;

    sd.Windowed = TRUE;

    sd.SwapEffect =
        DXGI_SWAP_EFFECT_DISCARD;

    D3D_FEATURE_LEVEL level;

    HRESULT hr =
        D3D11CreateDeviceAndSwapChain(
            NULL,
            D3D_DRIVER_TYPE_HARDWARE,
            NULL,
            0,
            NULL,
            0,
            D3D11_SDK_VERSION,
            &sd,
            &swapchain,
            &device,
            &level,
            &context
        );

    if (FAILED(hr))
    {
        MessageBoxA(
            hwnd,
            "DirectX 11 initialisation failed.",
            "Error",
            MB_ICONERROR
        );

        return 0;
    }

    ID3D11Texture2D *backbuffer = NULL;

    hr = swapchain->GetBuffer(
        0,
        __uuidof(ID3D11Texture2D),
        (void **)&backbuffer
    );

    if (FAILED(hr))
        return 0;

    hr =
        device->CreateRenderTargetView(
            (ID3D11Resource *)backbuffer,
            NULL,
            &render_target
        );

    backbuffer->Release();

    if (FAILED(hr))
        return 0;

    context->OMSetRenderTargets(
        1,
        &render_target,
        NULL
    );

    return 1;
}


/* ============================================================
   CLEANUP
   ============================================================ */

static void shutdown_directx(void)
{
    if (render_target)
        render_target->Release();

    if (swapchain)
        swapchain->Release();

    if (context)
        context->Release();

    if (device)
        device->Release();
}


/* ============================================================
   FULLSCREEN
   ============================================================ */

static void toggle_fullscreen(void)
{
    static int fullscreen = 1;

    fullscreen = !fullscreen;

    if (fullscreen)
    {
        SetWindowLong(
            hwnd,
            GWL_STYLE,
            WS_POPUP
        );

        SetWindowPos(
            hwnd,
            HWND_TOP,
            0,
            0,
            GetSystemMetrics(SM_CXSCREEN),
            GetSystemMetrics(SM_CYSCREEN),
            SWP_SHOWWINDOW
        );
    }
    else
    {
        SetWindowLong(
            hwnd,
            GWL_STYLE,
            WS_OVERLAPPEDWINDOW
        );

        SetWindowPos(
            hwnd,
            HWND_TOP,
            100,
            100,
            1280,
            720,
            SWP_SHOWWINDOW
        );
    }
}


/* ============================================================
   INPUT
   ============================================================ */

static void handle_click(
    int x,
    int y
)
{
    int taskbar_y =
        screen_h - 56;

    /* Start button */

    if (
        x >= 10 &&
        x <= 60 &&
        y >= taskbar_y &&
        y <= screen_h
    )
    {
        start_open =
            !start_open;

        return;
    }

    /* Explorer taskbar button */

    if (
        x >= 285 &&
        x <= 440 &&
        y >= taskbar_y &&
        y <= screen_h
    )
    {
        explorer_open = 1;
        start_open = 0;

        return;
    }

    /* Close Explorer */

    if (
        explorer_open &&
        x > screen_w - 220 &&
        y > 90 &&
        y < 150
    )
    {
        explorer_open = 0;
        return;
    }

    /* Desktop Explorer icon */

    if (
        !explorer_open &&
        x >= 20 &&
        x <= 110 &&
        y >= 85 &&
        y <= 180
    )
    {
        explorer_open = 1;
        return;
    }

    /* Clicking desktop closes Start */

    start_open = 0;
}


/* ============================================================
   WINDOW PROCEDURE
   ============================================================ */

static LRESULT CALLBACK wndproc(
    HWND h,
    UINT msg,
    WPARAM w,
    LPARAM l
)
{
    switch (msg)
    {
        case WM_DESTROY:

            running = 0;

            PostQuitMessage(0);

            return 0;


        case WM_KEYDOWN:

            if (w == VK_ESCAPE)
            {
                running = 0;

                PostQuitMessage(0);

                return 0;
            }

            if (w == VK_F11)
            {
                toggle_fullscreen();

                return 0;
            }

            break;


        case WM_LBUTTONDOWN:

            handle_click(
                LOWORD(l),
                HIWORD(l)
            );

            return 0;


        case WM_MOUSEMOVE:

            mouse_x = LOWORD(l);
            mouse_y = HIWORD(l);

            return 0;


        case WM_SIZE:

            screen_w =
                LOWORD(l);

            screen_h =
                HIWORD(l);

            return 0;
    }

    return DefWindowProc(
        h,
        msg,
        w,
        l
    );
}


/* ============================================================
   ENTRY POINT
   ============================================================ */

int WINAPI WinMain(
    HINSTANCE instance,
    HINSTANCE previous,
    LPSTR command_line,
    int show
)
{
    (void)previous;
    (void)command_line;

    WNDCLASSA wc;

    ZeroMemory(
        &wc,
        sizeof(wc)
    );

    wc.style =
        CS_HREDRAW |
        CS_VREDRAW;

    wc.lpfnWndProc =
        wndproc;

    wc.hInstance =
        instance;

    wc.hCursor =
        LoadCursor(
            NULL,
            IDC_ARROW
        );

    wc.lpszClassName =
        "DirectXExplorer";

    RegisterClassA(
        &wc
    );

    /* Start fullscreen. */

    screen_w =
        GetSystemMetrics(
            SM_CXSCREEN
        );

    screen_h =
        GetSystemMetrics(
            SM_CYSCREEN
        );

    hwnd = CreateWindowExA(
        0,
        "DirectXExplorer",
        "DirectX Explorer",
        WS_POPUP,
        0,
        0,
        screen_w,
        screen_h,
        NULL,
        NULL,
        instance,
        NULL
    );

    if (!hwnd)
        return 1;

    ShowWindow(
        hwnd,
        SW_SHOW
    );

    UpdateWindow(
        hwnd
    );

    if (!init_directx())
        return 1;

    /* ========================================================
       MAIN LOOP
       ======================================================== */

    MSG msg;

    ZeroMemory(
        &msg,
        sizeof(msg)
    );

    while (running)
    {
        while (
            PeekMessage(
                &msg,
                NULL,
                0,
                0,
                PM_REMOVE
            )
        )
        {
            TranslateMessage(
                &msg
            );

            DispatchMessage(
                &msg
            );
        }

        draw_frame();
    }

    shutdown_directx();

    return 0;
}
