### Build

With Visual Studio's **x64 Native Tools Command Prompt**:

```bat
cl /O2 directx_explorer_taskbar.c /link d3d11.lib dxgi.lib user32.lib gdi32.lib
```

This gives you a fullscreen executable with:

- **DirectX 11 device + swap chain**
- fullscreen desktop
- taskbar
- Start menu
- Explorer window
- Explorer navigation pane
- address bar
- folders/drives
- desktop icons
- mouse interaction
- `F11` fullscreen toggle
- `ESC` exit

One caveat: the UI primitives are intentionally simple. The next step for a genuinely **Windows-shell-like DirectX explorer** would be to replace the GDI drawing layer with a proper DirectX 11 sprite/font renderer, then add an actual filesystem backend (`FindFirstFileA`/`FindNextFileA`) so the Explorer pane displays the real contents of `C:\`, rather than the demonstration folders.

Yep. Below is the upgraded version: **fullscreen DirectX 11 Explorer with a real Windows filesystem backend**. It enumerates the actual contents of `C:\`, supports directory navigation, double-clicking folders, going up, refresh, and a taskbar/Start interface.

It remains a standalone application rather than replacing `explorer.exe`.

```c
/*
    directx_explorer_taskbar.c

    Fullscreen DirectX 11 filesystem Explorer.

    Features
    --------
    - DirectX 11 window / swap chain
    - Fullscreen desktop
    - Taskbar
    - Start menu
    - Real filesystem enumeration
    - C:\ root
    - Directory navigation
    - Double-click folders
    - Double-click files -> ShellExecute
    - Back
    - Up
    - Refresh
    - Address bar
    - File/folder icons
    - Scrollable file list
    - F11 fullscreen toggle
    - ESC exits

    Build with MSVC:

        cl /O2 directx_explorer_taskbar.c ^
           /link d3d11.lib dxgi.lib user32.lib gdi32.lib shell32.lib gdi32.lib

    NOTE:
        The rendering layer uses GDI over a DirectX-owned window
        for simplicity. The DirectX device/swapchain are present
        and can subsequently be replaced with a native DX11
        renderer.
*/

#define WIN32_LEAN_AND_MEAN

#include <windows.h>
#include <d3d11.h>
#include <dxgi.h>
#include <shellapi.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* ============================================================
   CONFIGURATION
   ============================================================ */

#define MAX_ITEMS       4096
#define MAX_PATH_TEXT   32768
#define ITEM_HEIGHT     38

#define EXPLORER_X      150
#define EXPLORER_Y      70

#define TASKBAR_HEIGHT  58

/* ============================================================
   DIRECTX
   ============================================================ */

static HWND g_hwnd = NULL;

static ID3D11Device *g_device = NULL;
static ID3D11DeviceContext *g_context = NULL;
static IDXGISwapChain *g_swapchain = NULL;
static ID3D11RenderTargetView *g_target = NULL;

/* ============================================================
   APPLICATION STATE
   ============================================================ */

static int g_width = 1280;
static int g_height = 720;

static int g_running = 1;
static int g_fullscreen = 1;

static int g_start_open = 0;
static int g_explorer_open = 1;

static int g_mouse_x = 0;
static int g_mouse_y = 0;

static int g_scroll = 0;

static char g_current_path[MAX_PATH_TEXT] = "C:\\";

/* ============================================================
   FILE SYSTEM
   ============================================================ */

typedef struct
{
    char name[MAX_PATH];
    int is_directory;
    unsigned long long size;
} FileItem;

static FileItem g_items[MAX_ITEMS];
static int g_item_count = 0;

/* ============================================================
   COLORS
   ============================================================ */

#define C_DESKTOP       RGB(15,24,40)
#define C_TASKBAR       RGB(18,22,30)
#define C_WINDOW        RGB(27,31,40)
#define C_TITLE         RGB(31,36,47)
#define C_PANEL         RGB(21,25,33)
#define C_INPUT         RGB(37,43,54)
#define C_HOVER         RGB(48,59,76)
#define C_SELECTED      RGB(45,75,108)
#define C_BORDER        RGB(62,70,83)

#define C_TEXT          RGB(225,230,238)
#define C_TEXT2         RGB(165,175,190)
#define C_ACCENT        RGB(70,155,235)

#define C_FOLDER        RGB(226,181,72)
#define C_FILE          RGB(175,185,200)

/* ============================================================
   UTILITIES
   ============================================================ */

static void safe_copy(
    char *dst,
    size_t dst_size,
    const char *src
)
{
    if (!dst || dst_size == 0)
        return;

    strncpy(
        dst,
        src,
        dst_size - 1
    );

    dst[dst_size - 1] = 0;
}


static void join_path(
    char *out,
    size_t out_size,
    const char *base,
    const char *name
)
{
    if (strcmp(base, "\\") == 0)
    {
        snprintf(
            out,
            out_size,
            "\\%s",
            name
        );
    }
    else
    {
        snprintf(
            out,
            out_size,
            "%s\\%s",
            base,
            name
        );
    }
}


/* ============================================================
   FILESYSTEM ENUMERATION
   ============================================================ */

static int compare_items(
    const void *a,
    const void *b
)
{
    const FileItem *fa =
        (const FileItem *)a;

    const FileItem *fb =
        (const FileItem *)b;

    /*
        Directories first.
    */

    if (fa->is_directory != fb->is_directory)
        return fb->is_directory - fa->is_directory;

    return _stricmp(
        fa->name,
        fb->name
    );
}


static void enumerate_directory(void)
{
    g_item_count = 0;

    char search[MAX_PATH_TEXT];

    snprintf(
        search,
        sizeof(search),
        "%s\\*",
        g_current_path
    );

    WIN32_FIND_DATAA data;

    HANDLE h =
        FindFirstFileA(
            search,
            &data
        );

    if (h == INVALID_HANDLE_VALUE)
        return;

    do
    {
        if (
            strcmp(data.cFileName, ".") == 0 ||
            strcmp(data.cFileName, "..") == 0
        )
        {
            continue;
        }

        if (g_item_count >= MAX_ITEMS)
            break;

        FileItem *item =
            &g_items[g_item_count];

        safe_copy(
            item->name,
            sizeof(item->name),
            data.cFileName
        );

        item->is_directory =
            (data.dwFileAttributes &
             FILE_ATTRIBUTE_DIRECTORY) != 0;

        item->size =
            ((unsigned long long)data.nFileSizeHigh << 32)
            |
            data.nFileSizeLow;

        g_item_count++;

    }
    while (
        FindNextFileA(
            h,
            &data
        )
    );

    FindClose(h);

    qsort(
        g_items,
        g_item_count,
        sizeof(FileItem),
        compare_items
    );

    g_scroll = 0;
}


/* ============================================================
   NAVIGATION
   ============================================================ */

static void open_directory(
    const char *name
)
{
    char new_path[MAX_PATH_TEXT];

    join_path(
        new_path,
        sizeof(new_path),
        g_current_path,
        name
    );

    DWORD attributes =
        GetFileAttributesA(
            new_path
        );

    if (
        attributes != INVALID_FILE_ATTRIBUTES &&
        (attributes & FILE_ATTRIBUTE_DIRECTORY)
    )
    {
        safe_copy(
            g_current_path,
            sizeof(g_current_path),
            new_path
        );

        enumerate_directory();
    }
}


static void go_up(void)
{
    char temp[MAX_PATH_TEXT];

    safe_copy(
        temp,
        sizeof(temp),
        g_current_path
    );

    /*
        Remove trailing slash except for C:\
    */

    size_t len =
        strlen(temp);

    while (
        len > 0 &&
        (temp[len - 1] == '\\' ||
         temp[len - 1] == '/')
    )
    {
        if (len == 3)
            break;

        temp[--len] = 0;
    }

    char *slash =
        strrchr(
            temp,
            '\\'
        );

    if (!slash)
        return;

    /*
        Keep drive root.
    */

    if (slash == temp + 2)
    {
        temp[3] = 0;
    }
    else
    {
        *slash = 0;
    }

    safe_copy(
        g_current_path,
        sizeof(g_current_path),
        temp
    );

    enumerate_directory();
}


static void go_root(void)
{
    safe_copy(
        g_current_path,
        sizeof(g_current_path),
        "C:\\"
    );

    enumerate_directory();
}


/* ============================================================
   DRAWING
   ============================================================ */

static void fill_rect(
    HDC dc,
    int x,
    int y,
    int w,
    int h,
    COLORREF color
)
{
    RECT r;

    r.left = x;
    r.top = y;
    r.right = x + w;
    r.bottom = y + h;

    HBRUSH brush =
        CreateSolidBrush(color);

    FillRect(
        dc,
        &r,
        brush
    );

    DeleteObject(brush);
}


static void draw_border(
    HDC dc,
    int x,
    int y,
    int w,
    int h,
    COLORREF color
)
{
    HPEN pen =
        CreatePen(
            PS_SOLID,
            1,
            color
        );

    HGDIOBJ old =
        SelectObject(
            dc,
            pen
        );

    Rectangle(
        dc,
        x,
        y,
        x + w,
        y + h
    );

    SelectObject(
        dc,
        old
    );

    DeleteObject(pen);
}


static void draw_text(
    HDC dc,
    int x,
    int y,
    const char *str,
    COLORREF color,
    int size
)
{
    HFONT font =
        CreateFontA(
            size,
            0,
            0,
            0,
            FW_NORMAL,
            FALSE,
            FALSE,
            FALSE,
            DEFAULT_CHARSET,
            OUT_DEFAULT_PRECIS,
            CLIP_DEFAULT_PRECIS,
            CLEARTYPE_QUALITY,
            DEFAULT_PITCH,
            "Segoe UI"
        );

    HGDIOBJ old =
        SelectObject(
            dc,
            font
        );

    SetBkMode(
        dc,
        TRANSPARENT
    );

    SetTextColor(
        dc,
        color
    );

    TextOutA(
        dc,
        x,
        y,
        str,
        (int)strlen(str)
    );

    SelectObject(
        dc,
        old
    );

    DeleteObject(font);
}


/* ============================================================
   DESKTOP
   ============================================================ */

static void draw_desktop(HDC dc)
{
    fill_rect(
        dc,
        0,
        0,
        g_width,
        g_height,
        C_DESKTOP
    );

    /*
        Subtle desktop gradient.
    */

    for (
        int y = 0;
        y < g_height - TASKBAR_HEIGHT;
        y += 16
    )
    {
        int v =
            12 +
            (y * 15 /
             (g_height + 1));

        fill_rect(
            dc,
            0,
            y,
            g_width,
            16,
            RGB(
                10 + v / 2,
                18 + v / 2,
                30 + v
            )
        );
    }

    draw_text(
        dc,
        28,
        25,
        "DirectX Desktop",
        RGB(180,195,220),
        18
    );
}


/* ============================================================
   DESKTOP ICON
