{
    int hovered =
        g_mouse_x >= x &&
        g_mouse_x <= x + w &&
        g_mouse_y >= y &&
        g_mouse_y <= y + ITEM_HEIGHT;

    if (hovered)
    {
        fill_rect(
            dc,
