/* ============================================================
   DIRECTX INITIALISATION
   ============================================================ */

static int init_directx(void)
{
    RECT r;

    GetClientRect(
        g_hwnd,
        &r
    );

    g_width =
        r.right -
        r.left;

    g_height =
        r.bottom -
        r.top;

    DXGI_SWAP_CHAIN_DESC desc;

    ZeroMemory(
        &desc,
        sizeof(desc)
    );

    desc.BufferCount = 2;

    desc.BufferDesc.Width =
        g_width;

    desc.BufferDesc.Height =
        g_height;

    desc.BufferDesc.Format =
        DXGI_FORMAT_R8G8B8A8_UNORM;

    desc.BufferUsage =
        DXGI_USAGE_RENDER_TARGET_OUTPUT;

    desc.OutputWindow =
        g_hwnd;

    desc.SampleDesc.Count = 1;

    desc.Windowed = TRUE;

    desc.SwapEffect =
        DXGI_SWAP_EFFECT_DISCARD;

    D3D_FEATURE_LEVEL feature;

    HRESULT hr =
        D3D11CreateDeviceAndSwapChain(
            NULL,
            D3D_DRIVER_TYPE_HARDWARE,
            NULL,
            0,
            NULL,
            0,
            D3D11_SDK_VERSION,
            &desc,
            &g_swapchain,
            &g_device,
            &feature,
            &g_context
        );

    if (FAILED(hr))
    {
        MessageBoxA(
            g_hwnd,
            "Could not initialise DirectX 11.",
            "DirectX Explorer",
            MB_ICONERROR
        );

        return 0;
    }

    ID3D11Texture2D *backbuffer = NULL;

    hr =
        g_swapchain->GetBuffer(
            0,
            __uuidof(ID3D11Texture2D),
            (void **)&backbuffer
        );

    if (FAILED(hr))
        return 0;

    hr =
        g_device->CreateRenderTargetView(
            (ID3D11Resource *)backbuffer,
            NULL,
            &g_target
        );

    backbuffer->Release();

    if (FAILED(hr))
        return 0;

    g_context->OMSetRenderTargets(
        1,
        &g_target,
        NULL
    );

    return 1;
}


/* ============================================================
   DIRECTX CLEANUP
   ============================================================ */

static void shutdown_directx(void)
{
    if (g_target)
        g_target->Release();

    if (g_swapchain)
        g_swapchain->Release();

    if (g_context)
        g_context->Release();

    if (g_device)
        g_device->Release();

    g_target = NULL;
    g_swapchain = NULL;
    g_context = NULL;
    g_device = NULL;
}


