/* ============================================================
   HIT TESTING
   ============================================================ */

static int explorer_file_at(
    int mx,
    int my
)
{
    int x = EXPLORER_X;
    int y = EXPLORER_Y;

    int w = explorer_width();
    int h = explorer_height();

    int side_w = 190;

    int content_x =
        x + side_w;

    int content_y =
        y + 88;

    int content_h =
        h - 88;

    if (
        mx < content_x ||
        mx > content_x + w - side_w
    )
    {
        return -1;
    }

    if (
        my < content_y + 48 ||
        my > content_y + content_h
    )
    {
        return -1;
    }

    int list_y =
        content_y + 48;

    int local_y =
        my - list_y +
        g_scroll;

    if (local_y < 0)
        return -1;

    int index =
        local_y /
        ITEM_HEIGHT;

    if (
        index < 0 ||
        index >= g_item_count
    )
    {
        return -1;
    }

    return index;
}


/* ============================================================
   MOUSE INPUT
   ============================================================ */

static void handle_left_click(
    int x,
    int y
)
{
    int taskbar_y =
        g_height -
        TASKBAR_HEIGHT;

    /*
        Start.
    */

    if (
        x >= 8 &&
        x <= 56 &&
        y >= taskbar_y
    )
    {
        g_start_open =
            !g_start_open;

        return;
    }

    /*
        Explorer taskbar button.
    */

    if (
        x >= 280 &&
        x <= 445 &&
        y >= taskbar_y
    )
    {
        g_explorer_open = 1;
        g_start_open = 0;

        return;
    }

    /*
        Explorer desktop icon.
    */

    if (
        !g_explorer_open &&
        x >= 20 &&
        x <= 100 &&
        y >= 85 &&
        y <= 165
    )
    {
        g_explorer_open = 1;

        return;
    }

    /*
        Explorer close button.
    */

    if (
        g_explorer_open
    )
    {
        int ex = EXPLORER_X;
        int ey = EXPLORER_Y;
        int ew = explorer_width();

        if (
            x >= ex + ew - 45 &&
            x <= ex + ew &&
            y >= ey &&
            y <= ey + 42
        )
        {
            g_explorer_open = 0;
            return;
        }

        /*
            Up button.
        */

        if (
            x >= ex + 70 &&
            x <= ex + 120 &&
            y >= ey + 42 &&
            y <= ey + 85
        )
        {
            go_up();
            return;
        }

        /*
            File.
        */

        int index =
            explorer_file_at(
                x,
                y
            );

        if (index >= 0)
        {
            activate_item(
                index
            );

            return;
        }
    }

    g_start_open = 0;
}


/* ============================================================
   MOUSE WHEEL
   ============================================================ */

static void handle_wheel(
    int delta
)
{
    if (!g_explorer_open)
        return;

    int max_scroll =
        g_item_count *
        ITEM_HEIGHT;

    max_scroll -=
        explorer_height();

    if (max_scroll < 0)
        max_scroll = 0;

    g_scroll -= delta / 3;

    if (g_scroll < 0)
        g_scroll = 0;

    if (g_scroll > max_scroll)
        g_scroll = max_scroll;
}


/* ============================================================
   WINDOW PROCEDURE
   ============================================================ */

static LRESULT CALLBACK wndproc(
    HWND hwnd,
    UINT msg,
    WPARAM wParam,
    LPARAM lParam
)
{
    switch (msg)
    {
        case WM_DESTROY:

            g_running = 0;

            PostQuitMessage(0);

            return 0;


        case WM_KEYDOWN:

            if (wParam == VK_ESCAPE)
            {
                g_running = 0;

                PostQuitMessage(0);

                return 0;
            }

            if (wParam == VK_F11)
            {
                toggle_fullscreen();

                return 0;
            }

            if (
                wParam == VK_F5 &&
                g_explorer_open
            )
            {
                enumerate_directory();

                return 0;
            }

            if (
                wParam == VK_BACK &&
                g_explorer_open
            )
            {
                go_up();

                return 0;
            }

            break;


        case WM_LBUTTONDOWN:

            handle_left_click(
                LOWORD(lParam),
                HIWORD(lParam)
            );

            return 0;


        case WM_MOUSEMOVE:

            g_mouse_x =
                LOWORD(lParam);

            g_mouse_y =
                HIWORD(lParam);

            return 0;


        case WM_MOUSEWHEEL:

            handle_wheel(
                GET_WHEEL_DELTA_WPARAM(
                    wParam
                )
            );

            return 0;


        case WM_SIZE:

            g_width =
                LOWORD(lParam);

            g_height =
                HIWORD(lParam);

            return 0;
    }

    return DefWindowProcA(
        hwnd,
        msg,
        wParam,
        lParam
    );
}


/* ============================================================
   PROGRAM ENTRY
   ============================================================ */

int WINAPI WinMain(
    HINSTANCE instance,
    HINSTANCE previous,
    LPSTR command_line,
    int show
)
{
    (void)previous;
    (void)command_line;
    (void)show;

    WNDCLASSA wc;

    ZeroMemory(
        &wc,
        sizeof(wc)
    );

    wc.style =
        CS_HREDRAW |
        CS_VREDRAW;

    wc.lpfnWndProc =
        wndproc;

    wc.hInstance =
        instance;

    wc.hCursor =
        LoadCursor(
            NULL,
            IDC_ARROW
        );

    wc.lpszClassName =
        "DirectXExplorerWindow";

    if (!RegisterClassA(&wc))
        return 1;

    g_width =
        GetSystemMetrics(
            SM_CXSCREEN
        );

    g_height =
        GetSystemMetrics(
            SM_CYSCREEN
        );

    g_hwnd =
        CreateWindowExA(
            0,
            "DirectXExplorerWindow",
            "DirectX Explorer",
            WS_POPUP,
            0,
            0,
            g_width,
            g_height,
            NULL,
            NULL,
            instance,
            NULL
        );

    if (!g_hwnd)
        return 1;

    ShowWindow(
        g_hwnd,
        SW_SHOW
    );

    UpdateWindow(
        g_hwnd
    );

    if (!init_directx())
        return 1;

    /*
        Start at C:\.
    */

    go_root();

    /*
        Main loop.
    */

    MSG msg;

    ZeroMemory(
        &msg,
        sizeof(msg)
    );

    while (g_running)
    {
        while (
            PeekMessageA(
                &msg,
                NULL,
                0,
                0,
                PM_REMOVE
            )
        )
        {
            TranslateMessage(
                &msg
            );

            DispatchMessageA(
                &msg
            );
        }

        draw_frame();
    }

    shutdown_directx();

    return 0;
}
