# ============================================================
# BASIC HELPERS
# ============================================================

def clean_text(value) -> str:

    if value is None:
        return ""

    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass

    text = str(value)

    text = (
        text
        .replace("\n", " ")
        .replace("\r", " ")
        .replace("\t", " ")
    )

    return re.sub(
        r"\s+",
        " ",
        text,
    ).strip()


def number(value):

    if value is None:
        return None

    if isinstance(value, bool):
        return None

    if isinstance(value, (int, float)):

        try:
            if not math.isfinite(float(value)):
                return None
        except Exception:
            return None

        return float(value)

    text = clean_text(value)

    if not text:
        return None

    if text.lower() in {
        "-",
        "—",
        "–",
        "..",
        "...",
        "n.p.",
        "np",
        "n/a",
        "na",
    }:
        return None

    negative = (
        text.startswith("(")
        and text.endswith(")")
    )

    text = (
        text
        .replace(",", "")
        .replace("$", "")
        .replace("%", "")
    )

    match = re.search(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)",
        text,
    )

    if not match:
        return None

    value = float(
        match.group(0)
    )

    if negative:
        value = -value

    return value


def finite(value) -> bool:

    if value is None:
        return False

    try:
        return math.isfinite(
            float(value)
        )
    except Exception:
        return False


def safe_filename(name: str) -> str:

    name = re.sub(
        r'[<>:"/\\|?*]+',
        "_",
        name,
    )

    name = re.sub(
        r"\s+",
        "_",
        name,
    )

    return name[:180]


def json_clean(value):

    if isinstance(value, float):

        if not math.isfinite(value):
            return None

        return value

    if isinstance(value, dict):

        return {
            str(k): json_clean(v)
            for k, v in value.items()
        }

    if isinstance(value, list):

        return [
            json_clean(v)
            for v in value
        ]

    return value


def save_json(
    filename,
    data,
):

    path = OUTPUT_DIR / filename

    with path.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            json_clean(data),
            f,
            indent=2,
            ensure_ascii=False,
        )

    print(
        f"Saved: {path}"
    )


# ============================================================
# ABS DOWNLOADER
# ============================================================

class ABSDownloader:

    def __init__(
        self,
        force=False,
    ):

        self.force = force

        self.session = (
            requests.Session()
        )

        self.session.headers.update(
            HEADERS
        )

    # --------------------------------------------------------
    # Discover official XLSX links
    # --------------------------------------------------------

    def discover_xlsx(
        self,
        release_url,
    ):

        response = (
            self.session.get(
                release_url,
                timeout=60,
            )
        )

        response.raise_for_status()

        html = response.text

        candidates = []

        patterns = [

            r'href=["\']([^"\']+\.xlsx'
            r'(?:\?[^"\']*)?)["\']',

            r'(https?://[^"\'>\s]+\.xlsx'
            r'(?:\?[^"\'>\s]*)?)',

            r'((?:/|https?://)[^"\'>\s]+\.xlsx)',
        ]

        for pattern in patterns:

            candidates.extend(
                re.findall(
                    pattern,
                    html,
                    flags=re.IGNORECASE,
                )
            )

        links = []

        for raw in candidates:

            raw = raw.replace(
                "&amp;",
                "&",
            )

            url = urljoin(
                release_url,
                raw,
            )

            parsed = urlparse(
                url
            )

            if parsed.scheme not in {
                "http",
                "https",
            }:
                continue

            if parsed.netloc.lower() not in {
                "www.abs.gov.au",
                "abs.gov.au",
            }:
                continue

            if ".xlsx" not in (
                parsed.path.lower()
            ):
                continue

            if url not in links:
                links.append(url)

        return links

    # --------------------------------------------------------
    # Download
    # --------------------------------------------------------

    def download(
        self,
        url,
    ):

        filename = (
            urlparse(url)
            .path
            .split("/")[-1]
        )

        filename = safe_filename(
            filename
        )

        if not filename.lower().endswith(
            ".xlsx"
        ):
            filename += ".xlsx"

        destination = (
            DOWNLOAD_DIR / filename
        )

        if (
            destination.exists()
            and destination.stat().st_size > 0
            and not self.force
        ):

            print(
                f"  cached: {filename}"
            )

            return destination

        print(
            f"  downloading: {filename}"
        )

        response = (
            self.session.get(
                url,
                timeout=180,
                stream=True,
            )
        )

        response.raise_for_status()

        temporary = (
            destination.with_suffix(
                ".part"
            )
        )

        with temporary.open(
            "wb"
        ) as f:

            for chunk in response.iter_content(
                chunk_size=1024 * 1024
            ):

                if chunk:
                    f.write(chunk)

        if (
            not temporary.exists()
            or temporary.stat().st_size == 0
        ):

            raise RuntimeError(
                "Downloaded ABS XLSX is empty: "
                + url
            )

        temporary.replace(
            destination
        )

        time.sleep(
            0.4
        )

        return destination

    # --------------------------------------------------------
    # Dataset
    # --------------------------------------------------------

    def download_dataset(
        self,
        dataset,
        url,
    ):

        print(
            "\n" + "=" * 70
        )

        print(
            f"ABS DATASET: {dataset.upper()}"
        )

        print(
            "=" * 70
        )

        print(
            url
        )

        links = self.discover_xlsx(
            url
        )

        if not links:

            raise RuntimeError(
                "No official ABS XLSX files "
                f"found at {url}"
            )

        print(
            f"Found {len(links)} XLSX file(s)."
        )

        files = []

        for link in links:

            try:

                files.append(
                    self.download(
                        link
                    )
                )

            except Exception as exc:

                print(
                    f"  download failed: "
                    f"{exc}"
                )

        return files

    # --------------------------------------------------------
    # Everything
    # --------------------------------------------------------

    def download_all(self):

        result = {}

        for dataset, url in (
            ABS_RELEASES.items()
        ):

            try:

                result[dataset] = (
                    self.download_dataset(
                        dataset,
                        url,
                    )
                )

            except Exception as exc:

                print(
                    f"\nABS {dataset} failed:"
                )

                print(
                    f"  {exc}"
                )

                result[dataset] = []

        return result


