def workbook_sheets(
    path: Path,
):

    excel = pd.ExcelFile(
        path,
        engine="openpyxl",
    )

    return list(
        excel.sheet_names
    )


def read_sheet(
    path: Path,
    sheet,
):

    return pd.read_excel(
        path,
        sheet_name=sheet,
        header=None,
        engine="openpyxl",
    )


def state_aliases(
    code,
):

    aliases = [
        STATES[code],
        code,
    ]

    if code == "ACT":
        aliases += [
            "Australian Capital Territory",
            "A.C.T.",
        ]

    if code == "NT":
        aliases += [
            "Northern Territory",
            "N.T.",
        ]

    return [
        x.lower()
        for x in aliases
    ]


def find_state_rows(
    df,
    code,
):

    aliases = state_aliases(
        code
    )

    matches = []

    for row_index in range(
        len(df)
    ):

        row_text = " ".join(
            clean_text(x).lower()
            for x in df.iloc[
                row_index
            ].tolist()
        )

        for alias in aliases:

            if re.search(
                rf"(?<![a-z])"
                rf"{re.escape(alias)}"
                rf"(?![a-z])",
                row_text,
            ):

                matches.append(
                    row_index
                )

                break

    return matches


def make_headers(
    df,
    rows=15,
):

    labels = {}

    rows = min(
        rows,
        len(df),
    )

    for col in range(
        len(df.columns)
    ):

        pieces = []

        for row in range(
            rows
        ):

            text = clean_text(
                df.iloc[
                    row,
                    col,
                ]
            )

            if text:
                pieces.append(
                    text
                )

        pieces = list(
            dict.fromkeys(
                pieces
            )
        )

        labels[col] = (
            " | ".join(
                pieces
            )
        )

    return labels


def header_score(
    header,
    required,
    optional=None,
    forbidden=None,
):

    text = header.lower()

    if forbidden:

        for word in forbidden:

            if word.lower() in text:
                return -999999

    for word in required:

        if word.lower() not in text:
            return -999999

    score = (
        100 * len(required)
    )

    if optional:

        for word in optional:

            if word.lower() in text:
                score += 10

    return score


def find_series(
    workbook: Path,
    state,
    required,
    optional=None,
    forbidden=None,
    preferred_sheets=None,
):

    best = None
    best_score = -999999

    try:

        sheets = workbook_sheets(
            workbook
        )

    except Exception:

        return None

    if preferred_sheets:

        sheets = sorted(
            sheets,
            key=lambda sheet:
                -sum(
                    keyword.lower()
                    in sheet.lower()
                    for keyword
                    in preferred_sheets
                ),
        )

    for sheet in sheets:

        try:

            df = read_sheet(
                workbook,
                sheet,
            )

        except Exception:

            continue

        state_rows = find_state_rows(
            df,
            state,
        )

        if not state_rows:
            continue

        headers = make_headers(
            df
        )

        for col, header in (
            headers.items()
        ):

            score = header_score(
                header,
                required,
                optional,
                forbidden,
            )

            if score <= best_score:
                continue

            for row in state_rows:

                if col >= len(
                    df.columns
                ):
                    continue

                value = number(
                    df.iloc[
                        row,
                        col,
                    ]
                )

                if value is None:
                    continue

                best_score = score

                best = {
                    "value": value,
                    "workbook":
                        workbook.name,
                    "sheet":
                        sheet,
                    "row":
                        int(row),
                    "column":
                        int(col),
                    "header":
                        header,
                    "score":
                        score,
                }

                break

    return best


