# DWELLINGS
# ============================================================

def parse_dwellings(
    files,
):

    result = {
        code: {
            "total_dwelling_value": None,
            "mean_dwelling_price": None,
            "dwelling_count": None,
            "sources": {},
        }
        for code in STATES
    }

    for code in STATES:

        for workbook in files:

            if result[code][
                "mean_dwelling_price"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "mean",
                        "price",
                    ],
                    optional=[
                        "dwelling",
                        "residential",
                    ],
                    forbidden=[
                        "median",
                    ],
                    preferred_sheets=[
                        "mean",
                        "price",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "mean_dwelling_price"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "mean_dwelling_price"
                    ] = match

            if result[code][
                "total_dwelling_value"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "total",
                        "value",
                    ],
                    optional=[
                        "dwelling",
                        "residential",
                    ],
                    preferred_sheets=[
                        "value",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "total_dwelling_value"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "total_dwelling_value"
                    ] = match

            if result[code][
                "dwelling_count"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "number",
                        "dwellings",
                    ],
                    optional=[
                        "residential",
                    ],
                    preferred_sheets=[
                        "number",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "dwelling_count"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "dwelling_count"
                    ] = match

    return result


