# ============================================================
# PPI
# ============================================================

def parse_ppi(
    files,
):

    result = {
        code: {
            "construction_price_index":
                None,
            "construction_quarterly_change":
                None,
            "construction_annual_change":
                None,
            "sources": {},
        }
        for code in STATES
    }

    for code in STATES:

        for workbook in files:

            if result[code][
                "construction_annual_change"
            ] is not None:

                break

            try:

                sheets = workbook_sheets(
                    workbook
                )

            except Exception:

                continue

            for sheet in sheets:

                try:

                    df = read_sheet(
                        workbook,
                        sheet,
                    )

                except Exception:

                    continue

                state_rows = find_state_rows(
                    df,
                    code,
                )

                if not state_rows:
                    continue

                headers = make_headers(
                    df,
                    rows=12,
                )

                quarterly_columns = []
                annual_columns = []

                for col, header in (
                    headers.items()
                ):

                    text = header.lower()

                    if (
                        "quarter"
                        in text
                        and "change"
                        in text
                    ):

                        quarterly_columns.append(
                            col
                        )

                    if (
                        "annual"
                        in text
                        and "change"
                        in text
                    ):

                        annual_columns.append(
                            col
                        )

                sheet_text = (
                    " ".join(
                        headers.values()
                    ).lower()
                )

                if (
                    "house construction"
                    not in sheet_text
                    and "construction prices"
                    not in sheet_text
                ):

                    continue

                row = state_rows[0]

                quarterly = None
                annual = None

                for col in quarterly_columns:

                    value = number(
                        df.iloc[
                            row,
                            col,
                        ]
                    )

                    if value is not None:

                        quarterly = value

                        break

                for col in annual_columns:

                    value = number(
                        df.iloc[
                            row,
                            col,
                        ]
                    )

                    if value is not None:

                        annual = value

                        break

                if (
                    quarterly is None
                    and annual is None
                ):

                    continue

                result[code][
                    "construction_quarterly_change"
                ] = quarterly

                result[code][
                    "construction_annual_change"
                ] = annual

                result[code][
                    "construction_price_index"
                ] = annual

                result[code][
                    "sources"
                ][
                    "construction_price_index"
                ] = {
                    "workbook":
                        workbook.name,
                    "sheet":
                        sheet,
                    "row":
                        int(row),
                    "quarterly":
                        quarterly,
                    "annual":
                        annual,
                }

                break

    return result


