def combine_abs(
    dwellings,
    earnings,
    ppi,
    building,
):

    result = {}

    for code, name in STATES.items():

        d = dwellings.get(
            code,
            {},
        )

        e = earnings.get(
            code,
            {},
        )

        p = ppi.get(
            code,
            {},
        )

        b = building.get(
            code,
            {},
        )

        result[code] = {

            "state": name,

            "total_dwelling_value":
                d.get(
                    "total_dwelling_value"
                ),

            "mean_dwelling_price":
                d.get(
                    "mean_dwelling_price"
                ),

            "dwelling_count":
                d.get(
                    "dwelling_count"
                ),

            "weekly_earnings":
                e.get(
                    "weekly_earnings"
                ),

            "construction_price_index":
                p.get(
                    "construction_price_index"
                ),

            "construction_quarterly_change":
                p.get(
                    "construction_quarterly_change"
                ),

            "construction_annual_change":
                p.get(
                    "construction_annual_change"
                ),

            "building_work_value":
                b.get(
                    "building_work_value"
                ),

            "sources": {
                "dwellings":
                    d.get(
                        "sources",
                        {},
                    ),

                "earnings":
                    e.get(
                        "sources",
                        {},
                    ),

                "ppi":
                    p.get(
                        "sources",
                        {},
                    ),

                "building":
                    b.get(
                        "sources",
                        {},
                    ),
            },
        }

    return result


# ============================================================
# GOLDEN RATIO
# ============================================================

def golden_weights(
    n=16,
):

    weights = []

    for k in range(n):

        distance = min(
            k,
            n - k,
        )

        weights.append(
            PHI ** (-distance)
        )

    total = sum(
        weights
    )

    return [
        value / total
        for value in weights
    ]


def economic_sector_vector(
    values,
    sectors=16,
):

    finite_values = [
        float(value)
        for value in values
        if finite(value)
    ]

    if not finite_values:

        return [
            1.0 / sectors
            for _ in range(sectors)
        ]

    low = min(
        finite_values
    )

    high = max(
        finite_values
    )

    if high == low:

        normalized = [
            0.5
            for _ in values
        ]

    else:

        normalized = [
            (
                (
                    float(value)
                    - low
                )
                / (
                    high
                    - low
                )
            )
            if finite(value)
            else 0.5
            for value in values
        ]

    vector = [
        0.0
        for _ in range(sectors)
    ]

    for i, value in enumerate(
        normalized
    ):

        a = i % sectors

        b = (
            sectors
            - 1
            - i
        ) % sectors

        vector[a] += value
        vector[b] += value

    total = sum(
        vector
    )

    if total <= 0:

        return [
            1.0 / sectors
            for _ in range(sectors)
        ]

    return [
        value / total
        for value in vector
    ]


def similarity(
    observed,
    target,
):

    if len(observed) != len(target):

        return 0.0

    return sum(
        math.sqrt(
            max(a, 0.0)
            * max(b, 0.0)
        )
        for a, b in zip(
            observed,
            target,
        )
    )


# ============================================================
# NORMALIZATION
# ============================================================

def minmax(
    rows,
    field,
):

    values = [
        float(row[field])
        for row in rows
        if finite(
            row.get(field)
        )
    ]

    if not values:

        return {
            row["state"]: 0.5
            for row in rows
        }

    low = min(
        values
    )

    high = max(
        values
    )

    if high == low:

        return {
            row["state"]: 0.5
            for row in rows
        }

    output = {}

    for row in rows:

        value = row.get(
            field
        )

        if not finite(value):

            output[
                row["state"]
            ] = 0.5

        else:

            output[
                row["state"]
            ] = (
                float(value)
                - low
            ) / (
                high
                - low
            )

    return output


# ============================================================
# REGIONAL PREDICTION
# ============================================================

def calculate_scores(
    abs_data,
):

    rows = []

    for code, name in STATES.items():

        data = abs_data.get(
            code,
            {},
        )

        rows.append({

            "state":
                code,

            "name":
                name,

            "total_dwelling_value":
                data.get(
                    "total_dwelling_value"
                ),

            "mean_dwelling_price":
                data.get(
                    "mean_dwelling_price"
                ),

            "dwelling_count":
                data.get(
                    "dwelling_count"
                ),

            "weekly_earnings":
                data.get(
                    "weekly_earnings"
                ),

            "construction_price_index":
                data.get(
                    "construction_price_index"
                ),

            "construction_quarterly_change":
                data.get(
                    "construction_quarterly_change"
                ),

            "construction_annual_change":
                data.get(
                    "construction_annual_change"
                ),

            "building_work_value":
                data.get(
                    "building_work_value"
                ),
        })

    fields = [
        "total_dwelling_value",
        "mean_dwelling_price",
        "dwelling_count",
        "weekly_earnings",
        "construction_price_index",
        "building_work_value",
    ]

    normalized = {
        field:
            minmax(
                rows,
                field,
            )
        for field in fields
    }

    golden = golden_weights(
        16
    )

    for row in rows:

        feature_values = [
            normalized[field][
                row["state"]
            ]
            for field in fields
        ]

        mean_feature = (
            sum(feature_values)
            / len(feature_values)
        )

        denominator = sum(
            PHI ** (-j)
            for j in range(
                len(feature_values)
            )
        )

        weighted_feature = sum(
            value
            * PHI ** (-j)
            for j, value
            in enumerate(
                feature_values
            )
        ) / denominator

        state_vector_seed = (
            feature_values
            + [
                mean_feature,
                weighted_feature,
            ]
        )

        vector = (
            economic_sector_vector(
                state_vector_seed,
                16,
            )
        )

        row[
            "golden_alignment"
        ] = similarity(
            vector,
            golden,
        )

        row[
            "economic_sector_vector"
        ] = vector

    score_weights = {

        "mean_dwelling_price":
            0.25,

        "weekly_earnings":
            0.20,

        "building_work_value":
            0.15,

        "total_dwelling_value":
            0.10,

        "dwelling_count":
            0.10,

        "construction_price_index":
            0.10,

        "golden_alignment":
            0.10,
    }

    for row in rows:

        score = 0.0

        for field, weight in (
            score_weights.items()
        ):

            if field == (
                "golden_alignment"
            ):

                value = row.get(
                    field,
                    0.5,
                )

            else:

                value = normalized[
                    field
                ][
                    row["state"]
                ]

            score += (
                weight
                * value
            )

        row[
            "regional_score"
        ] = score

        row[
            "normalized_features"
        ] = {

            field:

                (
                    row.get(field)
                    if field ==
                    "golden_alignment"

                    else

                    normalized[
                        field
                    ][
                        row["state"]
                    ]
                )

            for field
            in score_weights
        }

    rows.sort(
        key=lambda row:
            row[
                "regional_score"
            ],
        reverse=True,
    )

    # Add ranking after sorting.
    for rank, row in enumerate(
        rows,
        1,
    ):

        row[
            "rank"
        ] = rank

    return rows


# ============================================================
# PREDICTED VALUE TILE HEAT MAP
# ============================================================

STATE_TILE_LAYOUT = {

    # row, column

    "WA":
        (0, 0),

    "NT":
        (0, 1),

    "QLD":
        (0, 2),

    "SA":
        (1, 0),

    "NSW":
        (1, 2),

    "VIC":
        (2, 1),

    "ACT":
        (2, 2),

    "TAS":
        (3, 1),
}


def generate_predicted_value_heatmap(
    predictions,
    output_path=None,
):

    """
    Generate a tile-style Australian
    predicted-value heat map.

    One tile:
        one state/territory.

    Tile colour:
        regional_score.

    Tile text:
        state abbreviation
        state name
        regional score
        rank

    The layout is a simplified visual
    state arrangement. It is NOT an
    OSM/geographic tile map.
    """

    if output_path is None:

        output_path = (
            OUTPUT_DIR
            / "predicted_value_heatmap.png"
        )

    scores = {}
    names = {}
    ranks = {}

    for row in predictions:

        code = row.get(
            "state"
        )

        score = row.get(
            "regional_score"
        )

        if code not in (
            STATE_TILE_LAYOUT
        ):

            continue

        if not finite(score):

            continue

        scores[code] = float(
            score
        )

        names[code] = row.get(
            "name",
            STATES.get(
                code,
                code,
            ),
        )

        ranks[code] = row.get(
            "rank",
            "?",
        )

    if not scores:

        raise ValueError(
            "No valid regional_score "
            "values were found."
        )

    minimum = min(
        scores.values()
    )

    maximum = max(
        scores.values()
    )

    if maximum == minimum:

        normalized = {
            code: 0.5
            for code in scores
        }

    else:

        normalized = {

            code:

                (
                    value
                    - minimum
                )
                / (
                    maximum
                    - minimum
                )

            for code, value
            in scores.items()
        }

    fig, ax = plt.subplots(
        figsize=(11, 8)
    )

    ax.set_xlim(
        -0.25,
        3.25,
    )

    ax.set_ylim(
        4.10,
        -0.25,
    )

    ax.set_aspect(
        "equal"
    )

    ax.axis(
        "off"
    )

    cmap = plt.get_cmap(
        "YlOrRd"
    )

    for code, (
        row,
        col,
    ) in STATE_TILE_LAYOUT.items():

        if code not in scores:

            continue

        x = col
        y = row

        score = scores[
            code
        ]

        normalized_value = (
            normalized[
                code
            ]
        )

        face_color = cmap(
            normalized_value
        )

        tile = Rectangle(

            (
                x,
                y,
            ),

            1.0,
            1.0,

            facecolor=
                face_color,

            edgecolor=
                "black",

            linewidth=
                2.0,
        )

        ax.add_patch(
            tile
        )

        r, g, b, _ = (
            face_color
        )

        luminance = (
            0.299 * r
            + 0.587 * g
            + 0.114 * b
        )

        text_color = (
            "black"
            if luminance > 0.60
            else "white"
        )

        # Rank
        ax.text(

            x + 0.10,
            y + 0.12,

            f"#{ranks[code]}",

            ha="left",
            va="top",

            fontsize=10,

            fontweight="bold",

            color=text_color,
        )

        # State abbreviation
        ax.text(

            x + 0.5,
            y + 0.37,

            code,

            ha="center",
            va="center",

            fontsize=23,

            fontweight="bold",

            color=text_color,
        )

        # Predicted regional score
        ax.text(

            x + 0.5,
            y + 0.60,

            f"{score:.4f}",

            ha="center",
            va="center",

            fontsize=13,

            color=text_color,
        )

        # Full state name
        ax.text(

            x + 0.5,
            y + 0.84,

            names[code],

            ha="center",
            va="center",

            fontsize=7.5,

            color=text_color,
        )

    ax.set_title(

        "Predicted Regional Value — "
        "ABS Economic Model",

        fontsize=18,

        fontweight="bold",

        pad=20,
    )

    sm = plt.cm.ScalarMappable(

        cmap=cmap,

        norm=plt.Normalize(

            vmin=minimum,

            vmax=maximum,
        ),
    )

    sm.set_array([])

    colorbar = fig.colorbar(

        sm,

        ax=ax,

        fraction=0.035,

        pad=0.025,
    )

    colorbar.set_label(

        "Predicted regional score",

        fontsize=11,
    )

    ax.text(

        1.5,
        3.88,

        (
            f"Low = {minimum:.4f}    "
            f"High = {maximum:.4f}"
        ),

        ha="center",

        va="center",

        fontsize=10,
    )

    fig.savefig(

        output_path,

        dpi=220,

        bbox_inches="tight",
    )

    plt.close(
        fig
    )

    print(
        f"Saved heat map: "
        f"{output_path}"
    )

    return output_path


