        age = time.time() - path.stat().st_mtime

        if age < CACHE_SECONDS:
            return path.read_text(
                encoding="utf-8",
                errors="replace",
            )

    print(f"Downloading ABS: {name}")
    print(f"  {url}")

    response = requests.get(
        url,
        headers=HEADERS,
        timeout=60,
    )

    response.raise_for_status()

    data = response.content

    path.write_bytes(data)

    print(f"  bytes: {len(data):,}")
    print(f"  sha256: {sha256(data)}")

    return response.text


def discover_downloads(
    html: str,
    base_url: str,
) -> list[str]:

    links = re.findall(
        r'href\s*=\s*["\']([^"\']+)["\']',
        html,
        flags=re.I,
    )

    output = []

    for link in links:

        full = urljoin(
            base_url,
            link,
        )

        lower = full.lower()

        if any(
            lower.endswith(ext)
            or ext in lower
            for ext in (
                ".xlsx",
                ".xls",
                ".csv",
                ".zip",
            )
        ):
            output.append(full)

    return list(dict.fromkeys(output))


# ============================================================
# HTML TABLE LOADING
# ============================================================

def read_tables(
    html: str,
) -> list[pd.DataFrame]:

    try:

        return pd.read_html(
            io.StringIO(html)
        )

    except Exception as exc:

        print(
            "WARNING: pandas could not read "
            f"HTML tables: {exc}"
        )

        return []


def flatten_columns(
    df: pd.DataFrame,
) -> pd.DataFrame:

    result = df.copy()

    if isinstance(
        result.columns,
        pd.MultiIndex,
    ):

        result.columns = [
            " ".join(
                str(x)
                for x in col
                if str(x).lower()
                != "nan"
            ).strip()
            for col in result.columns
        ]

    else:

        result.columns = [
            str(x)
            for x in result.columns
        ]

    return result


def clean_text(value) -> str:

    if pd.isna(value):
        return ""

    text = str(value)

    text = (
        text.replace("\xa0", " ")
        .replace("\n", " ")
        .replace("\r", " ")
    )

    return re.sub(
        r"\s+",
        " ",
        text,
    ).strip()


def numeric(value) -> Optional[float]:

    if value is None:
        return None

    if isinstance(
        value,
        (int, float),
    ):

        if pd.isna(value):
            return None

        return float(value)

    text = clean_text(value)

    if not text:
        return None

    text = (
        text.replace(",", "")
        .replace("$", "")
        .replace("%", "")
        .replace("−", "-")
        .replace("–", "-")
    )

    if text.lower() in {
        "na",
        "n/a",
        "nan",
        "-",
        "..",
        "np",
    }:
        return None

    match = re.search(
        r"-?\d+(?:\.\d+)?",
        text,
    )

    if not match:
        return None

    try:
        return float(
            match.group(0)
        )
    except ValueError:
        return None


# ============================================================
# TABLE DETECTION
# ============================================================

def state_in_text(
    value,
    state: str,
) -> bool:

    text = clean_text(
        value
    ).lower()

    for alias in STATE_ALIASES[state]:

        if alias.lower() == text:
            return True

    return False


def find_state_column(
    df: pd.DataFrame,
) -> Optional[str]:

    best_column = None
    best_score = 0

    for column in df.columns:

        score = 0

        for value in df[column]:

            text = clean_text(
                value
            ).lower()

            for state, aliases in (
                STATE_ALIASES.items()
            ):

                if any(
                    alias.lower()
                    == text
                    for alias in aliases
                ):

                    score += 1
                    break

        if score > best_score:

            best_score = score
            best_column = column

    if best_score >= 3:
        return best_column

    return None


def state_rows(
    df: pd.DataFrame,
) -> dict[str, pd.Series]:

    df = flatten_columns(
        df
    )

    column = find_state_column(
        df
    )

    if column is None:
        return {}

    output = {}

    for _, row in df.iterrows():

        label = clean_text(
            row[column]
        )

        for state, aliases in (
            STATE_ALIASES.items()
        ):

            if any(
                label.lower()
                == alias.lower()
                for alias in aliases
            ):

                output[state] = row
                break

    return output


def find_table_with_states(
    tables: list[pd.DataFrame],
) -> list[pd.DataFrame]:

    result = []

    for table in tables:

        if len(
            state_rows(table)
        ) >= 3:

            result.append(
                flatten_columns(table)
            )

    return result


# ============================================================
# COLUMN SELECTION
# ============================================================

def score_column(
    column: str,
    preferred: list[str],
    forbidden: list[str] = None,
) -> int:

    text = column.lower()

    score = 0

    for keyword in preferred:

        if keyword.lower() in text:
            score += 10

    if forbidden:

        for keyword in forbidden:

            if keyword.lower() in text:
                score -= 10

    return score


def choose_numeric_column(
    df: pd.DataFrame,
    preferred: list[str],
    value_min: float = -float("inf"),
    value_max: float = float("inf"),
) -> Optional[str]:

    rows = state_rows(
        df
    )

    if not rows:
        return None

    candidates = []

    for column in df.columns:

        values = []

        for row in rows.values():

            value = numeric(
                row[column]
            )

            if (
                value is not None
                and value_min
                <= value
                <= value_max
            ):

                values.append(
                    value
                )

        if len(values) < 3:
            continue

        score = score_column(
            str(column),
            preferred,
        )

        # Prefer columns that actually contain
        # plausible state observations.
        score += len(values)

        candidates.append(
            (
                score,
                column,
            )
        )

    if not candidates:
        return None

    candidates.sort(
        reverse=True,
        key=lambda x: x[0],
    )

    return candidates[0][1]


# ============================================================
# DWELLING TABLES
# ============================================================

def extract_dwelling_data(
    html: str,
) -> dict[str, dict]:

    tables = find_table_with_states(
        read_tables(html)
    )

    print(
        f"DWELLING STATE TABLES FOUND: "
        f"{len(tables)}"
    )

    observations = {
        state: {}
        for state in STATES
    }

    for table in tables:

        columns = [
            str(c)
            for c in table.columns
        ]

        # ----------------------------------------------------
        # Mean price
        # ----------------------------------------------------

        mean_col = choose_numeric_column(
            table,
            [
                "mean price",
                "mean dwelling price",
                "mean",
                "average price",
            ],
            value_min=300_000,
            value_max=5_000_000,
        )

        # ----------------------------------------------------
        # Median price
        # ----------------------------------------------------

        median_col = choose_numeric_column(
            table,
            [
                "median price",
                "median",
            ],
            value_min=200_000,
            value_max=5_000_000,
        )

        # ----------------------------------------------------
        # Dwelling count
        # ----------------------------------------------------

        count_col = choose_numeric_column(
            table,
            [
                "number",
                "dwellings",
                "count",
                "stock",
            ],
            value_min=100_000,
            value_max=5_000_000,
        )

        # ----------------------------------------------------
        # Total value
        # ----------------------------------------------------

        value_col = choose_numeric_column(
            table,
            [
                "total value",
                "value",
            ],
            value_min=1_000,
            value_max=20_000_000,
        )

        rows = state_rows(
            table
        )

        for state, row in rows.items():

            if mean_col:

                value = numeric(
                    row[mean_col]
                )

                if value is not None:

                    # ABS dwelling price tables often
                    # report in $'000.
                    if value < 20_000:
                        value *= 1000

                    observations[state][
                        "mean_dwelling_price"
                    ] = value

            if median_col:

                value = numeric(
                    row[median_col]
                )

                if value is not None:

                    if value < 20_000:
                        value *= 1000

                    observations[state][
                        "median_dwelling_price"
                    ] = value

            if count_col:

                value = numeric(
                    row[count_col]
                )

                if value is not None:

                    observations[state][
                        "dwelling_count"
                    ] = value

            if value_col:

                value = numeric(
                    row[value_col]
                )

                if value is not None:

                    # If the table is $m or $b,
                    # infer based on magnitude.
                    observations[state][
                        "dwelling_total_value"
                    ] = value

    return observations


