def coverage(
    data: RegionalData,
) -> float:

    fields = [
        data.dwelling_count,
        data.dwelling_total_value,
        data.mean_dwelling_price,
        data.median_dwelling_price,
        data.weekly_earnings,
        data.construction_quarter_change,
        data.construction_annual_change,
        data.building_work_value,
    ]

    present = sum(
        x is not None
        for x in fields
    )

    return (
        present
        / len(fields)
    )


def make_regional_dataset(
    dwelling_data,
    earnings_data,
    ppi_data,
    building_data,
) -> list[RegionalData]:

    records = []

    for state, state_name in (
        STATES.items()
    ):

        latitude, longitude = (
            STATE_CENTROIDS[state]
        )

        dwelling = (
            dwelling_data.get(
                state,
                {},
            )
        )

        ppi = (
            ppi_data.get(
                state,
                {},
            )
        )

        weekly = (
            earnings_data.get(
                state
            )
        )

        building = (
            building_data.get(
                state
            )
        )

        annual_income = (
            None
            if weekly is None
            else weekly * 52.0
        )

        # ----------------------------------------------------
        # IMPORTANT:
        #
        # This is explicitly a DERIVED estimate.
        # It is NOT presented as an ABS construction cost.
        #
        # Where building-work value is available, use it as
        # the primary observed construction/economic measure.
        # ----------------------------------------------------

        if building is not None:

            estimated_building_cost = (
                float(building)
            )

        else:

            estimated_building_cost = None

        record = RegionalData(
            state=state,
            state_name=state_name,

            latitude=latitude,
            longitude=longitude,

            dwelling_count=(
                dwelling.get(
                    "dwelling_count"
                )
            ),

            dwelling_total_value=(
                dwelling.get(
                    "dwelling_total_value"
                )
            ),

            mean_dwelling_price=(
                dwelling.get(
                    "mean_dwelling_price"
                )
            ),

            median_dwelling_price=(
                dwelling.get(
                    "median_dwelling_price"
                )
            ),

            weekly_earnings=weekly,

            construction_quarter_change=(
                ppi.get(
                    "quarter"
                )
            ),

            construction_annual_change=(
                ppi.get(
                    "annual"
                )
            ),

            building_work_value=building,

            annual_income=annual_income,

            estimated_building_cost=(
                estimated_building_cost
            ),

            data_coverage=0.0,
            confidence=0.0,
        )

        record.data_coverage = (
            coverage(record)
        )

        # Confidence is deliberately conservative.
        record.confidence = (
            record.data_coverage
            ** 0.5
        )

        records.append(
            record
        )

    return records


# ============================================================
# LOG NORMALIZATION
# ============================================================

def log_normalize(
    values: list[Optional[float]],
) -> list[float]:

    positive = [
        float(x)
        for x in values
        if (
            x is not None
            and x > 0
        )
    ]

    if not positive:
        return [
            0.0
            for _ in values
        ]

    logs = [
        math.log1p(x)
        for x in positive
    ]

    low = min(logs)
    high = max(logs)

    output = []

    for value in values:

        if (
            value is None
            or value <= 0
        ):

            output.append(
                0.0
            )

            continue

        x = math.log1p(
            value
        )

        if high == low:

            output.append(
                1.0
            )

        else:

            output.append(
                (x - low)
                / (high - low)
            )

    return output


def normalize_signed(
    values: list[Optional[float]],
) -> list[float]:

    valid = [
        float(x)
        for x in values
        if x is not None
    ]

    if not valid:

        return [
            0.0
            for _ in values
        ]

    low = min(valid)
    high = max(valid)

    output = []

    for value in values:

        if value is None:

            output.append(
                0.0
            )

            continue

        if high == low:

            output.append(
                0.5
            )

        else:

            output.append(
                (
                    value - low
                )
                / (
                    high - low
                )
            )

    return output


# ============================================================
# PRECISE PREDICTION MODEL
# ============================================================

def predict_big_things(
    records: list[RegionalData],
    *,
    property_weight: float = 0.30,
    income_weight: float = 0.20,
    construction_weight: float = 0.15,
    building_weight: float = 0.20,
    dwelling_stock_weight: float = 0.15,
) -> list[Prediction]:

    weights = [
        property_weight,
        income_weight,
        construction_weight,
        building_weight,
        dwelling_stock_weight,
    ]

    total_weight = sum(
        weights
    )

    if total_weight <= 0:

        raise ValueError(
            "Prediction weights must "
            "sum to a positive number."
        )

    property_weight /= total_weight
    income_weight /= total_weight
    construction_weight /= total_weight
    building_weight /= total_weight
    dwelling_stock_weight /= total_weight

    property_values = [
        x.mean_dwelling_price
        for x in records
    ]

    income_values = [
        x.annual_income
        for x in records
    ]

    construction_values = [
        x.construction_annual_change
        for x in records
    ]

    building_values = [
        x.building_work_value
        for x in records
    ]

    dwelling_values = [
        x.dwelling_count
        for x in records
    ]

    property_scores = log_normalize(
        property_values
    )

    income_scores = log_normalize(
        income_values
    )

    construction_scores = normalize_signed(
        construction_values
    )

    building_scores = log_normalize(
        building_values
    )

    dwelling_scores = log_normalize(
        dwelling_values
    )

    predictions = []

    for i, record in enumerate(
        records
    ):

        raw_score = (
            property_weight
            * property_scores[i]

            + income_weight
            * income_scores[i]

            + construction_weight
            * construction_scores[i]

            + building_weight
            * building_scores[i]

            + dwelling_stock_weight
            * dwelling_scores[i]
        )

        # Missing-data penalty.
        #
        # A region with half the observations available
        # should not receive the same confidence as a region
        # with complete observations.
        score = (
            raw_score
            * record.confidence
        )

        predictions.append(
            Prediction(
                rank=0,

                state=record.state,

                score=score,

                property_score=(
                    property_weight
                    * property_scores[i]
                ),

                income_score=(
                    income_weight
                    * income_scores[i]
                ),

                construction_score=(
                    construction_weight
                    * construction_scores[i]
                ),

                building_activity_score=(
                    building_weight
                    * building_scores[i]
                ),

                dwelling_stock_score=(
                    dwelling_stock_weight
                    * dwelling_scores[i]
                ),

                confidence=record.confidence,

                data_coverage=(
                    record.data_coverage
                ),

                mean_dwelling_price=(
                    record.mean_dwelling_price
                ),

                median_dwelling_price=(
                    record.median_dwelling_price
                ),

                weekly_earnings=(
                    record.weekly_earnings
                ),

                annual_income=(
                    record.annual_income
                ),

                dwelling_count=(
                    record.dwelling_count
                ),

                dwelling_total_value=(
                    record.dwelling_total_value
                ),

                construction_annual_change=(
                    record.construction_annual_change
                ),

                building_work_value=(
                    record.building_work_value
                ),

                latitude=record.latitude,
                longitude=record.longitude,
            )
        )

    predictions.sort(
        key=lambda x: x.score,
        reverse=True,
    )

    output = []

    for rank, prediction in enumerate(
        predictions,
        start=1,
    ):

        prediction.rank = rank

        output.append(
            prediction
        )

    return output


# ============================================================
# ORIGINAL FACTOR / PRODUCT SOLVER
# ============================================================

def prime_factors(
    n: int,
) -> dict[int, int]:

    result = {}

    d = 2

    while d * d <= n:

        while n % d == 0:

            result[d] = (
                result.get(d, 0)
                + 1
            )

            n //= d

        d = (
            3
            if d == 2
            else d + 2
        )

    if n > 1:

        result[n] = (
            result.get(n, 0)
            + 1
        )

    return result


def factor_vector(
    value: int,
    primes: tuple[int, ...],
) -> Optional[tuple[int, ...]]:

    remaining = value
    vector = []

    for prime in primes:

        exponent = 0

        while (
            remaining % prime == 0
        ):

            remaining //= prime
            exponent += 1

        vector.append(
            exponent
        )

    if remaining != 1:
        return None

    return tuple(vector)


def vector_add(
    a: tuple[int, ...],
    b: tuple[int, ...],
) -> tuple[int, ...]:

    return tuple(
        x + y
        for x, y in zip(a, b)
    )


def vector_leq(
    a: tuple[int, ...],
    b: tuple[int, ...],
) -> bool:

    return all(
        x <= y
        for x, y in zip(a, b)
    )


def vector_distance(
    a: tuple[int, ...],
    b: tuple[int, ...],
) -> int:

    return sum(
        max(
            0,
            y - x,
        )
        for x, y in zip(a, b)
    )


def solve_product_target(
    candidates: list[Candidate],
    target: int,
    beam_width: int = 256,
) -> list[Candidate]:

    factors = prime_factors(
        target
    )

    primes = tuple(
        sorted(factors)
    )

    target_vector = tuple(
        factors[p]
        for p in primes
    )

    states = {
        tuple(
            0
            for _ in primes
        ): []
    }

    for candidate in candidates:

        vector = factor_vector(
            candidate.value,
            primes,
        )

        if vector is None:
            continue

        new_states = dict(
            states
        )

        for current, path in (
            states.items()
        ):

            combined = vector_add(
                current,
                vector,
            )

            if not vector_leq(
                combined,
                target_vector,
            ):
                continue

            new_path = (
                path
                + [candidate]
            )

            if (
                combined
                == target_vector
            ):

                return new_path

            old = new_states.get(
                combined
            )

            if (
                old is None
                or len(new_path)
                < len(old)
            ):

                new_states[
                    combined
                ] = new_path

        ranked = sorted(
            new_states.items(),
            key=lambda item:
                (
                    vector_distance(
                        item[0],
                        target_vector,
                    ),
                    len(item[1]),
                ),
        )

        states = dict(
            ranked[
                :beam_width
            ]
        )

    return []


