def clean_text(
    value,
) -> str:

    if value is None:
        return ""

    try:

        if pd.isna(value):
            return ""

    except Exception:
        pass

    return (
        str(value)
        .replace(
            "\xa0",
            " ",
        )
        .replace(
            "\n",
            " ",
        )
        .replace(
            "\r",
            " ",
        )
        .strip()
    )


def numeric(
    value,
) -> Optional[float]:

    text = clean_text(
        value
    )

    if not text:
        return None

    text = (
        text
        .replace(",", "")
        .replace("$", "")
        .replace("%", "")
        .replace("−", "-")
    )

    if text.lower() in {
        "-",
        "..",
        "na",
        "n/a",
        "nan",
    }:

        return None

    import re

    match = re.search(
        r"-?\d+(?:\.\d+)?",
        text,
    )

    if not match:
        return None

    try:

        return float(
            match.group(0)
        )

    except ValueError:

        return None


def flatten_columns(
    df: pd.DataFrame,
) -> pd.DataFrame:

    df = df.copy()

    if isinstance(
        df.columns,
        pd.MultiIndex,
    ):

        df.columns = [
            " ".join(
                clean_text(x)
                for x in column
                if clean_text(x)
            )
            for column in df.columns
        ]

    else:

        df.columns = [
            clean_text(x)
            for x in df.columns
        ]

    return df


def read_tables(
    html: str,
) -> list[pd.DataFrame]:

    try:

        return [
            flatten_columns(table)
            for table in pd.read_html(
                io.StringIO(html)
            )
        ]

    except Exception as exc:

        print(
            "table parsing warning:",
            exc,
        )

        return []


def state_aliases(
    state: str,
) -> list[str]:

    return [
        state,
        STATES[state],
    ]


def find_state_column(
    df: pd.DataFrame,
) -> Optional[str]:

    best = None
    best_score = 0

    for column in df.columns:

        score = 0

        for value in df[column]:

            text = clean_text(
                value
            ).lower()

            for state in STATES:

                if text in {
                    x.lower()
                    for x in state_aliases(
                        state
                    )
                }:

                    score += 1
                    break

        if score > best_score:

            best_score = score
            best = column

    if best_score >= 3:
        return best

    return None


def get_state_rows(
    df: pd.DataFrame,
) -> dict[str, pd.Series]:

    column = find_state_column(
        df
    )

    if column is None:
        return {}

    output = {}

    for _, row in df.iterrows():

        text = clean_text(
            row[column]
        ).lower()

        for state in STATES:

            aliases = {
                x.lower()
                for x in state_aliases(
                    state
                )
            }

            if text in aliases:

                output[state] = row
                break

    return output


def choose_column(
    df: pd.DataFrame,
    keywords: list[str],
    low: float,
    high: float,
) -> Optional[str]:

    rows = get_state_rows(
        df
    )

    if len(rows) < 3:
        return None

    candidates = []

    for column in df.columns:

        values = []

        for row in rows.values():

            value = numeric(
                row[column]
            )

            if (
                value is not None
                and low <= value <= high
            ):

                values.append(
                    value
                )

        if len(values) < 3:
            continue

        name = str(
            column
        ).lower()

        score = len(values)

        for keyword in keywords:

            if keyword.lower() in name:
                score += 20

        candidates.append(
            (
                score,
                column,
            )
        )

    if not candidates:
        return None

    candidates.sort(
        reverse=True,
        key=lambda x: x[0],
    )

    return candidates[0][1]


