def parse_dwellings(
    html: str,
) -> dict[str, dict]:

    tables = read_tables(
        html
    )

    output = {
        state: {}
        for state in STATES
    }

    for table in tables:

        rows = get_state_rows(
            table
        )

        if len(rows) < 3:
            continue

        mean_column = choose_column(
            table,
            [
                "mean price",
                "mean dwelling",
                "average price",
            ],
            300_000,
            5_000_000,
        )

        median_column = choose_column(
            table,
            [
                "median price",
                "median dwelling",
                "median",
            ],
            200_000,
            5_000_000,
        )

        count_column = choose_column(
            table,
            [
                "number",
                "dwellings",
                "count",
            ],
            100_000,
            5_000_000,
        )

        for state, row in rows.items():

            if mean_column:

                value = numeric(
                    row[mean_column]
                )

                if value is not None:

                    if value < 20_000:
                        value *= 1000

                    output[state][
                        "mean"
                    ] = value

            if median_column:

                value = numeric(
                    row[median_column]
                )

                if value is not None:

                    if value < 20_000:
                        value *= 1000

                    output[state][
                        "median"
                    ] = value

            if count_column:

                value = numeric(
                    row[count_column]
                )

                if value is not None:

                    output[state][
                        "count"
                    ] = value

    return output


