    html: str,
) -> dict[str, float]:

    output = {}

    for table in read_tables(
        html
    ):

        rows = get_state_rows(
            table
        )

        if len(rows) < 3:
            continue

        column = choose_column(
            table,
            [
                "ordinary time",
                "full-time",
                "full time",
                "adult",
            ],
            1000,
            5000,
        )

        if column is None:
            continue

        for state, row in rows.items():

            value = numeric(
                row[column]
            )

            if value is not None:

                output[state] = value

    return output


