        table_name = " ".join(
            str(x).lower()
            for x in table.columns
        )

        if (
            "construction"
            not in table_name
            and "annual"
            not in table_name
        ):
            continue

        quarter = choose_column(
            table,
            [
                "quarter",
                "quarterly",
            ],
            -50,
            50,
        )

        annual = choose_column(
            table,
            [
                "annual",
                "12 month",
                "12-month",
            ],
            -50,
            50,
        )

        for state, row in rows.items():

            if quarter:

                value = numeric(
                    row[quarter]
                )

                if value is not None:

                    output[state][
                        "quarter"
                    ] = value

            if annual:

                value = numeric(
                    row[annual]
                )

                if value is not None:

                    output[state][
                        "annual"
                    ] = value

    return output


