def haversine_km(
    lat1,
    lon1,
    lat2,
    lon2,
) -> np.ndarray:

    lat1 = np.radians(
        np.asarray(lat1)
    )

    lat2 = np.radians(
        np.asarray(lat2)
    )

    dlat = (
        lat2 - lat1
    )

    dlon = np.radians(
        np.asarray(lat2 * 0 + lon2)
        - np.asarray(lat1 * 0 + lon1)
    )

    a = (
        np.sin(dlat / 2) ** 2
        +
        np.cos(lat1)
        * np.cos(lat2)
        * np.sin(dlon / 2) ** 2
    )

    return (
        6371.0088
        * 2
        * np.arctan2(
            np.sqrt(a),
            np.sqrt(
                np.maximum(
                    0,
                    1 - a,
                )
            ),
        )
    )


def road_overpass_query(
    latitude: float,
    longitude: float,
    radius_km: float,
) -> str:

    radius_m = int(
        radius_km * 1000
    )

    highway_types = "|".join(
        ROAD_TYPES
    )

    return f"""
[out:json][timeout:90];

way
  ["highway"~"^({highway_types})$"]
  (around:{radius_m},{latitude},{longitude});

out geom;
"""


def download_roads(
    state: str,
    force: bool = False,
) -> dict:

    path = (
        ROAD_DIR
        / f"{state.lower()}_roads.json"
    )

    if (
        path.exists()
        and not force
    ):

        age = (
            time.time()
            - path.stat().st_mtime
        )

        if age < 86400:

            return json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )

    latitude, longitude = (
        STATE_CAPITALS[state]
    )

    query = road_overpass_query(
        latitude,
        longitude,
        ROAD_RADIUS_KM,
    )

    last_error = None

    for endpoint in OVERPASS_URLS:

        try:

            print()
            print(
                f"Downloading roads "
                f"for {state}"
            )

            response = requests.post(
                endpoint,
                data=query.encode(
                    "utf-8"
                ),
                headers={
                    "User-Agent":
                        USER_AGENT,
                    "Content-Type":
                        "text/plain",
                },
                timeout=120,
            )

            response.raise_for_status()

            data = response.json()

            path.write_text(
                json.dumps(
                    data
                ),
                encoding="utf-8",
            )

            print(
                "road elements:",
                len(
                    data.get(
                        "elements",
                        [],
                    )
                ),
            )

            return data

        except Exception as exc:

            last_error = exc

            print(
                "Overpass endpoint failed:",
                exc,
            )

    raise RuntimeError(
        f"Could not download roads "
        f"for {state}: {last_error}"
    )


# ============================================================
# VECTORIZE ROAD GEOMETRY
# ============================================================

def extract_road_segments(
    data: dict,
) -> tuple[
    np.ndarray,
    np.ndarray,
    np.ndarray,
    np.ndarray,
]:

    start_lat = []
    start_lon = []
    end_lat = []
    end_lon = []

    for element in data.get(
        "elements",
        [],
    ):

        geometry = (
            element.get(
                "geometry"
            )
        )

        if not geometry:
            continue

        if len(geometry) < 2:
            continue

        for a, b in zip(
            geometry[:-1],
            geometry[1:],
        ):

            start_lat.append(
                a["lat"]
            )

            start_lon.append(
                a["lon"]
            )

            end_lat.append(
                b["lat"]
            )

            end_lon.append(
                b["lon"]
            )

    return (
        np.asarray(
            start_lat,
            dtype=np.float64,
        ),

        np.asarray(
            start_lon,
            dtype=np.float64,
        ),

        np.asarray(
            end_lat,
            dtype=np.float64,
        ),

        np.asarray(
            end_lon,
            dtype=np.float64,
        ),
    )


def calculate_road_geometry(
    state: str,
    data: dict,
) -> RoadGeometry:

    (
        lat1,
        lon1,
        lat2,
        lon2,
    ) = extract_road_segments(
        data
    )

    if len(lat1) == 0:

        raise RuntimeError(
            f"No road segments "
            f"found for {state}"
        )

    # --------------------------------------------------------
    # Vectorized local projection.
    #
    # x = east-west distance
    # y = north-south distance
    # --------------------------------------------------------

    mean_lat = np.radians(
        (
            lat1 + lat2
        )
        / 2
    )

    meters_per_degree_lat = 111_320.0

    meters_per_degree_lon = (
        111_320.0
        * np.cos(mean_lat)
    )

    dx = (
        (
            lon2
            - lon1
        )
        * meters_per_degree_lon
    )

    dy = (
        (
            lat2
            - lat1
        )
        * meters_per_degree_lat
    )

    lengths_m = np.hypot(
        dx,
        dy,
    )

    valid = (
        lengths_m > 0.1
    )

    dx = dx[valid]
    dy = dy[valid]
    lengths_m = lengths_m[valid]

    # --------------------------------------------------------
    # Road direction.
    #
    # A road has no inherent arrow direction, therefore
    # orientation is folded into [0, pi).
    # --------------------------------------------------------

    angles = np.arctan2(
        dy,
        dx,
    )

    angles = np.mod(
        angles,
        np.pi,
    )

    # --------------------------------------------------------
    # Vectorized sector assignment.
    # --------------------------------------------------------

    sector_width = (
        np.pi
        / ROAD_SECTORS
    )

    sector_indices = np.floor(
        angles
        / sector_width
    ).astype(
        np.int64
    )

    sector_indices = np.clip(
        sector_indices,
        0,
        ROAD_SECTORS - 1,
    )

    sector_lengths = np.bincount(
        sector_indices,
        weights=lengths_m,
        minlength=ROAD_SECTORS,
    )

    total_length_m = (
        np.sum(
            sector_lengths
        )
    )

    if total_length_m <= 0:

        raise RuntimeError(
            "Road length is zero."
        )

    sector_ratios = (
        sector_lengths
        / total_length_m
    )

    # --------------------------------------------------------
    # Vector resultant.
    #
    # Because road orientation is axial rather than directed,
    # use 2*theta.
    #
    # This prevents a road running east from cancelling a road
    # running west.
    # --------------------------------------------------------

    cos2 = np.cos(
        2 * angles
    )

    sin2 = np.sin(
        2 * angles
    )

    weighted_cos = (
        np.sum(
            lengths_m
            * cos2
        )
        / total_length_m
    )

    weighted_sin = (
        np.sum(
            lengths_m
            * sin2
        )
        / total_length_m
    )

    anisotropy = float(
        np.hypot(
            weighted_cos,
            weighted_sin,
        )
    )

    dominant_angle = (
        0.5
        * np.arctan2(
            weighted_sin,
            weighted_cos,
        )
    )

    dominant_angle = float(
        np.mod(
            dominant_angle,
            np.pi,
        )
    )

    dominant_sector = int(
        np.floor(
            dominant_angle
            / sector_width
        )
    )

    dominant_sector = min(
        dominant_sector,
        ROAD_SECTORS - 1,
    )

    # --------------------------------------------------------
    # Entropy.
    #
    # Maximum entropy means evenly distributed road
    # orientations.
    # --------------------------------------------------------

    probabilities = (
        sector_ratios[
            sector_ratios > 0
        ]
    )

    entropy = float(
        -np.sum(
            probabilities
            * np.log(
                probabilities
            )
        )
    )

    maximum_entropy = math.log(
        ROAD_SECTORS
    )

    directional_entropy = (
        entropy
        / maximum_entropy
        if maximum_entropy > 0
        else 0.0
    )

    # --------------------------------------------------------
    # Geometric sector classes.
    # --------------------------------------------------------

    sector_angles = (
        (
            np.arange(
                ROAD_SECTORS
            )
            + 0.5
        )
        * sector_width
    )

    # Near horizontal.
    horizontal = (
        np.abs(
            np.sin(
                sector_angles
            )
        )
        < 0.25
    )

    # Near vertical.
    vertical = (
        np.abs(
            np.cos(
                sector_angles
            )
        )
        < 0.25
    )

    diagonal = (
        ~horizontal
        & ~vertical
    )

    east_west_ratio = float(
        np.sum(
            sector_ratios[
                horizontal
            ]
        )
    )

    north_south_ratio = float(
        np.sum(
            sector_ratios[
                vertical
            ]
        )
    )

    diagonal_ratio = float(
        np.sum(
            sector_ratios[
                diagonal
            ]
        )
    )

    # --------------------------------------------------------
    # Network vector.
    # --------------------------------------------------------

    network_vector_x = float(
        weighted_cos
    )

    network_vector_y = float(
        weighted_sin
    )

    # --------------------------------------------------------
    # Approximate circular region area.
    # --------------------------------------------------------

    area_km2 = (
        math.pi
        * ROAD_RADIUS_KM**2
    )

    total_length_km = (
        total_length_m
        / 1000.0
    )

    road_density = (
        total_length_km
        / area_km2
        * 100.0
    )

    # --------------------------------------------------------
    # Capital direction.
    #
    # This compares the dominant road orientation to the
    # radial direction from the regional centre to its capital.
    # --------------------------------------------------------

    centroid_lat, centroid_lon = (
        STATE_CENTROIDS[state]
    )

    capital_lat, capital_lon = (
        STATE_CAPITALS[state]
    )

    capital_dx = (
        (
            capital_lon
            - centroid_lon
        )
        * 111_320
        * math.cos(
            math.radians(
                centroid_lat
            )
        )
    )

    capital_dy = (
        (
            capital_lat
            - centroid_lat
        )
        * 111_320
    )

    capital_angle = math.atan2(
        capital_dy,
        capital_dx,
    )

    capital_angle = (
        capital_angle
        % math.pi
    )

    angular_difference = abs(
        dominant_angle
        - capital_angle
    )

    angular_difference = min(
        angular_difference,
        math.pi
        - angular_difference,
    )

    alignment = (
        math.cos(
            angular_difference
        )
        + 1
    ) / 2

    return RoadGeometry(
        state=state,

        total_length_km=(
            total_length_km
        ),

        sector_lengths=(
            sector_lengths / 1000.0
        ),

        sector_ratios=(
            sector_ratios
        ),

        anisotropy=anisotropy,

        dominant_sector=(
            dominant_sector
        ),

        dominant_angle_degrees=(
            math.degrees(
                dominant_angle
            )
        ),

        road_density_km_per_100km2=(
            road_density
        ),

        directional_entropy=(
            directional_entropy
        ),

        east_west_ratio=(
            east_west_ratio
        ),

        north_south_ratio=(
            north_south_ratio
        ),

        diagonal_ratio=(
            diagonal_ratio
        ),

        network_vector_x=(
            network_vector_x
        ),

        network_vector_y=(
            network_vector_y
        ),

        alignment_with_capital=(
            alignment
        ),

        road_count=len(
            data.get(
                "elements",
                [],
            )
        ),
    )


