def load_all_roads(
    force: bool = False,
) -> dict[str, RoadGeometry]:

    results = {}

    for state in STATES:

        try:

            data = download_roads(
                state,
                force=force,
            )

            geometry = (
                calculate_road_geometry(
                    state,
                    data,
                )
            )

            results[state] = geometry

            print()
            print(
                state,
                "road length:",
                f"{geometry.total_length_km:,.2f}",
                "km",
            )

            print(
                "  density:",
                f"{geometry.road_density_km_per_100km2:.3f}",
            )

            print(
                "  anisotropy:",
                f"{geometry.anisotropy:.4f}",
            )

            print(
                "  dominant angle:",
                f"{geometry.dominant_angle_degrees:.2f}°",
            )

            print(
                "  entropy:",
                f"{geometry.directional_entropy:.4f}",
            )

        except Exception as exc:

            print()
            print(
                f"ROAD DATA FAILED "
                f"FOR {state}:"
            )

            print(
                exc
            )

    return results


