def make_regions(
    dwellings,
    earnings,
    ppi,
    building,
    roads,
) -> list[RegionalData]:

    records = []

    for state, name in STATES.items():

        dwelling = dwellings.get(
            state,
            {},
        )

        ppi_state = ppi.get(
            state,
            {},
        )

        weekly = earnings.get(
            state
        )

        building_value = building.get(
            state
        )

        annual_income = (
            None
            if weekly is None
            else weekly * 52.0
        )

        latitude, longitude = (
            STATE_CENTROIDS[state]
        )

        road = roads.get(
            state
        )

        fields = [
            dwelling.get("count"),
            dwelling.get("mean"),
            dwelling.get("median"),
            weekly,
            ppi_state.get("annual"),
            building_value,
            road,
        ]

        available = sum(
            x is not None
            for x in fields
        )

        data_coverage = (
            available
            / len(fields)
        )

        confidence = math.sqrt(
            data_coverage
        )

        records.append(
            RegionalData(
                state=state,

                state_name=name,

                latitude=latitude,

                longitude=longitude,

                dwelling_count=(
                    dwelling.get(
                        "count"
                    )
                ),

                dwelling_total_value=None,

                mean_dwelling_price=(
                    dwelling.get(
                        "mean"
                    )
                ),

                median_dwelling_price=(
                    dwelling.get(
                        "median"
                    )
                ),

                weekly_earnings=weekly,

                annual_income=annual_income,

                construction_quarter_change=(
                    ppi_state.get(
                        "quarter"
                    )
                ),

                construction_annual_change=(
                    ppi_state.get(
                        "annual"
                    )
                ),

                building_work_value=(
                    building_value
                ),

                road=road,

                data_coverage=(
                    data_coverage
                ),

                confidence=(
                    confidence
                ),
            )
        )

    return records


# ============================================================
# NORMALIZATION
# ============================================================

def log_normalize(
    values,
) -> np.ndarray:

    array = np.asarray(
        [
            np.nan
            if x is None
            else float(x)
            for x in values
        ],
        dtype=np.float64,
    )

    result = np.zeros_like(
        array
    )

    valid = (
        np.isfinite(array)
        & (array > 0)
    )

    if not np.any(valid):
        return result

    transformed = np.log1p(
        array[valid]
    )

    low = transformed.min()
    high = transformed.max()

    if high == low:

        result[valid] = 1.0

    else:

        result[valid] = (
            transformed - low
        ) / (
            high - low
        )

    return result


def normalize(
    values,
) -> np.ndarray:

    array = np.asarray(
        [
            np.nan
            if x is None
            else float(x)
            for x in values
        ],
        dtype=np.float64,
    )

    result = np.zeros_like(
        array
    )

    valid = np.isfinite(
        array
    )

    if not np.any(valid):
        return result

    low = array[valid].min()
    high = array[valid].max()

    if high == low:

        result[valid] = 1.0

    else:

        result[valid] = (
            array[valid] - low
        ) / (
            high - low
        )

    return result


# ============================================================
# VECTOR GEOMETRY SCORE
# ============================================================

def road_geometry_scores(
    records: list[RegionalData],
) -> np.ndarray:

    anisotropy = np.asarray(
        [
            0.0
            if r.road is None
            else r.road.anisotropy
            for r in records
        ]
    )

    density = np.asarray(
        [
            0.0
            if r.road is None
            else r.road.road_density_km_per_100km2
            for r in records
        ]
    )

    alignment = np.asarray(
        [
            0.0
            if r.road is None
            else r.road.alignment_with_capital
            for r in records
        ]
    )

    # Vector geometric score.
    #
    # Density measures network availability.
    # Anisotropy measures directional structure.
    # Alignment measures coherent radial structure.
    #
    # The three components are normalized separately.

    density_score = log_normalize(
        density
    )

    anisotropy_score = normalize(
        anisotropy
    )

    alignment_score = normalize(
        alignment
    )

    return (
        0.45
        * density_score
        +
        0.30
        * anisotropy_score
        +
        0.25
        * alignment_score
    )


# ============================================================
# PRECISE PREDICTION
# ============================================================

def predict(
    records: list[RegionalData],
) -> list[Prediction]:

    property_values = [
        r.mean_dwelling_price
        for r in records
    ]

    income_values = [
        r.annual_income
        for r in records
    ]

    construction_values = [
        r.construction_annual_change
        for r in records
    ]

    building_values = [
        r.building_work_value
        for r in records
    ]

    dwelling_values = [
        r.dwelling_count
        for r in records
    ]

    property_score = log_normalize(
        property_values
    )

    income_score = log_normalize(
        income_values
    )

    construction_score = normalize(
        construction_values
    )

    building_score = log_normalize(
        building_values
    )

    dwelling_score = log_normalize(
        dwelling_values
    )

    road_score = (
        road_geometry_scores(
            records
        )
    )

    # --------------------------------------------------------
    # Final weighting.
    #
    # Economic:
    #   25% property
    #   15% income
    #   10% construction
    #   15% building activity
    #   10% dwelling stock
    #
    # Geometry:
    #   15% road geometry
    #   10% road density/alignment
    #
    # Total = 100%
    # --------------------------------------------------------

    raw = (
        0.25
        * property_score

        + 0.15
        * income_score

        + 0.10
        * construction_score

        + 0.15
        * building_score

        + 0.10
        * dwelling_score

        + 0.15
        * road_score

        + 0.10
        * road_score
    )

    confidence = np.asarray(
        [
            r.confidence
            for r in records
        ]
    )

    final_score = (
        raw
        * confidence
    )

    order = np.argsort(
        -final_score
    )

    predictions = []

    for rank, i in enumerate(
        order,
        start=1,
    ):

        r = records[i]

        road = r.road

        predictions.append(
            Prediction(
                rank=rank,

                state=r.state,

                score=float(
                    final_score[i]
                ),

                property_score=float(
                    0.25
                    * property_score[i]
                ),

                income_score=float(
                    0.15
                    * income_score[i]
                ),

                construction_score=float(
                    0.10
                    * construction_score[i]
                ),

                building_score=float(
                    0.15
                    * building_score[i]
                ),

                dwelling_stock_score=float(
                    0.10
                    * dwelling_score[i]
                ),

                road_density_score=float(
                    0.15
                    * road_score[i]
                ),

                road_geometry_score=float(
                    0.10
                    * road_score[i]
                ),

                road_alignment_score=(
                    0.0
                    if road is None
                    else road.alignment_with_capital
                ),

                confidence=float(
                    r.confidence
                ),

                data_coverage=float(
                    r.data_coverage
                ),

                mean_dwelling_price=(
                    r.mean_dwelling_price
                ),

                median_dwelling_price=(
                    r.median_dwelling_price
                ),

                weekly_earnings=(
                    r.weekly_earnings
                ),

                annual_income=(
                    r.annual_income
                ),

                dwelling_count=(
                    r.dwelling_count
                ),

                dwelling_total_value=(
                    r.dwelling_total_value
                ),

                construction_annual_change=(
                    r.construction_annual_change
                ),

                building_work_value=(
                    r.building_work_value
