def prime_factors(
    n: int,
) -> dict[int, int]:

    result = {}

    d = 2

    while d * d <= n:

        while n % d == 0:

            result[d] = (
                result.get(
                    d,
                    0,
                )
                + 1
            )

            n //= d

        d = (
            3
            if d == 2
            else d + 2
        )

    if n > 1:

        result[n] = (
            result.get(
                n,
                0,
            )
            + 1
        )

    return result


def product_solver(
    candidates: list[Candidate],
    target: int,
    beam_width: int = 256,
) -> list[Candidate]:

    factors = prime_factors(
        target
    )

    primes = tuple(
        sorted(factors)
    )

    target_vector = tuple(
        factors[p]
        for p in primes
    )

    states = {
        tuple(
            0
            for _ in primes
        ): []
    }

    for candidate in candidates:

        vector = []

        remainder = candidate.value

        valid = True

        for prime in primes:

            exponent = 0

            while (
                remainder % prime == 0
            ):

                remainder //= prime
                exponent += 1

            vector.append(
                exponent
            )

        if remainder != 1:
            continue

        vector = tuple(
            vector
        )

        next_states = dict(
            states
        )

        for current, path in (
            states.items()
        ):

            combined = tuple(
                a + b
                for a, b in zip(
                    current,
                    vector,
                )
            )

            if any(
                x > y
                for x, y in zip(
                    combined,
                    target_vector,
                )
            ):
                continue

            new_path = (
                path
                + [candidate]
            )

            if (
                combined
                == target_vector
            ):

                return new_path

            next_states[
                combined
            ] = new_path

        ranked = sorted(
            next_states.items(),
            key=lambda item:
                sum(
                    y - x
                    for x, y in zip(
                        item[0],
                        target_vector,
                    )
                ),
        )

        states = dict(
            ranked[
                :beam_width
            ]
        )

    return []


