@dataclass(frozen=True)
class Location:
    latitude: float
    longitude: float

    def distance_to(
        self,
        other: "Location",
    ) -> float:
        """
        Haversine distance in kilometres.
        """

        radius = 6371.0

        lat1 = math.radians(
            self.latitude
        )

        lat2 = math.radians(
            other.latitude
        )

        dlat = math.radians(
            other.latitude
            - self.latitude
        )

        dlon = math.radians(
            other.longitude
            - self.longitude
        )

        a = (
            math.sin(dlat / 2.0) ** 2
            +
            math.cos(lat1)
            * math.cos(lat2)
            * math.sin(dlon / 2.0) ** 2
        )

        return (
            radius
            * 2.0
            * math.atan2(
                math.sqrt(a),
                math.sqrt(
                    max(
                        0.0,
                        1.0 - a,
                    )
                ),
            )
        )


