    url: str,
    timeout: int = 60,
) -> bytes:

    request = make_request(
        url
    )

    with urlopen(
        request,
        timeout=timeout,
    ) as response:

        return response.read()


def download_text(
    url: str,
    timeout: int = 60,
) -> str:

    data = download_bytes(
        url,
        timeout=timeout,
    )

    return data.decode(
        "utf-8",
        errors="replace",
    )


def sha256_bytes(
    data: bytes,
) -> str:

    return hashlib.sha256(
        data
    ).hexdigest()


def cached_download(
    url: str,
    path: Path,
    *,
    force: bool = False,
) -> bytes:

    if (
        path.exists()
        and not force
    ):

        age = (
            time.time()
            - path.stat().st_mtime
        )

        if age < CACHE_MAX_AGE_SECONDS:

            return path.read_bytes()

    print(
        f"  downloading {url}"
    )

    data = download_bytes(
        url
    )

    path.write_bytes(
        data
    )

    return data


# ============================================================
# ABS PAGE DISCOVERY
# ============================================================

def find_download_links(
    html: str,
    base_url: str,
) -> list[str]:

    links = []

    # href="..."
    hrefs = re.findall(
        r'href\s*=\s*["\']([^"\']+)["\']',
        html,
        flags=re.IGNORECASE,
    )

    for href in hrefs:

        href = href.strip()

        if not href:
            continue

        absolute = urljoin(
            base_url,
            href,
        )

        lower = absolute.lower()

        if any(
            extension in lower
            for extension in (
                ".xlsx",
                ".xls",
                ".csv",
                ".zip",
            )
        ):

            links.append(
                absolute
            )

    # Remove duplicates.
    return list(
        dict.fromkeys(
            links
        )
    )


def discover_abs_files(
    page_name: str,
    html: str,
) -> list[str]:

    base_url = ABS_PAGES[
        page_name
    ]

    links = find_download_links(
        html,
        base_url,
    )

    print()
    print(
        f"ABS {page_name} "
        f"download links: "
        f"{len(links)}"
    )

    for link in links:

        print(
            " ",
            link,
        )

    return links


# ============================================================
# TEXT NORMALIZATION
# ============================================================

def html_to_text(
    html: str,
) -> str:

    text = re.sub(
        r"<script\b[^>]*>.*?</script>",
        " ",
        html,
        flags=(
            re.IGNORECASE
            | re.DOTALL
        ),
    )

    text = re.sub(
        r"<style\b[^>]*>.*?</style>",
        " ",
        text,
        flags=(
            re.IGNORECASE
            | re.DOTALL
        ),
    )

    text = re.sub(
        r"<[^>]+>",
        " ",
        text,
    )

    replacements = {
        "&nbsp;": " ",
        "&#160;": " ",
        "&amp;": "&",
        "&dollar;": "$",
        "&#36;": "$",
        "&ndash;": "-",
        "&mdash;": "-",
        "&#8211;": "-",
        "&#8212;": "-",
    }

    for old, new in (
        replacements.items()
    ):

        text = text.replace(
            old,
            new,
        )

    return re.sub(
        r"\s+",
        " ",
        text,
    ).strip()


def clean_number(
    value: str,
) -> Optional[float]:

    if value is None:
        return None

    value = (
        str(value)
        .replace(
            ",",
            "",
        )
        .replace(
            "$",
            "",
        )
        .replace(
            "%",
            "",
        )
        .strip()
    )

    match = re.search(
        r"-?\d+(?:\.\d+)?",
        value,
    )

    if not match:
        return None

    try:

        return float(
            match.group(0)
        )

    except ValueError:

        return None


# ============================================================
# ROBUST NUMERIC EXTRACTION
# ============================================================

def find_dollar_values(
    text: str,
) -> list[float]:

    values = []

    for raw in re.findall(
        r"\$"
        r"\s*"
        r"([\d,]+(?:\.\d+)?)",
        text,
    ):

        value = clean_number(
            raw
        )

        if value is not None:

            values.append(
                value
            )

    return values


def find_values_near_keyword(
    text: str,
    keywords: list[str],
    *,
    window: int = 2500,
    minimum: float = 0,
    maximum: float = float("inf"),
) -> list[float]:

    values = []

    for keyword in keywords:

        for match in re.finditer(
            re.escape(keyword),
            text,
            flags=re.IGNORECASE,
        ):

            start = max(
                0,
                match.start()
                - window,
            )

            end = min(
                len(text),
                match.end()
                + window,
            )

            context = text[
                start:end
            ]

            for value in (
                find_dollar_values(
                    context
                )
            ):

                if (
                    minimum
                    <= value
                    <= maximum
                ):

                    values.append(
                        value
                    )

    return values


def median_or_none(
    values: list[float],
) -> Optional[float]:

    if not values:
        return None

    return float(
        statistics.median(
            values
        )
    )


# ============================================================
# ABS DWELLING EXTRACTION
# ============================================================

def extract_latest_mean_price(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    values = find_values_near_keyword(
        text,
        [
            "mean price",
            "mean dwelling price",
            "average dwelling price",
            "residential dwelling price",
        ],
        window=1200,
        minimum=300_000,
        maximum=5_000_000,
    )

    if values:

        # The ABS page can mention several periods.
        # The latest/current release value is normally
        # one of the largest nearby values.
        return max(values)

    # Broader fallback.
    all_values = [
        value
        for value in find_dollar_values(
            text
        )
        if (
            300_000
            <= value
            <= 5_000_000
        )
    ]

    if all_values:

        return max(
            all_values
        )

    raise RuntimeError(
        "Could not extract mean dwelling price"
    )


def extract_total_dwellings_value(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    trillion_patterns = [
        r"total value"
        r".{0,1000}?"
        r"\$([\d,.]+)"
        r"\s*trillion",

        r"value of residential dwellings"
        r".{0,1000}?"
        r"\$([\d,.]+)"
        r"\s*trillion",
    ]

    for pattern in (
        trillion_patterns
    ):

        matches = re.findall(
            pattern,
            text,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        )

        for raw in matches:

            value = clean_number(
                raw
            )

            if (
                value is not None
                and 1 <= value <= 100
            ):

                return (
                    value
                    * 1000.0
                )

    billion_values = []

    for raw in re.findall(
        r"\$([\d,.]+)"
        r"\s*billion",
        text,
        flags=re.IGNORECASE,
    ):

        value = clean_number(
            raw
        )

        if (
            value is not None
            and 1000 <= value <= 50000
        ):

            billion_values.append(
                value
            )

    if billion_values:

        return max(
            billion_values
        )

    raise RuntimeError(
        "Could not extract total dwelling value"
    )


def extract_dwellings_count(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    patterns = [
        r"number of residential dwellings"
        r".{0,1000}?"
        r"([\d,]+)"
        r"\s*(?:dwellings)?",

        r"residential dwellings"
        r".{0,500}?"
        r"([\d,]+)",
    ]

    candidates = []

    for pattern in patterns:

        for raw in re.findall(
            pattern,
            text,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        ):

            value = clean_number(
                raw
            )

            if (
                value is not None
                and 5_000_000
                <= value
                <= 20_000_000
            ):

                candidates.append(
                    value
                )

    if candidates:

        return max(
            candidates
        )

    raise RuntimeError(
        "Could not extract dwelling count"
    )


# ============================================================
# ABS EARNINGS EXTRACTION
# ============================================================

def extract_national_weekly_earnings(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    # --------------------------------------------------------
    # First look specifically near earnings terminology.
    # --------------------------------------------------------

    values = find_values_near_keyword(
        text,
        [
            "average weekly earnings",
            "weekly earnings",
            "ordinary time earnings",
            "total hourly rates",
        ],
        window=1800,
        minimum=500,
        maximum=10000,
    )

    if values:

        # Median avoids accidentally selecting a
        # nearby unrelated amount.
        return float(
            statistics.median(
                values
            )
        )

    # --------------------------------------------------------
    # Regex patterns used by different ABS releases.
    # --------------------------------------------------------

    patterns = [

        r"\$([\d,]+(?:\.\d+)?)"
        r"\s*(?:a|per)\s+week",

        r"(?:earnings|wages)"
        r".{0,500}?"
        r"\$([\d,]+(?:\.\d+)?)",

        r"weekly"
        r".{0,1000}?"
        r"\$([\d,]+(?:\.\d+)?)",
    ]

    candidates = []

    for pattern in patterns:

        for raw in re.findall(
            pattern,
            text,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        ):

            value = clean_number(
                raw
            )

            if (
                value is not None
                and 500 <= value <= 10000
            ):

                candidates.append(
                    value
                )

    if candidates:

        return float(
            statistics.median(
                candidates
            )
        )

    # --------------------------------------------------------
    # Last fallback: inspect all plausible weekly amounts.
    # --------------------------------------------------------

    dollar_values = [
        value
        for value in find_dollar_values(
            text
        )
        if (
            500 <= value <= 10000
        )
    ]

    if dollar_values:

        return float(
            statistics.median(
                dollar_values
            )
        )

    raise RuntimeError(
        "Could not extract weekly earnings"
    )


# ============================================================
# CONSTRUCTION COST EXTRACTION
# ============================================================

def extract_construction_change(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    patterns = [

        r"house construction"
        r".{0,1000}?"
        r"rose\s+([\d.]+)%",

        r"house construction"
        r".{0,1000}?"
        r"([+-]?[\d.]+)%",

        r"construction"
        r".{0,1000}?"
        r"([+-]?[\d.]+)%",

    ]

    candidates = []

    for pattern in patterns:

        for raw in re.findall(
            pattern,
            text,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        ):

            value = clean_number(
                raw
            )

            if (
                value is not None
                and -20 <= value <= 50
            ):

                candidates.append(
                    value
                )

    if candidates:

        return float(
            statistics.median(
                candidates
            )
        )

    # A missing construction index should not
    # prevent the rest of the data pipeline.
    return 0.0


# ============================================================
# VICTORIA EXTRACTION
# ============================================================

def extract_victoria_change(
    html: str,
) -> float:

    text = html_to_text(
        html
    )

    # Search within a relatively small context
    # around Victoria.
    for match in re.finditer(
        r"Victoria",
        text,
        flags=re.IGNORECASE,
    ):

        context = text[
            max(
                0,
                match.start() - 300,
            ):
            min(
                len(text),
                match.end() + 700,
            )
        ]

        percentages = re.findall(
            r"([+-]?[\d.]+)\s*%",
            context,
        )

        values = []

        for raw in percentages:

            value = clean_number(
                raw
            )

            if (
                value is not None
                and -50 <= value <= 50
            ):

                values.append(
                    value
                )

        if values:

            return float(
                values[0]
            )

    return 0.0


