def download_url(
    url: str,
    destination: Path,
    timeout: int = 30,
) -> str:

    request = Request(
        url,
        headers={
            "User-Agent": USER_AGENT,
            "Accept": "text/html,application/xhtml+xml",
        },
    )

    with urlopen(
        request,
        timeout=timeout,
    ) as response:

        data = response.read()

    destination.write_bytes(data)

    return data.decode(
        "utf-8",
        errors="replace",
    )


def sha256_file(
    path: Path,
) -> str:

    digest = hashlib.sha256()

    with path.open("rb") as handle:

        while True:

            chunk = handle.read(
                1024 * 1024
            )

            if not chunk:
                break

            digest.update(chunk)

    return digest.hexdigest()


