    ) in sources.items():

        print(
            f"downloading {name}:"
        )

        try:

            download_url(
                url,
                destination,
            )

            print(
                f"saved {destination}"
            )

            print(
                f"sha256 "
                f"{sha256_file(destination)}"
            )

            paths[name] = destination

        except Exception as exc:

            print(
                f"download failed: {exc}"
            )

    return paths


# ============================================================
# HTML EXTRACTION
#
# We deliberately avoid hard-coding the current ABS numbers.
# The program downloads the current ABS pages and extracts
# numeric information from the latest release.
# ============================================================

def clean_number(
    value: str,
) -> Optional[float]:

    value = value.replace(
        ",",
        "",
    )

    value = value.replace(
        "$",
        "",
    )

    value = value.replace(
        "%",
        "",
    )

    value = value.strip()

    match = re.search(
        r"-?\d+(?:\.\d+)?",
        value,
    )

    if not match:
        return None

    try:
        return float(
            match.group(0)
        )
    except ValueError:
        return None


def extract_latest_mean_price(
    html: str,
) -> float:

    """
    Extract the current national mean dwelling price.

    The ABS page currently states the latest mean price
    explicitly. The parser searches for the phrase rather
    than relying on a fixed number.
    """

    patterns = [
        r"mean price of residential dwellings "
        r"fell by \$[\d,.]+ to \$([\d,.]+)",

        r"mean price of residential dwellings "
        r"rose by \$[\d,.]+ to \$([\d,.]+)",

        r"mean price of residential dwellings "
        r"was \$([\d,.]+)",
    ]

    for pattern in patterns:

        match = re.search(
            pattern,
            html,
            flags=re.IGNORECASE,
        )

        if match:

            number = clean_number(
                match.group(1)
            )

            if number is not None:
                return number

    raise RuntimeError(
        "Could not extract ABS mean dwelling price"
    )


def extract_total_dwellings_value(
    html: str,
) -> float:

    patterns = [
        r"total value of residential dwellings "
        r"in Australia.*?"
        r"\$([\d,.]+)\s*billion",

        r"total value of residential dwellings "
        r"in Australia.*?"
        r"\$([\d,.]+)\s*trillion",
    ]

    for pattern in patterns:

        match = re.search(
            pattern,
            html,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        )

        if not match:
            continue

        value = clean_number(
            match.group(1)
        )

        if value is None:
            continue

        if "trillion" in pattern:
            return value * 1000.0

        return value

    raise RuntimeError(
        "Could not extract total dwelling value"
    )


def extract_dwellings_count(
    html: str,
) -> float:

    patterns = [
        r"number of residential dwellings "
        r"in Australia rose by [\d,]+ "
        r"to ([\d,]+)",

        r"number of residential dwellings.*?"
        r"to ([\d,]+)",
    ]

    for pattern in patterns:

        match = re.search(
            pattern,
            html,
            flags=(
                re.IGNORECASE
                | re.DOTALL
            ),
        )

        if match:

            value = clean_number(
                match.group(1)
            )

            if value is not None:
                return value

    raise RuntimeError(
        "Could not extract dwelling count"
    )


def extract_victoria_change(
    html: str,
) -> float:

    match = re.search(
        r"Victoria\s*"
        r"\(\s*([+-]?[\d.]+)%"
        r"\s*or",
        html,
        flags=re.IGNORECASE,
    )

    if match:

        value = clean_number(
            match.group(1)
        )

        if value is not None:
            return value

    return 0.0


def extract_national_weekly_earnings(
    html: str,
) -> float:

    patterns = [
        r"increased by [\d.]+% annually "
        r"to \$([\d,.]+)",

        r"annually to \$([\d,.]+)",
    ]

    for pattern in patterns:

        match = re.search(
            pattern,
            html,
            flags=re.IGNORECASE,
        )

        if match:

            value = clean_number(
                match.group(1)
            )

            if value is not None:
                return value

    raise RuntimeError(
        "Could not extract weekly earnings"
    )


def extract_construction_change(
    html: str,
) -> float:

    patterns = [
        r"House construction prices "
        r"rose ([\d.]+)%",

        r"house construction prices "
        r"rose ([\d.]+)%",
    ]

    for pattern in patterns:

        match = re.search(
            pattern,
            html,
            flags=re.IGNORECASE,
        )

        if match:

            value = clean_number(
                match.group(1)
            )

            if value is not None:
                return value

    return 0.0


# ============================================================
# REGIONAL REAL-DATA MODEL
# ============================================================

@dataclass
class ABSData:

    mean_dwelling_price: float

    total_dwelling_value_billions: float

    dwelling_count: float

    weekly_earnings: float

    construction_change_percent: float

    victoria_dwelling_change_percent: float

    downloaded_at: float


def load_real_abs_data(
    downloaded_paths: dict[str, Path],
) -> ABSData:

    dwelling_html = (
        downloaded_paths["dwellings"]
        .read_text(
            encoding="utf-8",
            errors="replace",
        )
    )

    earnings_html = (
        downloaded_paths["earnings"]
        .read_text(
            encoding="utf-8",
            errors="replace",
        )
    )

    ppi_html = (
        downloaded_paths["ppi"]
        .read_text(
            encoding="utf-8",
            errors="replace",
        )
    )

    mean_price = (
        extract_latest_mean_price(
            dwelling_html
        )
    )

    total_value = (
        extract_total_dwellings_value(
            dwelling_html
        )
    )

    dwelling_count = (
        extract_dwellings_count(
            dwelling_html
        )
    )

    weekly_earnings = (
        extract_national_weekly_earnings(
            earnings_html
        )
    )

    construction_change = (
        extract_construction_change(
            ppi_html
        )
    )

    victoria_change = (
        extract_victoria_change(
            dwelling_html
        )
    )

    return ABSData(
        mean_dwelling_price=mean_price,
        total_dwelling_value_billions=(
            total_value
        ),
        dwelling_count=dwelling_count,
        weekly_earnings=weekly_earnings,
        construction_change_percent=(
            construction_change
        ),
        victoria_dwelling_change_percent=(
            victoria_change
        ),
        downloaded_at=time.time(),
    )


# ============================================================
# REGIONAL DATA
#
# We use real ABS national data as the base and apply regional
# adjustment factors. These adjustments are explicitly marked
# as estimates rather than pretending the national mean is a
# state-level observation.
# ============================================================

REGIONAL_FACTORS = {
    "NSW": 1.18,
    "VIC": 1.00,
    "QLD": 1.03,
    "WA": 1.02,
    "SA": 0.89,
    "TAS": 0.67,
    "NT": 0.56,
    "ACT": 0.89,
}


def build_real_people(
    data: ABSData,
) -> list[Person]:

    people: list[Person] = []

    states = list(
        STATE_LOCATIONS.keys()
    )

    for index, state in enumerate(
        states
    ):

        latitude, longitude = (
            STATE_LOCATIONS[state]
        )

        regional_factor = (
            REGIONAL_FACTORS[state]
        )

        dwelling_price = (
            data.mean_dwelling_price
            * regional_factor
        )

        # Annualised earnings from weekly earnings.
        annual_income = (
            data.weekly_earnings
            * 52.0
        )

        regional_income = (
            annual_income
            * (
                0.90
                + 0.20
                * regional_factor
            )
        )

        # Generic construction estimate.
        #
        # This is deliberately a broad model:
        #
        # building_cost =
        #     dwelling value
        #     × construction share
        #     × current PPI adjustment
        #
        construction_share = 0.35

        building_cost = (
            dwelling_price
            * construction_share
            * (
                1.0
                + data.construction_change_percent
                / 100.0
            )
        )

        price_low = (
            dwelling_price * 0.80
        )

        price_high = (
            dwelling_price * 1.20
        )

        person = Person(
            person_id=index,
            name=index,

            # Use small integer factors so the original
            # multiplicative solver remains usable.
            value=(
                index + 2
            ),

            attributes=(
                index,
                int(
                    regional_factor * 10
                ),
            ),

            metadata=(
                int(
                    dwelling_price
                    / 100_000
                ),
            ),

            individual_id=(
                100000 + index
            ),

            location=Location(
                latitude,
                longitude,
            ),

            income=int(
                regional_income
            ),

            building_cost=int(
                building_cost
            ),

            generic_price=PriceRange(
                int(price_low),
                int(price_high),
            ),

            # For the prediction model the source is
            # represented by a slightly displaced
            # regional economic origin.
            source_location=Location(
                latitude + 0.5,
                longitude + 0.5,
            ),

            region=state,
        )

        people.append(person)

    return people


# ============================================================
# CANDIDATES
# ============================================================

def make_candidates(
    people: list[Person],
) -> list[Candidate]:

    candidates: list[Candidate] = []

    for index, person in enumerate(
        people
    ):

        candidates.append(
            Candidate(
                block=index,
                person=person,
                category=index % 3,
            )
        )

    return candidates


# ============================================================
# FACTORIZATION
# ============================================================

def factor_integer(
    target: int,
) -> dict[int, int]:

    factors: dict[int, int] = {}

    remaining = target
    divisor = 2

    while (
        divisor * divisor
        <= remaining
    ):

        while (
            remaining % divisor == 0
        ):

            factors[divisor] = (
                factors.get(
                    divisor,
                    0,
                )
                + 1
            )

            remaining //= divisor

        if divisor == 2:
            divisor = 3
        else:
            divisor += 2

    if remaining > 1:
        factors[remaining] = (
            factors.get(
                remaining,
                0,
            )
            + 1
        )

    return factors


def factor_vector(
    value: int,
    primes: tuple[int, ...],
) -> Optional[
    tuple[int, ...]
]:

    exponents = []
    remaining = value

    for prime in primes:

        exponent = 0

        while (
            remaining % prime == 0
        ):

            remaining //= prime
            exponent += 1

        exponents.append(
            exponent
        )

    if remaining != 1:
        return None

    return tuple(exponents)


def add_vectors(
    left: tuple[int, ...],
    right: tuple[int, ...],
) -> tuple[int, ...]:

    return tuple(
        a + b
        for a, b in zip(
            left,
            right,
        )
    )


def vector_within_target(
    vector: tuple[int, ...],
    target_vector: tuple[int, ...],
) -> bool:

    return all(
        a <= b
        for a, b in zip(
            vector,
            target_vector,
        )
    )


def vector_distance(
    vector: tuple[int, ...],
    target_vector: tuple[int, ...],
) -> int:

    return sum(
        b - a
        for a, b in zip(
            vector,
            target_vector,
        )
    )


# ============================================================
# PATH
# ============================================================

def materialize_path(
    node: Optional[PathNode],
) -> list[Candidate]:

    result = []

    while node is not None:

        result.append(
            node.candidate
        )

        node = node.parent

    result.reverse()

    return result


def product_of_candidates(
    candidates: Iterable[Candidate],
) -> int:

    result = 1

    for candidate in candidates:
        result *= candidate.person.value

    return result


# ============================================================
# SOLUTION MATRIX
# ============================================================

def build_solution_matrix(
    selected_candidates: list[Candidate],
    all_candidates: list[Candidate],
    target: int,
) -> SolutionMatrix:

    selected_by_block = {
        candidate.block: candidate
        for candidate in selected_candidates
    }

    rows = []

    for candidate in all_candidates:

        person = candidate.person

        selected = int(
            selected_by_block.get(
                candidate.block
            )
            == candidate
        )

        location = person.location
        source = person.source_location

        price = person.generic_price

        rows.append(
            [
                candidate.block,
                person.person_id,
                person.name,
                candidate.category,
                person.value,
                selected,

                person.individual_id,

                (
                    0.0
                    if location is None
                    else location.latitude
                ),

                (
                    0.0
                    if location is None
                    else location.longitude
                ),

                person.income,
                person.building_cost,

                (
                    0
                    if price is None
                    else price.minimum
                ),

                (
                    0
                    if price is None
                    else price.maximum
                ),

                (
                    0.0
                    if source is None
                    else source.latitude
                ),

                (
                    0.0
                    if source is None
                    else source.longitude
                ),
            ]
        )

    product = (
        product_of_candidates(
            selected_candidates
        )
    )

    return SolutionMatrix(
        rows=rows,
        selected_candidates=(
            selected_candidates
        ),
        product=product,
        target=target,
        matched=(
            product == target
        ),
    )


# ============================================================
# NUMERIC SOLVER
# ============================================================

def solve_numeric_people(
    people: Iterable[Person],
    candidates: Iterable[Candidate],
    target: int,
    *,
    max_beam_width: int = 2000,
    return_best: bool = True,
) -> tuple[
    Optional[SolutionMatrix],
    dict[str, Any],
]:

    people = list(people)
    candidates = list(candidates)

    factorization = (
        factor_integer(target)
    )

    primes = tuple(
        sorted(
            factorization
        )
    )

    target_vector = tuple(
        factorization[p]
        for p in primes
    )

    prepared_blocks = {}

    discarded = []

    for candidate in candidates:

        vector = factor_vector(
            candidate.person.value,
            primes,
        )

        if vector is None:

            discarded.append(
                candidate
            )

            continue

        prepared_blocks.setdefault(
            candidate.block,
            [],
        ).append(
            (
                candidate,
                vector,
            )
        )

    zero = tuple(
        0 for _ in primes
    )

    beam = {
        zero: None
    }

    states_created = 1
    blocks_processed = 0
    best_vector = zero

    for block in sorted(
        prepared_blocks
    ):

        blocks_processed += 1

        next_states = {}

        for (
            current_vector,
            node,
        ) in beam.items():

            next_states.setdefault(
                current_vector,
                node,
            )

            for (
                candidate,
                candidate_vector,
            ) in prepared_blocks[
                block
            ]:

                new_vector = (
                    add_vectors(
                        current_vector,
                        candidate_vector,
                    )
                )

                if not vector_within_target(
                    new_vector,
                    target_vector,
                ):
                    continue

                if (
                    new_vector
                    not in next_states
                ):

                    next_states[
                        new_vector
                    ] = PathNode(
                        candidate=candidate,
                        parent=node,
                    )

        states_created += (
            len(next_states)
        )

        if (
            target_vector
            in next_states
        ):

            selected = (
                materialize_path(
                    next_states[
                        target_vector
                    ]
                )
            )

            return (
                build_solution_matrix(
                    selected,
                    candidates,
                    target,
                ),
                {
                    "found": 1,
                    "states_created":
                        states_created,
                    "blocks_processed":
                        blocks_processed,
                    "discarded":
                        discarded,
                    "target_factors":
                        factorization,
                },
            )

        if not next_states:
            break

        best_vector = min(
            next_states,
            key=lambda vector:
                vector_distance(
                    vector,
                    target_vector,
                ),
        )

        if (
            len(next_states)
            > max_beam_width
        ):

            retained = heapq.nsmallest(
                max_beam_width,
                next_states.items(),
                key=lambda item:
                    vector_distance(
                        item[0],
                        target_vector,
                    ),
            )

            beam = dict(
                retained
            )

        else:

            beam = next_states

    if return_best and beam:

        selected = (
            materialize_path(
                beam[best_vector]
            )
        )

        return (
            build_solution_matrix(
                selected,
                candidates,
                target,
            ),
            {
                "found": 0,
                "states_created":
                    states_created,
                "blocks_processed":
                    blocks_processed,
                "discarded":
                    discarded,
                "target_factors":
                    factorization,
            },
        )

    return (
        None,
        {
            "found": 0,
            "states_created":
                states_created,
            "blocks_processed":
                blocks_processed,
            "discarded":
                discarded,
            "target_factors":
                factorization,
        },
    )


# ============================================================
# BIG-THING PREDICTOR
# ============================================================

def normalize(
    values: list[float],
) -> list[float]:

    if not values:
        return []

    minimum = min(values)
    maximum = max(values)

    if maximum == minimum:
        return [
            1.0
            for _ in values
        ]

    return [
        (
            value - minimum
        )
        / (
            maximum - minimum
        )
        for value in values
    ]


def predict_big_things(
    people: Iterable[Person],
    *,
    top_k: int = 10,
    income_weight: float = 0.25,
    property_weight: float = 0.35,
    construction_weight: float = 0.25,
    proximity_weight: float = 0.15,
) -> list[Prediction]:

    people = list(people)

    income = [
        float(person.income)
        for person in people
    ]

    property_values = [
        (
            0.0
            if person.generic_price is None
            else person.generic_price.midpoint
        )
        for person in people
    ]

    construction = [
        float(person.building_cost)
        for person in people
    ]

    income_n = normalize(
        income
    )

    property_n = normalize(
        property_values
    )

    construction_n = normalize(
        construction
    )

    proximity_values = []

    distances = []

    for person in people:

        if (
            person.location is None
            or person.source_location is None
        ):

            distances.append(
                None
            )

            proximity_values.append(
                0.0
            )

            continue

        distance = (
            person.location.distance_to(
                person.source_location
            )
        )

        distances.append(
            distance
        )

        proximity_values.append(
            math.exp(
                -distance / 500.0
            )
        )

    proximity_n = normalize(
        proximity_values
    )

    predictions = []

    for index, person in enumerate(
        people
    ):

        score = (
            income_weight
            * income_n[index]
            + property_weight
            * property_n[index]
            + construction_weight
            * construction_n[index]
            + proximity_weight
            * proximity_n[index]
        )

        location = (
            person.location
            if person.location is not None
            else Location(
                0.0,
                0.0,
            )
        )

        price = (
            person.generic_price
        )

        predictions.append(
            Prediction(
                rank=0,

                region=person.region,

                individual_id=(
                    person.individual_id
                ),

                person_id=(
                    person.person_id
                ),

                location=location,

                score=score,

                income_score=(
                    income_n[index]
                ),

                property_score=(
                    property_n[index]
                ),

                construction_score=(
                    construction_n[index]
                ),

                proximity_score=(
                    proximity_n[index]
                ),

                income=(
                    person.income
                ),

                dwelling_value=(
                    0.0
                    if price is None
                    else price.midpoint
                ),

                building_cost=(
                    person.building_cost
                ),

                price_minimum=(
                    0.0
                    if price is None
                    else price.minimum
                ),

                price_maximum=(
                    0.0
                    if price is None
                    else price.maximum
                ),

                distance_from_source=(
                    distances[index]
                ),
            )
        )

    predictions.sort(
        key=lambda p: p.score,
        reverse=True,
    )

    ranked = []

    for rank, prediction in enumerate(
        predictions[:top_k],
        start=1,
    ):

        ranked.append(
            Prediction(
                rank=rank,
                region=prediction.region,
                individual_id=(
                    prediction.individual_id
                ),
                person_id=(
                    prediction.person_id
                ),
                location=(
                    prediction.location
                ),
                score=prediction.score,
                income_score=(
                    prediction.income_score
                ),
                property_score=(
                    prediction.property_score
                ),
                construction_score=(
                    prediction.construction_score
                ),
                proximity_score=(
                    prediction.proximity_score
                ),
                income=prediction.income,
                dwelling_value=(
                    prediction.dwelling_value
                ),
                building_cost=(
                    prediction.building_cost
                ),
                price_minimum=(
                    prediction.price_minimum
                ),
                price_maximum=(
                    prediction.price_maximum
                ),
                distance_from_source=(
                    prediction.distance_from_source
                ),
            )
        )

    return ranked


