Force fresh ABS downloads:
    python golden_abs_only_regional_solver.py --force

Skip downloading and use cached XLSX:
    python golden_abs_only_regional_solver.py --cached

Print workbook inspection:
    python golden_abs_only_regional_solver.py --inspect
"""

from __future__ import annotations

import argparse
import json
import math
import re
import sys
import time
from pathlib import Path
from urllib.parse import urljoin, urlparse

import pandas as pd
import requests


# ============================================================
# CONFIGURATION
# ============================================================

OUTPUT_DIR = Path("abs_only_solver_output")
