# ============================================================
# TEXT / NUMBER HELPERS
# ============================================================

def clean_text(value) -> str:

    if value is None:
        return ""

    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass

    text = str(value)

    text = (
        text
        .replace("\n", " ")
        .replace("\r", " ")
        .replace("\t", " ")
    )

    text = re.sub(
        r"\s+",
        " ",
        text,
    )

    return text.strip()


def number(value):

    if value is None:
        return None

    if isinstance(value, bool):
        return None

    if isinstance(value, (int, float)):

        try:
            if math.isnan(float(value)):
                return None
        except Exception:
            pass

        return float(value)

    text = clean_text(value)

    if not text:
        return None

    if text.lower() in {
        "-",
        "—",
        "–",
        "..",
        "...",
        "n.p.",
        "np",
        "n/a",
        "na",
    }:
        return None

    negative = (
        text.startswith("(")
        and text.endswith(")")
    )

    text = text.replace(",", "")
    text = text.replace("$", "")
    text = text.replace("%", "")

    match = re.search(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)",
        text,
    )

    if not match:
        return None

    value = float(
        match.group(0)
    )

    if negative:
        value = -value

    return value


def safe_filename(name: str) -> str:

    name = re.sub(
        r'[<>:"/\\|?*]+',
        "_",
        name,
    )

    name = re.sub(
        r"\s+",
        "_",
        name,
    )

    return name[:180]


def finite(value) -> bool:

    if value is None:
        return False

    try:
        return math.isfinite(
            float(value)
        )
    except Exception:
        return False


# ============================================================
# JSON
# ============================================================

def json_clean(value):

    if isinstance(value, float):

        if not math.isfinite(value):
            return None

        return value

    if isinstance(value, dict):

        return {
            str(k): json_clean(v)
            for k, v in value.items()
        }

    if isinstance(value, list):

        return [
            json_clean(v)
            for v in value
        ]

    return value


def save_json(
    filename: str,
    data,
):

    path = OUTPUT_DIR / filename

    with path.open(
        "w",
        encoding="utf-8",
    ) as f:

        json.dump(
            json_clean(data),
            f,
            indent=2,
            ensure_ascii=False,
        )

    print(
        f"Saved: {path}"
    )


# ============================================================
# ABS DOWNLOAD
# ============================================================

class ABSDownloader:

    def __init__(
        self,
        force=False,
    ):

        self.force = force

        self.session = (
            requests.Session()
        )

        self.session.headers.update(
            HEADERS
        )

    # --------------------------------------------------------
    # Discover official XLSX links
    # --------------------------------------------------------

    def discover_xlsx(
        self,
        release_url,
    ):

        print(
            f"\nABS release:"
        )

        print(
            release_url
        )

        response = (
            self.session.get(
                release_url,
                timeout=60,
            )
        )

        response.raise_for_status()

        html = response.text

        candidates = []

        patterns = [

            r'href=["\']([^"\']+\.xlsx'
            r'(?:\?[^"\']*)?)["\']',

            r'(https?://[^"\'>\s]+\.xlsx'
            r'(?:\?[^"\'>\s]*)?)',

            r'((?:/|https?://)[^"\'>\s]+\.xlsx)',
        ]

        for pattern in patterns:

            candidates.extend(
                re.findall(
                    pattern,
                    html,
                    flags=re.IGNORECASE,
                )
            )

        links = []

        for raw in candidates:

            raw = raw.replace(
                "&amp;",
                "&",
            )

            url = urljoin(
                release_url,
                raw,
            )

            parsed = urlparse(
                url
            )

            if parsed.scheme not in {
                "http",
                "https",
            }:
                continue

            if parsed.netloc.lower() != (
                "www.abs.gov.au"
            ):
                continue

            if ".xlsx" not in (
                parsed.path.lower()
            ):
                continue

            if url not in links:
                links.append(url)

        return links

    # --------------------------------------------------------
    # Download
    # --------------------------------------------------------

    def download(
        self,
        url,
    ):

        filename = (
            urlparse(url)
            .path
            .split("/")[-1]
        )

        filename = safe_filename(
            filename
        )

        if not filename.lower().endswith(
            ".xlsx"
        ):
            filename += ".xlsx"

        destination = (
            DOWNLOAD_DIR / filename
        )

        if (
            destination.exists()
            and destination.stat().st_size > 0
            and not self.force
        ):

            print(
                f"  cached: {filename}"
            )

            return destination

        print(
            f"  downloading: {filename}"
        )

        response = (
            self.session.get(
                url,
                timeout=180,
                stream=True,
            )
        )

        response.raise_for_status()

        temporary = (
            destination.with_suffix(
                ".part"
            )
        )

        with temporary.open(
            "wb"
        ) as f:

            for chunk in response.iter_content(
                chunk_size=1024 * 1024
            ):

                if chunk:
                    f.write(chunk)

        if (
            not temporary.exists()
            or temporary.stat().st_size == 0
        ):

            raise RuntimeError(
                "Downloaded ABS XLSX is empty: "
                + url
            )

        temporary.replace(
            destination
        )

        time.sleep(
            0.5
        )

        return destination

    # --------------------------------------------------------
    # Dataset
    # --------------------------------------------------------

    def download_dataset(
        self,
        dataset,
        url,
    ):

        print(
            "\n" + "=" * 70
        )

        print(
            f"ABS DATASET: {dataset.upper()}"
        )

        print(
            "=" * 70
        )

        links = self.discover_xlsx(
            url
        )

        if not links:

            raise RuntimeError(
                "No official ABS XLSX files "
                f"found at {url}"
            )

        print(
            f"Found {len(links)} XLSX file(s)."
        )

        files = []

        for link in links:

            try:

                path = self.download(
                    link
                )

                files.append(
                    path
                )

            except Exception as exc:

                print(
                    f"  download failed: "
                    f"{exc}"
                )

        return files

    # --------------------------------------------------------
    # All datasets
    # --------------------------------------------------------

    def download_all(self):

        result = {}

        for dataset, url in (
            ABS_RELEASES.items()
        ):

            try:

                result[dataset] = (
                    self.download_dataset(
                        dataset,
                        url,
                    )
                )

            except Exception as exc:

                print(
                    f"\nABS {dataset} failed:"
                )

                print(
                    f"  {exc}"
                )

                result[dataset] = []

        return result


# ============================================================
# WORKBOOK HELPERS
# ============================================================

def workbook_sheets(
    path: Path,
):

    excel = pd.ExcelFile(
        path,
        engine="openpyxl",
    )

    return list(
        excel.sheet_names
    )


def read_sheet(
    path: Path,
    sheet,
):

    return pd.read_excel(
        path,
        sheet_name=sheet,
        header=None,
        engine="openpyxl",
    )


def state_aliases(
    code,
):

    name = STATES[code]

    aliases = [
        name,
        code,
    ]

    if code == "ACT":
        aliases += [
            "Australian Capital Territory",
            "A.C.T.",
        ]

    if code == "NT":
        aliases += [
            "Northern Territory",
            "N.T.",
        ]

    return [
        x.lower()
        for x in aliases
    ]


def find_state_rows(
    df,
    code,
):

    aliases = state_aliases(
        code
    )

    matches = []

    for row_index in range(
        len(df)
    ):

        row_text = " ".join(
            clean_text(x).lower()
            for x in df.iloc[
                row_index
            ].tolist()
        )

        for alias in aliases:

            if not alias:
                continue

            if re.search(
                rf"(?<![a-z])"
                rf"{re.escape(alias)}"
                rf"(?![a-z])",
                row_text,
            ):

                matches.append(
                    row_index
                )

                break

    return matches


def make_headers(
    df,
    rows=15,
):

    labels = {}

    rows = min(
        rows,
        len(df),
    )

    for col in range(
        len(df.columns)
    ):

        pieces = []

        for row in range(
            rows
        ):

            text = clean_text(
                df.iloc[
                    row,
                    col,
                ]
            )

            if text:
                pieces.append(
                    text
                )

        pieces = list(
            dict.fromkeys(
                pieces
            )
        )

        labels[col] = (
            " | ".join(
                pieces
            )
        )

    return labels


def header_score(
    header,
    required,
    optional=None,
    forbidden=None,
):

    text = header.lower()

    if forbidden:

        for word in forbidden:

            if word.lower() in text:
                return -999999

    for word in required:

        if word.lower() not in text:
            return -999999

    score = (
        100 * len(required)
    )

    if optional:

        for word in optional:

            if word.lower() in text:
                score += 10

    return score


def find_series(
    workbook: Path,
    state,
    required,
    optional=None,
    forbidden=None,
    preferred_sheets=None,
):

    best = None
    best_score = -999999

    sheets = workbook_sheets(
        workbook
    )

    if preferred_sheets:

        sheets = sorted(
            sheets,
            key=lambda sheet: -sum(
                keyword.lower()
                in sheet.lower()
                for keyword
                in preferred_sheets
            ),
        )

    for sheet in sheets:

        try:

            df = read_sheet(
                workbook,
                sheet,
            )

        except Exception:
            continue

        state_rows = find_state_rows(
            df,
            state,
        )

        if not state_rows:
            continue

        headers = make_headers(
            df
        )

        for col, header in (
            headers.items()
        ):

            score = header_score(
                header,
                required,
                optional,
                forbidden,
            )

            if score <= best_score:
                continue

            for row in state_rows:

                if col >= len(
                    df.columns
                ):
                    continue

                value = number(
                    df.iloc[
                        row,
                        col,
                    ]
                )

                if value is None:
                    continue

                best_score = score

                best = {
                    "value": value,
                    "workbook":
                        workbook.name,
                    "sheet": sheet,
                    "row": int(row),
                    "column": int(col),
                    "header": header,
                    "score": score,
                }

                break

    return best


# ============================================================
# DWELLINGS
# ============================================================

def parse_dwellings(
    files,
):

    result = {
        code: {
            "total_dwelling_value": None,
            "mean_dwelling_price": None,
            "dwelling_count": None,
            "sources": {},
        }
        for code in STATES
    }

    if not files:
        return result

    candidates = [
        path
        for path in files
        if any(
            word in path.name.lower()
            for word in [
                "dwelling",
                "residential",
                "table",
            ]
        )
    ]

    if not candidates:
        candidates = files

    # Search all candidate workbooks rather than
    # assuming the first XLSX is correct.
    for code in STATES:

        for workbook in candidates:

            if result[code][
                "mean_dwelling_price"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "mean",
                        "price",
                    ],
                    optional=[
                        "dwelling",
                        "residential",
                    ],
                    forbidden=[
                        "median",
                    ],
                    preferred_sheets=[
                        "mean",
                        "price",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "mean_dwelling_price"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "mean_dwelling_price"
                    ] = match

            if result[code][
                "total_dwelling_value"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "total",
                        "value",
                    ],
                    optional=[
                        "dwelling",
                        "residential",
                    ],
                    preferred_sheets=[
                        "value",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "total_dwelling_value"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "total_dwelling_value"
                    ] = match

            if result[code][
                "dwelling_count"
            ] is None:

                match = find_series(
                    workbook,
                    code,
                    required=[
                        "number",
                        "dwellings",
                    ],
                    optional=[
                        "residential",
                    ],
                    preferred_sheets=[
                        "number",
                        "dwelling",
                        "state",
                    ],
                )

                if match:

                    result[code][
                        "dwelling_count"
                    ] = match["value"]

                    result[code][
                        "sources"
                    ][
                        "dwelling_count"
                    ] = match

    return result


# ============================================================
# AVERAGE WEEKLY EARNINGS
# ============================================================

def parse_earnings(
    files,
):

    result = {
        code: {
            "weekly_earnings": None,
            "sources": {},
        }
        for code in STATES
    }

    if not files:
        return result

    # The May 2026 release provides separate
    # state/territory tables. We search the files
    # explicitly for the desired AWE series.
    for code in STATES:

        for workbook in files:

            if result[code][
                "weekly_earnings"
            ] is not None:
                break

            match = find_series(
                workbook,
                code,
                required=[
                    "average",
                    "weekly",
                    "earnings",
                ],
                optional=[
                    "full-time",
                    "adult",
                    "ordinary",
                    "time",
                    "persons",
                ],
                forbidden=[
                    "cash",
                    "industry",
                ],
                preferred_sheets=[
                    "state",
                    "earnings",
                    "table 13",
                    "table 11",
                ],
            )

            if match:

                result[code][
                    "weekly_earnings"
                ] = match["value"]

                result[code][
                    "sources"
                ][
                    "weekly_earnings"
                ] = match

    return result


# ============================================================
# PPI
# ============================================================

def parse_ppi(
    files,
):

    result = {
        code: {
            "construction_price_index":
                None,
            "construction_quarterly_change":
                None,
            "construction_annual_change":
                None,
            "sources": {},
        }
        for code in STATES
    }

    if not files:
        return result

    # The June 2026 PPI release explicitly reports
    # House construction price changes by state.
    #
    # We use the actual state table rather than
    # selecting the largest numeric value in a row.

    for code in STATES:

        for workbook in files:

            if result[code][
                "construction_annual_change"
            ] is not None:
                break

            try:

                sheets = workbook_sheets(
                    workbook
                )

            except Exception:
                continue

            for sheet in sheets:

                try:

                    df = read_sheet(
                        workbook,
                        sheet,
                    )

                except Exception:
                    continue

                state_rows = find_state_rows(
                    df,
                    code,
                )

                if not state_rows:
                    continue

                headers = make_headers(
                    df,
                    rows=12,
                )

                quarterly_columns = []
                annual_columns = []

                for col, header in (
                    headers.items()
                ):

                    text = header.lower()

                    if (
                        "quarter"
                        in text
                        and "change"
                        in text
                    ):
                        quarterly_columns.append(
                            col
                        )

                    if (
                        "annual"
                        in text
                        and "change"
                        in text
                    ):
                        annual_columns.append(
                            col
                        )

                # Prefer a sheet that actually mentions
                # house construction.
                sheet_text = (
                    " ".join(
                        headers.values()
                    )
                    .lower()
                )

                if (
                    "house construction"
                    not in sheet_text
                    and "construction prices"
                    not in sheet_text
                ):
                    continue

                row = state_rows[0]

                quarterly = None
                annual = None

                if quarterly_columns:

                    for col in quarterly_columns:

                        value = number(
                            df.iloc[
                                row,
                                col,
                            ]
                        )

                        if value is not None:
                            quarterly = value
                            break

                if annual_columns:

                    for col in annual_columns:

                        value = number(
                            df.iloc[
                                row,
                                col,
                            ]
                        )

                        if value is not None:
                            annual = value
                            break

                if (
                    quarterly is None
                    and annual is None
                ):
                    continue

                result[code][
                    "construction_quarterly_change"
                ] = quarterly

                result[code][
                    "construction_annual_change"
                ] = annual

                # For the regional score we use the
                # annual construction-price change.
                result[code][
                    "construction_price_index"
                ] = annual

                result[code][
                    "sources"
                ][
                    "construction_price_index"
                ] = {
                    "workbook":
                        workbook.name,
                    "sheet":
                        sheet,
                    "row":
                        int(row),
                    "quarterly":
                        quarterly,
                    "annual":
                        annual,
                }

                break

    return result


