# ============================================================
# GOLDEN RATIO
# ============================================================

def golden_weights(
    n=16,
):

    weights = []

    for k in range(n):

        distance = min(
            k,
            n - k,
        )

        weights.append(
            PHI ** (-distance)
        )

    total = sum(
        weights
    )

    return [
        value / total
        for value in weights
    ]


def economic_sector_vector(
    values,
    sectors=16,
):

    """
    Convert an ordered economic feature vector
    into a normalized sector vector.

    There are 8 Australian states/territories.
    To retain the 16-sector golden baseline,
    each regional value is mapped into two
    mirrored sectors.

    The transformation is deterministic:

        state i
        -> sector i
        -> sector (15-i)

    The values are normalized first.
    """

    finite = [
        float(v)
        for v in values
        if finite(v)
    ]

    if not finite:
        return [
            1.0 / sectors
            for _ in range(sectors)
        ]

    low = min(finite)
    high = max(finite)

    if high == low:

        normalized = [
            0.5
            for _ in values
        ]

    else:

        normalized = []

        for value in values:

            if not finite(value):

                normalized.append(
                    0.5
                )

            else:

                normalized.append(
                    (
                        float(value)
                        - low
                    )
                    / (
                        high
                        - low
                    )
                )

    vector = [
        0.0
        for _ in range(sectors)
    ]

    for i, value in enumerate(
        normalized
    ):

        a = i % sectors
        b = (
            sectors
            - 1
            - i
        ) % sectors

        vector[a] += value
        vector[b] += value

    total = sum(
        vector
    )

    if total <= 0:

        return [
            1.0 / sectors
            for _ in range(sectors)
        ]

    return [
        value / total
        for value in vector
    ]


def similarity(
    observed,
    target,
):

    if len(observed) != len(target):
        return 0.0

    return sum(
        math.sqrt(
            max(a, 0.0)
            * max(b, 0.0)
        )
        for a, b in zip(
            observed,
            target,
        )
    )


# ============================================================
# NORMALIZATION
# ============================================================

def minmax(
    rows,
    field,
):

    values = [
        float(row[field])
        for row in rows
        if finite(
            row.get(field)
        )
    ]

    if not values:

        return {
            row["state"]: 0.5
            for row in rows
        }

    low = min(values)
    high = max(values)

    if high == low:

        return {
            row["state"]: 0.5
            for row in rows
        }

    output = {}

    for row in rows:

        value = row.get(
            field
        )

        if not finite(value):

            output[
                row["state"]
            ] = 0.5

        else:

            output[
                row["state"]
            ] = (
                float(value)
                - low
            ) / (
                high
                - low
            )

    return output


# ============================================================
# REGIONAL SCORE
# ============================================================

def calculate_scores(
    abs_data,
):

    rows = []

    for code, name in STATES.items():

        data = abs_data.get(
            code,
            {},
        )

        rows.append({

            "state": code,

            "name": name,

            "total_dwelling_value":
                data.get(
                    "total_dwelling_value"
                ),

            "mean_dwelling_price":
                data.get(
                    "mean_dwelling_price"
                ),

            "dwelling_count":
                data.get(
                    "dwelling_count"
                ),

            "weekly_earnings":
                data.get(
                    "weekly_earnings"
                ),

            "construction_price_index":
                data.get(
                    "construction_price_index"
                ),

            "construction_quarterly_change":
                data.get(
                    "construction_quarterly_change"
                ),

            "construction_annual_change":
                data.get(
                    "construction_annual_change"
                ),

            "building_work_value":
                data.get(
                    "building_work_value"
                ),
        })

    fields = [
        "total_dwelling_value",
        "mean_dwelling_price",
        "dwelling_count",
        "weekly_earnings",
        "construction_price_index",
        "building_work_value",
    ]

    normalized = {
        field: minmax(
            rows,
            field,
        )
        for field in fields
    }

    # --------------------------------------------------------
    # Golden economic vector
    # --------------------------------------------------------

    economic_features = [
        (
            row.get(
                "mean_dwelling_price"
            )
            if finite(
                row.get(
                    "mean_dwelling_price"
                )
            )
            else row.get(
                "weekly_earnings"
            )
        )
        for row in rows
    ]

    golden = golden_weights(
        16
    )

    for index, row in enumerate(
        rows
    ):

        # Build a state-specific economic
        # feature vector from all available
        # normalized ABS fields.
        feature_values = [
            normalized[field][
                row["state"]
            ]
            for field in fields
        ]

        # Pad to eight state-derived
        # positions using the six economic
        # variables plus two aggregate values.
        mean_feature = (
            sum(feature_values)
            / len(feature_values)
            if feature_values
            else 0.5
        )

        weighted_feature = (
            0.0
        )

        for j, value in enumerate(
            feature_values
        ):

            weighted_feature += (
                value
                * (
                    PHI ** (
                        -j
                    )
                )
            )

        weighted_feature /= sum(
            PHI ** (-j)
            for j in range(
                len(feature_values)
            )
        )

        state_vector_seed = (
            feature_values
            + [
                mean_feature,
                weighted_feature,
            ]
        )

        vector = economic_sector_vector(
            state_vector_seed,
            16,
        )

        golden_score = similarity(
            vector,
            golden,
        )

        row[
            "golden_alignment"
        ] = golden_score

        row[
            "economic_sector_vector"
        ] = vector

    # --------------------------------------------------------
    # Regional prediction score
    # --------------------------------------------------------

    weights = {

        "mean_dwelling_price":
            0.25,

        "weekly_earnings":
            0.20,

        "building_work_value":
            0.15,

        "total_dwelling_value":
            0.10,

        "dwelling_count":
            0.10,

        "construction_price_index":
            0.10,

        "golden_alignment":
            0.10,
    }

    for row in rows:

        score = 0.0

        for field, weight in (
            weights.items()
        ):

            if field == (
                "golden_alignment"
            ):

                value = row.get(
                    field,
                    0.5,
                )

            else:

                value = normalized[
                    field
                ][
                    row["state"]
                ]

            score += (
                weight
                * value
            )

        row[
            "regional_score"
        ] = score

        row[
            "normalized_features"
        ] = {
            field:
                (
                    row.get(field)
                    if field ==
                    "golden_alignment"
                    else normalized[
                        field
                    ][
                        row["state"]
                    ]
                )
            for field in weights
        }

    rows.sort(
        key=lambda row:
            row["regional_score"],
        reverse=True,
    )

    return rows


