def clean_text(value: Any) -> str:

    if value is None:
        return ""

    return re.sub(
        r"\s+",
        " ",
        str(value)
    ).strip()


def numeric(value: Any) -> Optional[float]:

    if value is None:
        return None

    if isinstance(
        value,
        (int, float, np.integer, np.floating),
    ):

        if np.isfinite(float(value)):
            return float(value)

        return None

    text = clean_text(value)

    if not text:
        return None

    negative = (
        "(" in text
        and ")" in text
    )

    text = (
        text
        .replace(",", "")
        .replace("$", "")
        .replace("%", "")
        .replace("AUD", "")
        .replace("A$", "")
        .replace("million", "")
        .replace("billion", "")
    )

    match = re.search(
        r"-?\d+(?:\.\d+)?",
        text
    )

    if not match:
        return None

    value = float(
        match.group()
    )

    if negative:
        value = -abs(value)

    return value


def normalise_state_name(
    value: Any,
) -> Optional[str]:

    text = clean_text(value).lower()

    aliases = {
        "new south wales": "NSW",
        "nsw": "NSW",

        "victoria": "VIC",
        "vic": "VIC",

        "queensland": "QLD",
        "qld": "QLD",

        "south australia": "SA",
        "sa": "SA",

        "western australia": "WA",
        "wa": "WA",

        "tasmania": "TAS",
        "tas": "TAS",

        "northern territory": "NT",
        "nt": "NT",

        "australian capital territory": "ACT",
        "act": "ACT",
    }

    return aliases.get(text)


def flatten_columns(
    df: pd.DataFrame,
) -> pd.DataFrame:

    df = df.copy()

    if isinstance(
        df.columns,
        pd.MultiIndex,
    ):

        df.columns = [
            " ".join(
                clean_text(x)
                for x in column
                if clean_text(x)
            )
            for column in df.columns
        ]

    else:

        df.columns = [
            clean_text(x)
            for x in df.columns
        ]

    return df


def read_html_tables(
    url: str,
) -> list[pd.DataFrame]:

    print()
    print(
        "Downloading ABS page:"
    )

    print(
        url
    )

    response = SESSION.get(
        url,
        timeout=60,
    )

    response.raise_for_status()

    html = response.text

    try:

        tables = pd.read_html(
            html
        )

    except ValueError:

        tables = []

    return [
        flatten_columns(df)
        for df in tables
        if not df.empty
    ]


def state_column(
    df: pd.DataFrame,
) -> Optional[str]:

    for column in df.columns:

        text = clean_text(
            column
        ).lower()

        if (
            "state" in text
            or "territory" in text
            or "region" in text
        ):

            return column

    # Try first column if it contains state names.
    if len(df.columns) > 0:

        first = df.columns[0]

        matches = 0

        for value in df[first]:

            if normalise_state_name(
                value
            ):

                matches += 1

        if matches >= 2:
            return first

    return None


def find_state_rows(
    df: pd.DataFrame,
) -> dict[str, pd.Series]:

    column = state_column(
        df
    )

    if column is None:
        return {}

    result = {}

    for _, row in df.iterrows():

        state = normalise_state_name(
            row[column]
        )

        if state:
            result[state] = row

    return result


def column_score(
    column: str,
    include: list[str],
    exclude: list[str] | None = None,
) -> int:

    text = clean_text(
        column
    ).lower()

    score = 0

    for word in include:

        if word in text:
            score += 1

    if exclude:

        for word in exclude:

            if word in text:
                score -= 3

    return score


def choose_column(
    df: pd.DataFrame,
    include: list[str],
    exclude: list[str] | None = None,
) -> Optional[str]:

    if df.empty:
        return None

    scores = []

    for column in df.columns:

        scores.append(
            (
                column_score(
                    column,
                    include,
                    exclude,
                ),
                column,
            )
        )

    scores.sort(
        reverse=True
    )

    if not scores:
        return None

    if scores[0][0] <= 0:
        return None

    return scores[0][1]


# ============================================================
# ABS DWELLINGS
# ============================================================

def parse_dwellings(
    tables: list[pd.DataFrame],
) -> dict[str, dict[str, float]]:

    result = {}

    for df in tables:

        rows = find_state_rows(
            df
        )

        if len(rows) < 3:
            continue

        mean_col = choose_column(
            df,
            [
                "mean",
                "dwelling",
                "price",
            ],
            [
                "change",
                "growth",
                "quarter",
                "annual",
            ],
        )

        median_col = choose_column(
            df,
            [
                "median",
                "dwelling",
                "price",
            ],
            [
                "change",
                "growth",
            ],
        )

        count_col = choose_column(
            df,
            [
                "number",
                "dwellings",
            ],
        )

        value_col = choose_column(
            df,
            [
                "total",
                "value",
            ],
        )

        for state, row in rows.items():

            item = result.setdefault(
                state,
                {}
            )

            if mean_col:

                value = numeric(
                    row.get(
                        mean_col
                    )
                )

                if (
                    value is not None
                    and 100_000
                    <= value
                    <= 5_000_000
                ):

                    item[
                        "mean_dwelling_price"
                    ] = value

            if median_col:

                value = numeric(
                    row.get(
                        median_col
                    )
                )

                if (
                    value is not None
                    and 100_000
                    <= value
                    <= 5_000_000
                ):

                    item[
                        "median_dwelling_price"
                    ] = value

            if count_col:

                value = numeric(
                    row.get(
                        count_col
                    )
                )

                if (
                    value is not None
                    and value > 1000
                ):

                    item[
                        "dwelling_count"
                    ] = value

            if value_col:

                value = numeric(
                    row.get(
                        value_col
                    )
                )

                if (
                    value is not None
                    and value > 1e8
                ):

                    item[
                        "dwelling_total_value"
                    ] = value

    return result


# ============================================================
# ABS EARNINGS
# ============================================================

def parse_earnings(
    tables: list[pd.DataFrame],
) -> dict[str, float]:

    result = {}

    for df in tables:

        rows = find_state_rows(
            df
        )

        if len(rows) < 3:
            continue

        candidate_columns = []

        for column in df.columns:

            text = clean_text(
                column
            ).lower()

            score = 0

            if (
                "ordinary" in text
                or "time" in text
            ):
                score += 2

            if "full" in text:
                score += 2

            if "adult" in text:
                score += 2

            if (
                "weekly" in text
                or "earnings" in text
            ):
                score += 2

            if "change" in text:
                score -= 4

            if "percentage" in text:
                score -= 4

            if score > 0:
                candidate_columns.append(
                    (
                        score,
                        column,
                    )
                )

        candidate_columns.sort(
            reverse=True
        )

        for _, column in candidate_columns:

            values = {}

            for state, row in rows.items():

                value = numeric(
                    row.get(
                        column
                    )
                )

                if (
                    value is not None
                    and 500
                    <= value
                    <= 5000
                ):

                    values[state] = value

            if len(values) >= 3:

                for state, value in values.items():

                    result[state] = value

                return result

    return result


# ============================================================
# ABS PPI
# ============================================================

def parse_ppi(
    tables: list[pd.DataFrame],
) -> dict[str, dict[str, float]]:

    result = {}

    for df in tables:

        rows = find_state_rows(
            df
        )

        if len(rows) < 3:
            continue

        construction_columns = []

        for column in df.columns:

            text = clean_text(
                column
            ).lower()

            if (
                "construction" in text
                or "building" in text
                or "house" in text
            ):

                construction_columns.append(
                    column
                )

        if not construction_columns:
            continue

        for state, row in rows.items():

            for column in construction_columns:

                value = numeric(
                    row.get(
                        column
                    )
                )

                if value is None:
                    continue

                text = clean_text(
                    column
                ).lower()

                item = result.setdefault(
                    state,
                    {}
                )

                if (
                    "quarter" in text
                    or "qtr" in text
                ):

                    item[
                        "construction_quarter_change"
                    ] = value

                elif (
                    "annual" in text
                    or "year" in text
                ):

                    item[
                        "construction_annual_change"
                    ] = value

    return result


# ============================================================
# ABS BUILDING ACTIVITY
# ============================================================

def parse_building(
    tables: list[pd.DataFrame],
) -> dict[str, float]:

    result = {}

    for df in tables:

        rows = find_state_rows(
            df
        )

        if len(rows) < 3:
            continue

        candidate_columns = []

        for column in df.columns:

            text = clean_text(
                column
            ).lower()

            score = 0

            if "value" in text:
                score += 3

            if "building" in text:
                score += 2

            if "work" in text:
                score += 2

            if "construction" in text:
                score += 2

            if "number" in text:
                score -= 3

            if "dwellings" in text:
                score -= 1

            if score > 0:
                candidate_columns.append(
                    (
                        score,
                        column,
                    )
                )

        candidate_columns.sort(
            reverse=True
        )

        for _, column in candidate_columns:

            values = {}

            for state, row in rows.items():

                value = numeric(
                    row.get(
                        column
                    )
                )

                if (
                    value is not None
                    and value > 1e6
                ):

                    values[state] = value

            if len(values) >= 3:

                for state, value in values.items():

                    result[state] = value

                return result

    return result


