# ============================================================
# OVERPASS QUERY
# ============================================================

def build_overpass_query(
    latitude: float,
    longitude: float,
    radius_km: float,
) -> str:

    radius_m = int(
        radius_km * 1000
    )

    highway_regex = "|".join(
        ROAD_TYPES
    )

    return f"""
[out:json][timeout:180];

way
  ["highway"~"^({highway_regex})$"]
  (around:{radius_m},{latitude},{longitude});

out geom;
"""


# ============================================================
# ROAD CACHE
# ============================================================

def road_cache_path(
    state: str,
) -> Path:

    return (
        ROAD_DIR
        / f"{state.lower()}_roads.json"
    )


def cache_is_valid(
    path: Path,
) -> bool:

    if not path.exists():
        return False

    age = (
        time.time()
        - path.stat().st_mtime
    )

    return (
        age
        <= ROAD_CACHE_MAX_AGE
    )


# ============================================================
# OVERPASS DOWNLOAD
# ============================================================

def download_roads(
    state: str,
    force: bool = False,
) -> Optional[dict]:

    cache = road_cache_path(
        state
    )

    # --------------------------------------------------------
    # Existing cache.
    # --------------------------------------------------------

    if (
        cache_is_valid(cache)
        and not force
    ):

        print()
        print(
            f"Using cached roads for {state}"
        )

        try:

            with cache.open(
                "r",
                encoding="utf-8",
            ) as f:

                data = json.load(f)

            if (
                isinstance(data, dict)
                and isinstance(
                    data.get("elements"),
                    list,
                )
                and len(
                    data["elements"]
                ) > 0
            ):

                print(
                    "Cached road elements:",
                    len(
                        data["elements"]
                    ),
                )

                return data

        except Exception as exc:

            print(
                "Cache read failed:",
                repr(exc)
            )

    latitude, longitude = (
        STATE_CAPITALS[state]
    )

    query = build_overpass_query(
        latitude,
        longitude,
        ROAD_RADIUS_KM,
    )

    last_error = None

    # --------------------------------------------------------
    # Multiple Overpass endpoints.
    # --------------------------------------------------------

    for endpoint_index, endpoint in enumerate(
        OVERPASS_ENDPOINTS,
        start=1,
    ):

        print()
        print(
            f"Downloading roads for {state}"
        )

        print(
            f"Overpass endpoint "
            f"{endpoint_index}/"
            f"{len(OVERPASS_ENDPOINTS)}:"
        )

        print(
            endpoint
        )

        # ----------------------------------------------------
        # Endpoint retry loop.
        # ----------------------------------------------------

        for attempt in range(
            1,
            4,
        ):

            try:

                response = SESSION.post(
                    endpoint,
                    data={
                        "data": query
                    },
                    timeout=210,
                    allow_redirects=True,
                )

                status = (
                    response.status_code
                )

                print(
                    f"  attempt {attempt}: "
                    f"HTTP {status}"
                )

                # ------------------------------------------------
                # Temporary/recoverable errors.
                # ------------------------------------------------

                if status in {
                    406,
                    429,
                    500,
                    502,
                    503,
                    504,
                }:

                    retry_after = (
                        response.headers.get(
                            "Retry-After"
                        )
                    )

                    if retry_after:

                        try:

                            delay = float(
                                retry_after
                            )

                        except ValueError:

                            delay = (
                                15.0
                            )

                    else:

                        delay = (
                            15.0
                            * (
                                2
                                ** (
                                    attempt
                                    - 1
                                )
                            )
                        )

                    print(
                        f"  server returned "
                        f"{status}; waiting "
                        f"{delay:.1f}s"
                    )

                    last_error = RuntimeError(
                        f"HTTP {status}"
                    )

                    time.sleep(
                        delay
                    )

                    continue

                response.raise_for_status()

                # ------------------------------------------------
                # Decode JSON.
                # ------------------------------------------------

                data = response.json()

                if not isinstance(
                    data,
                    dict,
                ):

                    raise RuntimeError(
                        "Overpass returned "
                        "non-object JSON"
                    )

                elements = data.get(
                    "elements"
                )

                if not isinstance(
                    elements,
                    list,
                ):

                    raise RuntimeError(
                        "Overpass response "
                        "has no elements[]"
                    )

                if not elements:

                    raise RuntimeError(
                        "Overpass returned "
                        "zero road elements"
                    )

                # ------------------------------------------------
                # Save.
                # ------------------------------------------------

                with cache.open(
                    "w",
                    encoding="utf-8",
                ) as f:

                    json.dump(
                        data,
                        f,
                    )

                print(
                    "  SUCCESS"
                )

                print(
                    "  road elements:",
                    len(elements),
                )

                return data

            except Exception as exc:

                last_error = exc

                print(
                    "  request failed:",
                    repr(exc)
                )

                if attempt < 3:

                    delay = (
                        10.0
                        * attempt
                    )

                    print(
                        f"  retrying in "
                        f"{delay:.1f}s"
                    )

                    time.sleep(
                        delay
                    )

        print(
            "  endpoint exhausted; "
            "trying next endpoint."
        )

        time.sleep(
            5
        )

    # --------------------------------------------------------
    # All endpoints failed.
    #
    # IMPORTANT:
    # Do not fabricate geometry.
    # --------------------------------------------------------

    diagnostic = (
        ROAD_DIR
        / f"{state.lower()}_road_error.txt"
    )

    diagnostic.write_text(
        (
            "ROAD DOWNLOAD FAILED\n\n"
            f"State: {state}\n"
            f"Latitude: {latitude}\n"
            f"Longitude: {longitude}\n"
            f"Radius km: {ROAD_RADIUS_KM}\n\n"
            f"Last error:\n"
            f"{repr(last_error)}\n\n"
            "Endpoints attempted:\n"
            + "\n".join(
                OVERPASS_ENDPOINTS
            )
            + "\n"
        ),
        encoding="utf-8",
    )

    print()
    print(
        f"ROAD DATA FAILED FOR {state}:"
    )

    print(
        repr(last_error)
    )

    print(
        "No synthetic road data was created."
    )

    return None


# ============================================================
# ROAD SEGMENT EXTRACTION
# ============================================================

def extract_road_segments(
    data: dict,
):

    lat1 = []
    lon1 = []

    lat2 = []
    lon2 = []

    for element in data.get(
        "elements",
        [],
    ):

        geometry = element.get(
            "geometry"
        )

        if not geometry:
            continue

        if len(geometry) < 2:
            continue

        for point_a, point_b in zip(
            geometry[:-1],
            geometry[1:],
        ):

            try:

                lat1.append(
                    float(
                        point_a["lat"]
                    )
                )

                lon1.append(
                    float(
                        point_a["lon"]
                    )
                )

                lat2.append(
                    float(
                        point_b["lat"]
                    )
                )

                lon2.append(
                    float(
                        point_b["lon"]
                    )
                )

            except (
                KeyError,
                TypeError,
                ValueError,
            ):

                continue

    return (
        np.asarray(
            lat1,
            dtype=np.float64,
        ),

        np.asarray(
            lon1,
            dtype=np.float64,
        ),

        np.asarray(
            lat2,
            dtype=np.float64,
        ),

        np.asarray(
            lon2,
            dtype=np.float64,
        ),
    )


# ============================================================
# VECTORISED ROAD GEOMETRY
# ============================================================

def calculate_road_geometry(
    state: str,
    data: dict,
) -> RoadGeometry:

    (
        lat1,
        lon1,
        lat2,
        lon2,
    ) = extract_road_segments(
        data
    )

    if len(lat1) == 0:

        raise RuntimeError(
            f"No usable road segments "
            f"for {state}"
        )

    # --------------------------------------------------------
    # Local equirectangular projection.
    #
    # At a 35 km radius this is an accurate and computationally
    # efficient local representation.
    # --------------------------------------------------------

    mean_lat = np.radians(
        (
            lat1
            + lat2
        )
        * 0.5
    )

    metres_per_degree_lat = (
        111_320.0
    )

    metres_per_degree_lon = (
        111_320.0
        * np.cos(
            mean_lat
        )
    )

    dx = (
        (
            lon2
            - lon1
        )
        * metres_per_degree_lon
    )

    dy = (
        (
            lat2
            - lat1
        )
        * metres_per_degree_lat
    )

    lengths = np.hypot(
        dx,
        dy,
    )

    valid = (
        np.isfinite(dx)
        &
        np.isfinite(dy)
        &
        np.isfinite(lengths)
        &
        (lengths > 0.1)
    )

    dx = dx[valid]
    dy = dy[valid]
    lengths = lengths[valid]

    if len(lengths) == 0:

        raise RuntimeError(
            f"No valid road vectors "
            f"for {state}"
        )

    # --------------------------------------------------------
    # Road orientation.
    #
    # Roads are axial rather than directional:
    #
    # 0 degrees = 180 degrees
    #
    # Therefore theta is folded into [0, pi).
    # --------------------------------------------------------

    theta = np.mod(
        np.arctan2(
            dy,
            dx,
        ),
        np.pi,
    )

    # --------------------------------------------------------
    # 16 geometric sectors.
    # --------------------------------------------------------

    sector_width = (
        np.pi
        / ROAD_SECTORS
    )

    sector_indices = np.floor(
        theta
        / sector_width
    ).astype(
        np.int32
    )

    sector_indices = np.clip(
        sector_indices,
        0,
        ROAD_SECTORS - 1,
    )

    # --------------------------------------------------------
    # Length-weighted sector vector:
    #
    # R_k = L_k / sum(L_j)
    # --------------------------------------------------------

    sector_lengths = np.bincount(
        sector_indices,
        weights=lengths,
        minlength=ROAD_SECTORS,
    )

    total_length = (
        sector_lengths.sum()
    )

    if total_length <= 0:

        raise RuntimeError(
            "Total road length is zero."
        )

    sector_ratios = (
        sector_lengths
        / total_length
    )

    # Numerical check.
    if not np.isclose(
        sector_ratios.sum(),
        1.0,
        atol=1e-10,
    ):

        sector_ratios = (
            sector_ratios
            / sector_ratios.sum()
        )

    # --------------------------------------------------------
    # Axial orientation vector.
    #
    # z =
    #   sum(L_i exp(2 i theta_i))
    #   --------------------------------
    #            sum(L_i)
    #
    # x = Re(z)
    # y = Im(z)
    #
    # A = |z|
    # --------------------------------------------------------

    cos_2theta = np.cos(
        2.0 * theta
    )

    sin_2theta = np.sin(
        2.0 * theta
    )

    vector_x = (
        np.sum(
            lengths
            * cos_2theta
        )
        / total_length
    )

    vector_y = (
        np.sum(
            lengths
            * sin_2theta
        )
        / total_length
    )

    anisotropy = float(
        np.hypot(
            vector_x,
            vector_y,
        )
    )

    # --------------------------------------------------------
    # Dominant orientation.
    # --------------------------------------------------------

    dominant_angle = (
        0.5
        * np.arctan2(
            vector_y,
            vector_x,
        )
    )

    dominant_angle = float(
        np.mod(
            dominant_angle,
            np.pi,
        )
    )

    dominant_sector = int(
        np.floor(
            dominant_angle
            / sector_width
        )
    )

    dominant_sector = min(
        dominant_sector,
        ROAD_SECTORS - 1,
    )

    # --------------------------------------------------------
    # Shannon directional entropy.
    # --------------------------------------------------------

    positive = (
        sector_ratios[
            sector_ratios > 0
        ]
    )

    entropy = float(
        -np.sum(
            positive
            * np.log(
                positive
            )
        )
    )

    maximum_entropy = math.log(
        ROAD_SECTORS
    )

    directional_entropy = (
        entropy
        / maximum_entropy
    )

    # --------------------------------------------------------
    # Directional groups.
    # --------------------------------------------------------

    sector_centres = (
        (
            np.arange(
                ROAD_SECTORS
            )
            + 0.5
        )
        * sector_width
    )

    east_west = (
        np.abs(
            np.sin(
                sector_centres
            )
        )
        < 0.25
    )

    north_south = (
        np.abs(
            np.cos(
                sector_centres
            )
        )
        < 0.25
    )

    diagonal = (
        ~east_west
        & ~north_south
    )

    east_west_ratio = float(
        sector_ratios[
            east_west
        ].sum()
    )

    north_south_ratio = float(
        sector_ratios[
            north_south
        ].sum()
    )

    diagonal_ratio = float(
        sector_ratios[
            diagonal
        ].sum()
    )

    # --------------------------------------------------------
    # Alignment of dominant road direction with the vector
    # from the approximate state centroid to its capital.
    # --------------------------------------------------------

    centroid_lat, centroid_lon = (
        STATE_CENTROIDS[state]
    )

    capital_lat, capital_lon = (
        STATE_CAPITALS[state]
    )

    capital_dx = (
        (
            capital_lon
            - centroid_lon
        )
        * 111_320.0
        * math.cos(
            math.radians(
                centroid_lat
            )
        )
    )

    capital_dy = (
        (
            capital_lat
            - centroid_lat
        )
        * 111_320.0
    )

    capital_angle = (
        math.atan2(
            capital_dy,
            capital_dx,
        )
        % math.pi
    )

    angle_difference = abs(
        dominant_angle
        - capital_angle
    )

    angle_difference = min(
        angle_difference,
        math.pi
        - angle_difference,
    )

    capital_alignment = (
        1.0
        + math.cos(
            angle_difference
        )
    ) / 2.0

    # --------------------------------------------------------
    # Road density.
    # --------------------------------------------------------

    total_length_km = (
        total_length
        / 1000.0
    )

    area_km2 = (
        math.pi
        * ROAD_RADIUS_KM
        * ROAD_RADIUS_KM
    )

    road_density = (
        total_length_km
        / area_km2
        * 100.0
    )

    return RoadGeometry(
        state=state,

        total_length_km=float(
            total_length_km
        ),

        sector_lengths_km=(
            sector_lengths
            / 1000.0
        ),

        sector_ratios=(
            sector_ratios
        ),

        anisotropy=float(
            anisotropy
        ),

        dominant_sector=int(
            dominant_sector
        ),

        dominant_angle_degrees=float(
            math.degrees(
                dominant_angle
            )
        ),

        road_density_km_per_100km2=float(
            road_density
        ),

        directional_entropy=float(
            directional_entropy
        ),

        east_west_ratio=float(
            east_west_ratio
        ),

        north_south_ratio=float(
            north_south_ratio
        ),

        diagonal_ratio=float(
            diagonal_ratio
        ),

        network_vector_x=float(
            vector_x
        ),

        network_vector_y=float(
            vector_y
        ),

        alignment_with_capital=float(
            capital_alignment
        ),

        road_count=int(
            len(lengths)
        ),

        element_count=int(
            len(
                data.get(
                    "elements",
                    [],
                )
            )
        ),
    )


