# ============================================================
# NORMALIZATION
# ============================================================

def normalize(
    values: list[Optional[float]]
    | np.ndarray,
) -> np.ndarray:

    x = np.asarray(
        [
            np.nan
            if value is None
            else float(value)
            for value in values
        ],
        dtype=np.float64,
    )

    valid = np.isfinite(x)

    if not np.any(valid):

        return np.zeros_like(x)

    low = np.nanmin(x)
    high = np.nanmax(x)

    if (
        not np.isfinite(low)
        or not np.isfinite(high)
    ):

        return np.zeros_like(x)

    if high == low:

        result = np.zeros_like(x)

        result[valid] = 1.0

        return result

    result = np.zeros_like(x)

    result[valid] = (
        x[valid] - low
    ) / (
        high - low
    )

    return result


def log_normalize(
    values: list[Optional[float]]
    | np.ndarray,
) -> np.ndarray:

    x = np.asarray(
        [
            np.nan
            if value is None
            else float(value)
            for value in values
        ],
        dtype=np.float64,
    )

    finite = np.isfinite(x)

    x[finite] = np.maximum(
        x[finite],
        0.0,
    )

    x[finite] = np.log1p(
        x[finite]
    )

    return normalize(
        x
    )


# ============================================================
# ROAD SCORES
# ============================================================

def calculate_road_scores(
    roads: dict[str, RoadGeometry],
) -> dict[str, float]:

    if not roads:
        return {}

    states = list(
        roads.keys()
    )

    density = np.array(
        [
            roads[state]
            .road_density_km_per_100km2
            for state in states
        ],
        dtype=np.float64,
    )

    anisotropy = np.array(
        [
            roads[state]
            .anisotropy
            for state in states
        ],
        dtype=np.float64,
    )

    alignment = np.array(
        [
            roads[state]
            .alignment_with_capital
            for state in states
        ],
        dtype=np.float64,
    )

    density_score = (
        log_normalize(
            density
        )
    )

    anisotropy_score = (
        normalize(
            anisotropy
        )
    )

    alignment_score = (
        normalize(
            alignment
        )
    )

    # Independent components:
    #
    # 45% road density
    # 35% directional concentration
    # 20% capital alignment
    #
    # No duplicate road-score weighting.

    score = (
        0.45
        * density_score
        +
        0.35
        * anisotropy_score
        +
        0.20
        * alignment_score
    )

    return {
        state: float(
            score[i]
        )
        for i, state in enumerate(
            states
        )
    }


# ============================================================
# ROAD VECTOR COSINE SIMILARITY
# ============================================================

def cosine_similarity(
    a: np.ndarray,
    b: np.ndarray,
) -> float:

    a = np.asarray(
        a,
        dtype=np.float64,
    )

    b = np.asarray(
        b,
        dtype=np.float64,
    )

    denominator = (
        np.linalg.norm(a)
        * np.linalg.norm(b)
    )

    if denominator <= 0:
        return 0.0

    return float(
        np.dot(a, b)
        / denominator
    )


# ============================================================
# SECTOR VECTOR SIMILARITY
# ============================================================

def sector_vector_similarity(
    roads: dict[str, RoadGeometry],
) -> dict[str, float]:

    if len(roads) < 2:
        return {}

    states = list(
        roads.keys()
    )

    matrix = np.vstack(
        [
            roads[state]
            .sector_ratios
            for state in states
        ]
    )

    # Mean observed road geometry.
    template = np.mean(
        matrix,
        axis=0,
    )

    template_norm = (
        np.linalg.norm(
            template
        )
    )

    if template_norm == 0:

        return {
            state: 0.0
            for state in states
        }

    scores = []

    for vector in matrix:

        denominator = (
            np.linalg.norm(
                vector
            )
            * template_norm
        )

        if denominator == 0:

            scores.append(
                0.0
            )

        else:

            scores.append(
                float(
                    np.dot(
                        vector,
                        template,
                    )
                    / denominator
                )
            )

    scores = np.asarray(
        scores
    )

    # Convert similarity to [0,1].
    scores = (
        scores + 1.0
    ) / 2.0

    return {
        state: float(
            scores[i]
        )
        for i, state in enumerate(
            states
        )
    }


# ============================================================
# REGIONAL DATA
# ============================================================

def construct_regions(
    abs_data: dict[str, dict],
    roads: dict[str, RoadGeometry],
) -> dict[str, RegionalData]:

    regions = {}

    for state, state_name in (
        STATES.items()
    ):

        latitude, longitude = (
            STATE_CAPITALS[state]
        )

        values = abs_data.get(
            state,
            {}
        )

        weekly = values.get(
            "weekly_earnings"
        )

        annual_income = (
            weekly * 52.0
            if weekly is not None
            else None
        )

        region = RegionalData(
            state=state,
            state_name=state_name,

            latitude=latitude,
            longitude=longitude,

            dwelling_count=values.get(
                "dwelling_count"
            ),

            dwelling_total_value=values.get(
                "dwelling_total_value"
            ),

            mean_dwelling_price=values.get(
                "mean_dwelling_price"
            ),

            median_dwelling_price=values.get(
                "median_dwelling_price"
            ),

            weekly_earnings=weekly,

            annual_income=annual_income,

            construction_quarter_change=(
                values.get(
                    "construction_quarter_change"
                )
            ),

            construction_annual_change=(
                values.get(
                    "construction_annual_change"
                )
            ),

            building_work_value=(
                values.get(
                    "building_work_value"
                )
            ),

            road=roads.get(
                state
            ),
        )

        fields = [
            region.mean_dwelling_price,
            region.weekly_earnings,
            region.construction_annual_change,
            region.building_work_value,
            region.dwelling_count,
            region.road,
        ]

        available = sum(
            x is not None
            for x in fields
        )

        region.data_coverage = (
            available
            / len(fields)
        )

        # Road data gets its own confidence contribution.
        if region.road is None:

            region.confidence = (
                region.data_coverage
                * 0.75
            )

        else:

            region.confidence = (
                region.data_coverage
            )

        regions[state] = region

    return regions


# ============================================================
# PREDICTION
# ============================================================

def predict_regions(
    regions: dict[str, RegionalData],
) -> list[Prediction]:

    states = list(
        regions.keys()
    )

    property_values = [
        regions[state]
        .mean_dwelling_price
        for state in states
    ]

    income_values = [
        regions[state]
        .annual_income
        for state in states
    ]

    construction_values = [
        regions[state]
        .construction_annual_change
        for state in states
    ]

    building_values = [
        regions[state]
        .building_work_value
        for state in states
    ]

    dwelling_values = [
        regions[state]
        .dwelling_count
        for state in states
    ]

    property_score = log_normalize(
        property_values
    )

    income_score = log_normalize(
        income_values
    )

    construction_score = normalize(
        construction_values
    )

    building_score = log_normalize(
        building_values
    )

    dwelling_score = log_normalize(
        dwelling_values
    )

    road_scores = (
        calculate_road_scores(
            {
                state:
                    regions[state].road
                for state in states
                if regions[state].road
                is not None
            }
        )
    )

    vector_scores = (
        sector_vector_similarity(
            {
                state:
                    regions[state].road
                for state in states
                if regions[state].road
                is not None
            }
        )
    )

    predictions = []

    for i, state in enumerate(
        states
    ):

        region = regions[state]

        road_score = road_scores.get(
            state,
            0.0
        )

        geometry_similarity = (
            vector_scores.get(
                state,
                0.0
            )
        )

        # ----------------------------------------------------
        # Composite score.
        #
        # Economic:
        #   property       25%
        #   income         15%
        #   construction   10%
        #   building       15%
        #   dwellings      10%
        #
        # Geometry:
        #   road density / anisotropy /
        #   alignment       15%
        #   sector geometry 10%
        #
        # Total = 100%
        # ----------------------------------------------------

        raw_score = (
            0.25
            * property_score[i]
            +
            0.15
            * income_score[i]
            +
            0.10
            * construction_score[i]
            +
            0.15
            * building_score[i]
            +
            0.10
            * dwelling_score[i]
            +
            0.15
            * road_score
            +
            0.10
            * geometry_similarity
        )

        score = (
            raw_score
            * region.confidence
        )

        explanation_parts = []

        if (
            region.mean_dwelling_price
            is not None
        ):

            explanation_parts.append(
                "property"
            )

        if (
            region.annual_income
            is not None
        ):

            explanation_parts.append(
                "income"
            )

        if (
            region.building_work_value
            is not None
        ):

            explanation_parts.append(
                "building activity"
            )

        if (
            region.construction_annual_change
            is not None
        ):

            explanation_parts.append(
                "construction trend"
            )

        if region.road is not None:

            explanation_parts.append(
                "road geometry"
            )

        explanation = (
            ", ".join(
                explanation_parts
            )
            if explanation_parts
            else
            "limited data"
        )

        predictions.append(
            Prediction(
                state=state,

                state_name=(
                    region.state_name
                ),

                score=float(
                    score
                ),

                property_score=float(
                    property_score[i]
                ),

                income_score=float(
                    income_score[i]
                ),

                construction_score=float(
                    construction_score[i]
                ),

                building_score=float(
                    building_score[i]
                ),

                dwelling_score=float(
                    dwelling_score[i]
                ),

                road_score=float(
                    road_score
                ),

                confidence=float(
                    region.confidence
                ),

                explanation=(
                    explanation
                ),
            )
        )

    predictions.sort(
        key=lambda x: x.score,
        reverse=True,
    )

    return predictions


