def prime_factorization(
    n: int,
) -> list[int]:

    n = abs(
        int(n)
    )

    if n < 2:
        return []

    factors = []

    divisor = 2

    while (
        divisor
        * divisor
        <= n
    ):

        while (
            n % divisor
            == 0
        ):

            factors.append(
                divisor
            )

            n //= divisor

        if divisor == 2:
            divisor = 3
        else:
            divisor += 2

    if n > 1:

        factors.append(
            n
        )

    return factors


def factor_vector(
    n: int,
) -> dict[int, int]:

    result = {}

    for factor in prime_factorization(
        n
    ):

        result[factor] = (
            result.get(
                factor,
                0,
            )
            + 1
        )

    return result


def vector_product(
    vector: dict[int, int],
) -> int:

    result = 1

    for prime, exponent in (
        vector.items()
    ):

        result *= (
            prime
            ** exponent
        )

    return result


def candidate_product(
    candidates: list[Candidate],
) -> int:

    result = 1

    for candidate in candidates:

        result *= int(
            candidate.person.value
        )

    return result


def product_solver(
    target: int,
    values: list[float],
    beam_width: int = 16,
) -> list[dict[str, Any]]:

    if target <= 0:

        return []

    integer_values = []

    for value in values:

        try:

            integer = int(
                round(value)
            )

        except Exception:

            continue

        if integer > 1:
            integer_values.append(
                integer
            )

    if not integer_values:
        return []

    target_factors = (
        factor_vector(
            target
        )
    )

    states = [
        (
            1,
            [],
        )
    ]

    for value in integer_values:

        value_factors = (
            factor_vector(
                value
            )
        )

        next_states = []

        for current_product, chosen in (
            states
        ):

            new_product = (
                current_product
                * value
            )

            if (
                target
                % new_product
                == 0
            ):

                next_states.append(
                    (
                        new_product,
                        chosen
                        + [value],
                    )
                )

        states.extend(
            next_states
        )

        # ----------------------------------------------------
        # Keep unique states.
        # ----------------------------------------------------

        unique = {}

        for product, chosen in states:

            if product not in unique:

                unique[
                    product
                ] = chosen

        states = list(
            unique.items()
        )

        # ----------------------------------------------------
        # Beam pruning.
        # Prefer products closer to target in log space.
        # ----------------------------------------------------

        states.sort(
            key=lambda item:
                abs(
                    math.log(
                        target
                    )
                    - math.log(
                        item[0]
                    )
                )
        )

        states = states[
            :beam_width
        ]

    solutions = []

    for product, chosen in states:

        if product == target:

            solutions.append(
                {
                    "target":
                        target,

                    "product":
                        product,

                    "values":
                        chosen,

                    "exact":
                        True,

                    "factor_vector":
                        factor_vector(
                            product
                        ),

                    "target_factor_vector":
                        target_factors,
                }
            )

    return solutions


