@dataclass
class Uncertainty:
    confidence: float

    def __post_init__(self):
        self.confidence = max(
            0.0,
            min(1.0, float(self.confidence)),
        )

    @property
    def uncertainty(self) -> float:
        return 1.0 - self.confidence

    def as_dict(self) -> dict:
        return {
            "confidence": round(
                self.confidence,
                6,
            ),
            "uncertainty": round(
                self.uncertainty,
                6,
            ),
        }


