    identifier: str
    region_type: str

    x: int
    y: int
    width: int
    height: int

    uncertainty: Uncertainty

    source: str = "camera"

    observation_id: str = field(
        default_factory=lambda:
            new_identifier("observation")
    )

    def center(self) -> tuple[int, int]:
        return (
            self.x + self.width // 2,
            self.y + self.height // 2,
        )

    def area(self) -> int:
        return max(
            0,
            self.width * self.height,
