class Scratchpad:

    def __init__(
        self,
        max_entries: int = 100,
    ):
        self.max_entries = max_entries

        self.entries: list[
            ScratchpadEntry
        ] = []

    def add(
        self,
        identifier: str,
        thought: str,
        evidence: Optional[
            list[str]
        ] = None,
    ):

        self.entries.append(
            ScratchpadEntry(
                timestamp=time.time(),
                identifier=identifier,
                thought=thought,
                evidence=evidence or [],
            )
        )

        if len(self.entries) > self.max_entries:

            self.entries = (
                self.entries[
                    -self.max_entries:
                ]
            )

    def recent(
        self,
        n: int = 10,
    ) -> list[ScratchpadEntry]:

        return self.entries[-n:]

    def display(self):

        print()
        print(
            "---------------- SCRATCHPAD ----------------"
        )

        if not self.entries:

            print(
                "(empty)"
            )

        for entry in self.recent():

            print(
                f"[{entry.identifier}] "
                f"{entry.thought}"
            )

            for evidence in entry.evidence:

                print(
                    f"    evidence: {evidence}"
                )

        print(
            "---------------------------------------------"
        )

    def save(self, path: Path):

        data = [
            entry.as_dict()
            for entry in self.entries
        ]

        path.write_text(
            json.dumps(
                data,
                indent=2,
