                ),
                arguments=(
                    relation.source_region,
                    relation.target_region,
                ),
                confidence=(
                    relation.confidence
                ),
            )
        )

    def add_action_candidate(
        self,
        action: str,
        region_id: str,
        confidence: float,
    ):

        self.ontology.append(
            OntologyStatement(
                predicate="ActionCandidate",
                arguments=(
                    action,
                    region_id,
                ),
                confidence=confidence,
            )
        )

    def add_human_decision(
        self,
        region_id: str,
        action: str,
        decision: str,
    ):

        predicate = {
            "approve": "HumanApproved",
            "skip": "HumanRejected",
            "reperceive": "HumanRequestedReperception",
            "quit": "HumanStopped",
        }.get(
            decision,
            "HumanDecision",
        )

        self.ontology.append(
            OntologyStatement(
                predicate=predicate,
                arguments=(
                    region_id,
                    action,
                ),
            )
        )

    def find_borders(
        self,
        region_id: str,
    ) -> list[RegionRelation]:

        return [
            relation
            for relation in self.relations
            if (
                relation.relation_type
                == "border"
            )
            and (
                relation.source_region
                == region_id
                or
                relation.target_region
                == region_id
            )
        ]

    def ontology_text(self) -> str:

        return "\n".join(
            statement.render()
            for statement in self.ontology
        )

    def as_dict(self) -> dict:

        return {
            "observation_id":
                self.observation_id,

            "requested_exposure_seconds":
                self.exposure_seconds,

            "requested_exposure_us":
                EXPOSURE_US,

            "regions": [
                region.as_dict()
                for region
                in self.regions.values()
            ],

            "relations": [
                relation.as_dict()
                for relation
                in self.relations
            ],

            "ontology": [
                statement.as_dict()
                for statement
                in self.ontology
            ],
        }

    def save(
        self,
        path: Path,
    ):

        path.write_text(
            json.dumps(
                self.as_dict(),
                indent=2,
            ),
            encoding="utf-8",
        )


