# CAMERA
# ============================================================

class VisionCamera:

    def __init__(
        self,
        width: int = WIDTH,
        height: int = HEIGHT,
    ):

        self.width = width
        self.height = height

        self.cap = None

        self.camera_index = None

        self.real_camera_active = False

        self.requested_exposure_seconds = (
            EXPOSURE_SECONDS
        )

        self.requested_exposure_us = (
            EXPOSURE_US
        )

        self.open_camera()

    def open_camera(self):

        backend = (
            cv2.CAP_DSHOW
            if sys.platform.startswith("win")
            else cv2.CAP_ANY
        )

        for index in range(3):

            print(
                f"[CAMERA] Trying index {index}..."
            )

            cap = cv2.VideoCapture(
                index,
                backend,
            )

            if not cap.isOpened():

                cap.release()
                continue

            try:

                cap.set(
                    cv2.CAP_PROP_FRAME_WIDTH,
                    self.width,
                )

                cap.set(
                    cv2.CAP_PROP_FRAME_HEIGHT,
                    self.height,
                )

                # Attempt to request manual exposure.
                #
                # OpenCV does not define a universal
                # exposure unit. Therefore this is only
                # a backend request, not a physical guarantee.

                cap.set(
                    cv2.CAP_PROP_AUTO_EXPOSURE,
                    0.25,
                )

                cap.set(
                    cv2.CAP_PROP_EXPOSURE,
                    self.requested_exposure_seconds,
                )

                ret, frame = cap.read()

                if (
                    ret
                    and frame is not None
                    and frame.size > 0
                ):

                    self.cap = cap

                    self.camera_index = index

                    self.real_camera_active = True

                    print(
                        "[CAMERA] Connected to "
                        f"physical camera index "
                        f"{index}."
                    )

                    print(
                        "[CAMERA] Requested exposure: "
                        f"{self.requested_exposure_us} us "
                        f"(0.5 ms)"
                    )

                    return

            except Exception as exc:

                print(
                    "[CAMERA] Initialization error: "
                    f"{exc}"
                )

            cap.release()

        print(
            "[CAMERA] No stable physical "
            "camera found."
        )

        print(
            "[CAMERA] Using synthetic "
            "camera fallback."
        )

    def configure_exposure(self):

        if self.cap is None:
            return

        try:

            self.cap.set(
                cv2.CAP_PROP_EXPOSURE,
                self.requested_exposure_seconds,
            )

        except Exception:
            pass

    def synthetic_frame(
        self,
    ) -> np.ndarray:

        frame = np.zeros(
            (
                self.height,
                self.width,
                3,
            ),
            dtype=np.uint8,
        )

        frame[:] = (
            30,
            30,
            35,
        )

        # Two touching regions are included
        # so that the border relation can be demonstrated.

        cv2.rectangle(
            frame,
            (540, 280),
            (640, 380),
            (0, 0, 255),
            -1,
        )

        cv2.rectangle(
            frame,
            (640, 280),
            (740, 380),
            (0, 0, 255),
            -1,
        )

        cv2.putText(
            frame,
            "SYNTHETIC CAMERA",
            (40, 180),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.8,
            (255, 255, 255),
            2,
        )

        cv2.putText(
            frame,
            "REQUESTED EXPOSURE: 0.5 ms",
            (40, 220),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.65,
            (0, 255, 255),
            2,
        )

        return frame

    def capture_decision_frame(
        self,
    ) -> np.ndarray:

        """
        Capture the exact image that will be shown
        to the human before the decision.

        The important ordering is:

            configure exposure
            capture
            return frame
            show frame
            decide
        """

        if self.cap is None:

            return self.synthetic_frame()

        self.configure_exposure()

        # Flush one previous frame where possible.
        try:
            self.cap.grab()
        except Exception:
            pass

        ret, frame = self.cap.read()

        if (
            not ret
            or frame is None
            or frame.size == 0
        ):

            print(
                "[CAMERA] Frame acquisition "
                "failed; using fallback."
            )

            return self.synthetic_frame()

        frame = np.ascontiguousarray(
            frame
        )

        frame = cv2.resize(
            frame,
            (
                self.width,
                self.height,
            ),
        )

        return frame

    def close(self):

        if self.cap is not None:

            self.cap.release()

            self.cap = None


