class CameraPerception:

    def detect_red_regions(
        self,
        frame: np.ndarray,
    ) -> list[Region]:

        hsv = cv2.cvtColor(
            frame,
            cv2.COLOR_BGR2HSV,
        )

        lower_red1 = np.array(
            [0, 80, 50],
            dtype=np.uint8,
        )

        upper_red1 = np.array(
            [12, 255, 255],
            dtype=np.uint8,
        )

        lower_red2 = np.array(
            [170, 80, 50],
            dtype=np.uint8,
        )

        upper_red2 = np.array(
            [180, 255, 255],
            dtype=np.uint8,
        )

        mask1 = cv2.inRange(
            hsv,
            lower_red1,
            upper_red1,
        )

        mask2 = cv2.inRange(
            hsv,
            lower_red2,
            upper_red2,
        )

        mask = cv2.bitwise_or(
            mask1,
            mask2,
        )

        kernel = np.ones(
            (5, 5),
            dtype=np.uint8,
        )

        mask = cv2.morphologyEx(
            mask,
            cv2.MORPH_OPEN,
            kernel,
        )

        mask = cv2.morphologyEx(
            mask,
            cv2.MORPH_CLOSE,
            kernel,
        )

        contours, _ = cv2.findContours(
            mask,
            cv2.RETR_EXTERNAL,
            cv2.CHAIN_APPROX_SIMPLE,
        )

        regions = []

        for contour in contours:

            area = cv2.contourArea(
                contour
            )

            if area < 100:
                continue

            x, y, w, h = (
                cv2.boundingRect(
                    contour
                )
            )

            # Confidence is based on visual evidence
            # rather than being treated as certainty.
            #
            # This is an illustrative confidence model,
            # not a calibrated probability.

            confidence = min(
                0.99,
                0.45
                + math.log10(
                    max(area, 1)
                ) / 10.0,
            )

            regions.append(
                Region(
                    identifier=new_identifier(
                        "region"
                    ),
                    region_type="red_object",
                    x=x,
                    y=y,
                    width=w,
                    height=h,
                    uncertainty=Uncertainty(
                        confidence
                    ),
                )
            )

        return regions


# ============================================================
# BORDER / COMPATIBILITY RELATION
# ============================================================

def regions_share_border(
    a: Region,
    b: Region,
    tolerance: int = 8,
) -> bool:

    ax1 = a.x
    ay1 = a.y
    ax2 = a.x + a.width
    ay2 = a.y + a.height

    bx1 = b.x
    by1 = b.y
    bx2 = b.x + b.width
    by2 = b.y + b.height

    vertical_touch = (
        abs(ax2 - bx1) <= tolerance
        or
        abs(bx2 - ax1) <= tolerance
    )

    horizontal_overlap = (
        max(ay1, by1)
        <=
        min(ay2, by2)
    )

    horizontal_touch = (
        abs(ay2 - by1) <= tolerance
        or
        abs(by2 - ay1) <= tolerance
    )

    vertical_overlap = (
        max(ax1, bx1)
        <=
        min(ax2, bx2)
    )

    return (
        (
            vertical_touch
            and horizontal_overlap
        )
        or
        (
            horizontal_touch
            and vertical_overlap
        )
    )


def build_region_relations(
    regions: list[Region],
) -> list[RegionRelation]:

    relations = []

    for i in range(len(regions)):

        for j in range(
            i + 1,
            len(regions),
        ):

            a = regions[i]
            b = regions[j]

            if regions_share_border(
                a,
                b,
            ):

                confidence = min(
                    a.uncertainty.confidence,
                    b.uncertainty.confidence,
                )

                relations.append(
                    RegionRelation(
                        relation_type="border",
                        source_region=(
                            a.identifier
                        ),
                        target_region=(
                            b.identifier
                        ),
                        confidence=confidence,
                    )
                )

    return relations


