class ActionPlanner:

    def propose(
        self,
        world: WorldModel,
        scratchpad: Scratchpad,
    ):

        if not world.regions:

            scratchpad.add(
                "planner",
                "No visual region available.",
            )

            return None

        # Highest-confidence region is selected.
        # This is a planning heuristic, not a claim
        # that the region is certainly the target.

        region = max(
            world.regions.values(),
            key=lambda item:
                item.uncertainty.confidence,
        )

        confidence = (
            region.uncertainty.confidence
        )

        uncertainty = (
            region.uncertainty.uncertainty
        )

        scratchpad.add(
            region.identifier,
            "Candidate region selected.",
            [
                f"confidence={confidence:.3f}",
                f"uncertainty={uncertainty:.3f}",
                f"type={region.region_type}",
            ],
        )

        if confidence >= 0.80:

            action = (
                "approach_and_grasp"
            )

        elif confidence >= 0.55:

            action = (
                "approach_for_verification"
            )

        else:

            action = "observe_again"

        world.add_action_candidate(
            action,
            region.identifier,
            confidence,
        )

        scratchpad.add(
            region.identifier,
            f"Proposed action: {action}",
            [
                f"confidence={confidence:.3f}",
                f"uncertainty={uncertainty:.3f}",
            ],
        )

        return region, action


