# ============================================================
# TRAJECTORY / SUBSET-SUM PLANNER
# ============================================================

def _materialize(node):

    out = []

    while node is not None:

        move_id, node = node

        out.append(move_id)

    out.reverse()

    return out


def equation_beam_search(
    nums,
    target,
    r,
    c=2,
    max_beam_width=2000,
):

    n = len(nums)

    if n == 0:

        return (
            [] if target == 0 else None,
            0,
        )

    cap = min(
        max(1, n ** c),
        max(
            1,
            max_beam_width,
        ),
    )

    beam = [
        (0, None)
    ]

    for k in range(
        1,
        n + 1,
    ):

        value = nums[k - 1]

        seen = {}

        for partial, node in beam:

            if partial not in seen:

                seen[
                    partial
                ] = node

            new_partial = (
                partial + value
            )

            if (
                new_partial <= target
                and
                new_partial not in seen
            ):

                seen[
                    new_partial
                ] = (
                    k - 1,
                    node,
                )

        if target in seen:

            return (
                _materialize(
                    seen[target]
                ),
                k,
            )

        safe_r = min(
            max(
                float(r),
                1e-12,
            ),
            1.0 - 1e-12,
        )

        log_width = (
            n * math.log(2)
            +
            k * math.log(
                safe_r
            )
        )

        if log_width > math.log(
            cap
        ):

            width = cap

        else:

            try:

                width = max(
                    1,
                    min(
                        cap,
                        math.ceil(
                            math.exp(
                                log_width
                            )
                        ),
                    ),
                )

            except OverflowError:

                width = cap

        if len(seen) <= width:

            beam = list(
                seen.items()
            )

        else:

            beam = heapq.nsmallest(
                width,
                seen.items(),
                key=lambda item:
                    abs(
                        target
                        - item[0]
                    ),
            )

    return None, n


def measure_r(
    nums,
    sample_size=24,
    subset_fraction=5,
    seed=None,
):

    rng = random.Random(seed)

    if not nums:

        return (
            1e-6,
            1,
            0,
            0,
        )

    sample_size = min(
        sample_size,
        len(nums),
    )

    sample = rng.sample(
        list(nums),
        sample_size,
    )

    subset_target = sum(
        rng.sample(
            sample,
            max(
                1,
                min(
                    subset_fraction,
                    sample_size,
                ),
            ),
        )
    )

    suffix = [
        0
        for _ in range(
            sample_size + 1
        )
    ]

    for i in range(
        sample_size - 1,
        -1,
        -1,
    ):

        suffix[i] = (
            suffix[i + 1]
            + sample[i]
        )

    nodes = 0

    stack = [
        (0, 0)
    ]

    while stack:

        index, partial = (
            stack.pop()
        )

        nodes += 1

        if partial == subset_target:

            break

        if (
            index == sample_size
            or
            partial > subset_target
            or
            partial
            + suffix[index]
            < subset_target
        ):

            continue

        stack.append(
            (
                index + 1,
                partial,
            )
        )

        stack.append(
            (
                index + 1,
                partial
                + sample[index],
            )
        )

    ratio = (
        nodes
        /
        max(
            2 ** sample_size,
            1,
        )
    )

    ratio = max(
        ratio,
        1e-300,
    )

    r = (
        1
        -
        math.exp(
            math.log(ratio)
            /
            sample_size
        )
    )

    r = min(
        max(
            r,
            1e-6,
        ),
        1 - 1e-6,
    )

    return (
        r,
        nodes,
        sample_size,
        subset_target,
    )


@dataclass
class AxisJob:
    limb: str
    axis: str
    moves: Sequence[
        CartesianMove
    ]
    target: CartesianTarget

    is_approach_axis: bool = False

    c: float = 2.0

    max_beam_width: int = 2000

    r: Optional[float] = None

    seed: Optional[int] = None

    coordinate_unit_m: float = 0.001

    precision_weight: int = 1


@dataclass
class AxisResult:
    limb: str
    axis: str

    found: bool

    move_ids_used: list[int] = (
        field(default_factory=list)
    )

    displacement_m: float = 0.0


def target_units(
    job: AxisJob,
) -> int:

    return (
        round(
            job.target.coordinate(
                job.axis
            )
            /
            job.coordinate_unit_m
        )
        +
        (
            job.target.precision_ticks
            *
            job.precision_weight
        )
    )


def move_units(
    job: AxisJob,
    move: CartesianMove,
) -> int:

    return (
        round(
            move.displacement(
                job.axis
            )
            /
            job.coordinate_unit_m
        )
        +
        (
            move.precision_ticks
            *
            job.precision_weight
        )
    )


def solve_one_axis(
    job: AxisJob,
) -> AxisResult:

    values = [
        move_units(
            job,
            move,
        )
        for move in job.moves
    ]

    target = target_units(
        job
    )

    if job.r is None:

        r_used = measure_r(
            values,
            seed=job.seed,
        )[0]

    else:

        r_used = job.r

    result, _ = (
        equation_beam_search(
            values,
            target,
            r_used,
            c=job.c,
            max_beam_width=(
                job.max_beam_width
            ),
        )
    )

    if result is None:

        return AxisResult(
            limb=job.limb,
            axis=job.axis,
            found=False,
        )

    remaining = list(
        job.moves
    )

    selected_ids = []

    for value in result:

        for index, move in enumerate(
            remaining
        ):

            if (
                move_units(
                    job,
                    move,
                )
                == value
            ):

                selected_ids.append(
                    move.move_id
                )

                remaining.pop(
                    index
                )

                break

    by_id = {
        move.move_id: move
        for move in job.moves
    }

    coord_units = sum(
        round(
            by_id[
                move_id
            ].displacement(
                job.axis
            )
            /
            job.coordinate_unit_m
        )
        for move_id
        in selected_ids
    )

    return AxisResult(
        limb=job.limb,
        axis=job.axis,
        found=True,
        move_ids_used=selected_ids,
        displacement_m=(
            coord_units
            *
            job.coordinate_unit_m
        ),
    )


def solve_all_limbs(
    jobs: Sequence[AxisJob],
    max_workers=None,
):

    results = {}

    if not jobs:

        return results

    with ProcessPoolExecutor(
        max_workers=max_workers
    ) as pool:

        futures = {
            pool.submit(
                solve_one_axis,
                job,
            ): (
                job.limb,
                job.axis,
            )
            for job in jobs
        }

        for future in as_completed(
            futures
        ):

            key = futures[
                future
            ]

            results[key] = (
                future.result()
            )

    return results


# ============================================================
# VISUAL DECISION SNAPSHOT
# ============================================================

def draw_decision_snapshot(
    frame: np.ndarray,
    regions: list[Region],
    relations: list[RegionRelation],
    selected_id: Optional[str] = None,
) -> np.ndarray:

    display = frame.copy()

    region_map = {
        region.identifier: region
        for region in regions
    }

    # --------------------------------------------------------
    # Border relationships
    # --------------------------------------------------------

    for relation in relations:

        a = region_map.get(
            relation.source_region
        )

        b = region_map.get(
            relation.target_region
        )

        if a is None or b is None:

            continue

        cv2.line(
            display,
            a.center(),
            b.center(),
            (255, 0, 255),
            3,
        )

    # --------------------------------------------------------
    # Regions
    # --------------------------------------------------------

    for region in regions:

        selected = (
            region.identifier
            == selected_id
        )

        thickness = (
            5
            if selected
            else 2
        )

        cv2.rectangle(
            display,
            (
                region.x,
                region.y,
            ),
            (
                region.x
                + region.width,
                region.y
                + region.height,
            ),
            (0, 255, 255),
            thickness,
        )

        cx, cy = region.center()

        cv2.circle(
            display,
            (cx, cy),
            7,
            (0, 0, 255),
            -1,
        )

        label = (
            f"{region.identifier}"
        )

        cv2.putText(
            display,
            label,
            (
                region.x,
                max(
                    165,
                    region.y - 28,
                ),
            ),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.48,
            (0, 255, 255),
            2,
        )

        confidence_text = (
            f"C={region.uncertainty.confidence:.3f} "
            f"U={region.uncertainty.uncertainty:.3f}"
        )

        cv2.putText(
            display,
            confidence_text,
            (
                region.x,
                max(
                    185,
                    region.y - 8,
                ),
            ),
            cv2.FONT_HERSHEY_SIMPLEX,
            0.48,
            (255, 255, 255),
            2,
        )

    # --------------------------------------------------------
    # Header
    # --------------------------------------------------------

    cv2.rectangle(
        display,
        (20, 20),
        (
            display.shape[1] - 20,
            145,
        ),
        (15, 15, 20),
        -1,
    )

    cv2.rectangle(
        display,
        (20, 20),
        (
            display.shape[1] - 20,
            145,
        ),
        (0, 255, 255),
        2,
    )

    cv2.putText(
        display,
        "0.5 ms EXPOSURE - DECISION SNAPSHOT",
        (40, 55),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.68,
        (255, 255, 255),
        2,
    )

    cv2.putText(
        display,
        "IMAGE SHOWN BEFORE DECISION",
        (40, 87),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.55,
        (0, 255, 255),
        2,
    )

    cv2.putText(
        display,
        f"REGIONS={len(regions)}  "
        f"BORDER RELATIONS={len(relations)}",
        (40, 118),
        cv2.FONT_HERSHEY_SIMPLEX,
        0.52,
        (255, 255, 255),
        2,
    )

    return display


# ============================================================
# ROBOT AGENT
# ============================================================

class VisionRobotAgent:

    def __init__(
        self,
        width: int = WIDTH,
        height: int = HEIGHT,
        save_frames: bool = True,
    ):

        self.width = width
        self.height = height

        self.save_frames = (
            save_frames
        )

        if self.save_frames:

            FRAME_DIR.mkdir(
                parents=True,
                exist_ok=True,
            )

        self.camera = VisionCamera(
            width=width,
            height=height,
        )

        self.perception = (
            CameraPerception()
        )

        self.world = WorldModel()

        self.scratchpad = (
            Scratchpad()
        )

        self.planner = (
            ActionPlanner()
        )

        self.human = (
            HumanIntervention()
        )

        self.running = True

        self.step_counter = 0

        self.gui_available = False

        try:

            cv2.namedWindow(
                "Vision Robot Agent",
                cv2.WINDOW_AUTOSIZE,
            )

            self.gui_available = True

        except Exception as exc:

            print(
                "[GUI] Window unavailable: "
                f"{exc}"
            )

    # ========================================================
    # PERCEPTION CYCLE
    # ========================================================

    def perceive(self):

        # -----------------------------------------------
        # EXACT DECISION FRAME
        # -----------------------------------------------

        frame = (
            self.camera
            .capture_decision_frame()
        )

        # -----------------------------------------------
        # PERCEIVE THAT SAME FRAME
        # -----------------------------------------------

        regions = (
            self.perception
            .detect_red_regions(
                frame
            )
        )

        # -----------------------------------------------
        # NEW WORLD STATE
        # -----------------------------------------------

        self.world = WorldModel()

        for region in regions:

            self.world.add_region(
                region
            )

        relations = (
            build_region_relations(
                regions
            )
        )

        for relation in relations:

            self.world.add_relation(
                relation
            )

        return frame, regions, relations

    # ========================================================
    # SHOW DECISION SNAPSHOT
    # ========================================================

    def show_snapshot(
        self,
        frame,
        regions,
        relations,
        selected_id=None,
    ):

        snapshot = (
            draw_decision_snapshot(
                frame,
                regions,
                relations,
                selected_id,
            )
        )

        if self.save_frames:

            filename = (
                FRAME_DIR
                /
                f"decision_"
                f"{self.step_counter:04d}"
                f"_500us.png"
            )

            cv2.imwrite(
                str(filename),
                snapshot,
            )

            print(
                "[CAMERA] Snapshot saved:"
                f" {filename}"
            )

        if self.gui_available:

            cv2.imshow(
                "Vision Robot Agent",
                snapshot,
            )

            # A tiny GUI update allows the image to
            # become visible before input() blocks
            # the Python loop.

            cv2.waitKey(1)

        return snapshot

    # ========================================================
    # HUMAN DECISION
    # ========================================================

    def human_decision(
        self,
        region,
        action,
    ):

        # The snapshot has already been displayed.
        decision = (
            self.human.decision(
                region,
                action,
            )
        )

        self.world.add_human_decision(
            region.identifier,
            action,
            decision,
        )

        return decision

    # ========================================================
    # EXECUTE ROBOT ACTION
    # ========================================================

    def execute_action(
        self,
        region: Region,
        action: str,
    ):

        self.scratchpad.add(
            region.identifier,
            f"Executing {action}.",
            [
                "human_approved=True",
                "decision_snapshot_exposure=0.5ms",
            ],
        )

        print()
        print(
            f"[ROBOT] ACTION = {action}"
        )

        print(
            f"[ROBOT] TARGET = "
            f"{region.identifier}"
        )

        print(
            f"[ROBOT] CONFIDENCE = "
            f"{region.uncertainty.confidence:.3f}"
        )

        if action == "approach_and_grasp":

            print(
                "[ROBOT] Approaching target."
            )

            time.sleep(0.25)

            print(
                "[ROBOT] Grasp operation "
                "would occur here."
            )

        elif (
            action
            == "approach_for_verification"
        ):

            print(
                "[ROBOT] Verification approach."
            )

            time.sleep(0.25)

        elif action == "observe_again":

            print(
                "[ROBOT] Additional observation "
                "requested."
            )

    # ========================================================
    # ONE FULL REASONING LOOP
    # ========================================================

    def cycle(self):

        print()
        print(
            "============================================================"
        )

        print(
            f"AGENT CYCLE {self.step_counter}"
        )

        print(
            "Requested camera exposure: "
            "0.5 ms / 500 us"
        )

        print(
            "============================================================"
        )

        # ----------------------------------------------------
        # 1. CAMERA
        # ----------------------------------------------------

        frame, regions, relations = (
            self.perceive()
        )

        print(
            f"[PERCEPTION] "
            f"{len(regions)} region(s)"
        )

        print(
            f"[RELATIONS] "
            f"{len(relations)} border relation(s)"
        )

        # ----------------------------------------------------
        # 2. PLANNER
        # ----------------------------------------------------

        proposal = (
            self.planner.propose(
                self.world,
                self.scratchpad,
            )
        )

        # ----------------------------------------------------
        # 3. NO TARGET
        # ----------------------------------------------------

        if proposal is None:

            self.show_snapshot(
                frame,
                regions,
                relations,
            )

            print(
                "[PLANNER] No action proposed."
            )

            self.step_counter += 1

            return

        region, action = proposal

        # ----------------------------------------------------
        # 4. SHOW IMAGE BEFORE DECISION
        # ----------------------------------------------------

        self.show_snapshot(
            frame,
            regions,
            relations,
            selected_id=(
                region.identifier
            ),
        )

        # ----------------------------------------------------
        # 5. HUMAN SEES IMAGE
        # ----------------------------------------------------

        decision = (
            self.human_decision(
                region,
                action,
            )
        )

        # ----------------------------------------------------
        # 6. PROCESS HUMAN DECISION
        # ----------------------------------------------------

        if decision == "quit":

            self.scratchpad.add(
                region.identifier,
                "Human stopped autonomous loop.",
            )

            self.running = False

            return

        if decision == "skip":

            self.scratchpad.add(
                region.identifier,
                "Human rejected action.",
                [
                    "decision=skip",
                ],
            )

            print(
                "[HUMAN] Action skipped."
            )

            self.step_counter += 1

            return

        if decision == "reperceive":

            self.scratchpad.add(
                region.identifier,
                "Human requested another "
                "0.5 ms perception.",
            )

            print(
                "[HUMAN] Re-perception requested."
            )

            self.step_counter += 1

            return

        # ----------------------------------------------------
        # 7. HUMAN APPROVAL
        # ----------------------------------------------------

        self.scratchpad.add(
            region.identifier,
            "Human approved action.",
            [
                f"action={action}",
                "decision_snapshot=0.5ms",
            ],
        )

        # ----------------------------------------------------
        # 8. ACTION
        # ----------------------------------------------------

        self.execute_action(
            region,
            action,
        )

        self.step_counter += 1

    # ========================================================
    # RUN
    # ========================================================

    def run(self):

        print()
        print(
            "============================================================"
        )

        print(
            "VISION-ONTOLOGY ROBOTIC AGENT"
        )

        print(
            "============================================================"
        )

        print(
            "Shared identifiers connect perception, "
            "ontology, scratchpad and planning."
        )

        print(
            "Uncertainty remains explicit."
        )

        print(
            "Border relationships connect compatible "
            "neighboring regions."
        )

        print(
            "A 0.5 ms exposure snapshot is displayed "
            "before the human decision."
        )

        print(
            "The human can approve, reject, "
            "pause or request re-perception."
        )

        print(
            "============================================================"
        )

        try:

            while self.running:

                self.cycle()

                print()
                print(
                    "ONTOLOGY:"
                )

                print(
                    self.world.ontology_text()
                )

                self.scratchpad.display()

                # ------------------------------------------------
                # Save shared state after each decision cycle.
                # ------------------------------------------------

                self.world.save(
                    WORLD_FILE
                )

                self.scratchpad.save(
                    SCRATCHPAD_FILE
                )

                # ------------------------------------------------
                # Small delay prevents a runaway loop.
                # ------------------------------------------------

                time.sleep(0.05)

        except KeyboardInterrupt:

            print(
                "\n[INFO] Keyboard interrupt."
            )

        finally:

            self.close()

    # ========================================================
    # CLOSE
    # ========================================================

    def close(self):

        self.camera.close()

        if self.gui_available:

            try:
                cv2.destroyAllWindows()
            except Exception:
                pass

        self.world.save(
            WORLD_FILE
        )

        self.scratchpad.save(
            SCRATCHPAD_FILE
        )

        print()
        print(
            "[INFO] Agent stopped."
        )

        print(
            f"[INFO] World model: "
            f"{WORLD_FILE.resolve()}"
        )

        print(
            f"[INFO] Scratchpad: "
            f"{SCRATCHPAD_FILE.resolve()}"
        )

        if self.save_frames:

            print(
                f"[INFO] Snapshots: "
                f"{FRAME_DIR.resolve()}"
            )


# ============================================================
# TRAJECTORY GENERATION
# ============================================================

def create_demo_jobs():

    random.seed(4)

    target = CartesianTarget(
        x_m=0.250,
        y_m=0.180,
        z_m=0.187,
        precision_ticks=2,
    )

    jobs = []

    for axis in AXES:

        moves = []

        for i in range(
            1,
            150,
        ):

            if axis == "x":

                moves.append(
                    CartesianMove(
                        move_id=i,
                        dx_m=(
                            random.randint(
                                1,
                                8,
                            )
                            /
                            1000.0
                        ),
                    )
                )

            elif axis == "y":

                moves.append(
                    CartesianMove(
                        move_id=i,
                        dy_m=(
                            random.randint(
                                1,
                                8,
                            )
                            /
                            1000.0
                        ),
                    )
                )

            else:

                moves.append(
                    CartesianMove(
                        move_id=i,
                        dz_m=(
                            random.randint(
                                1,
                                8,
                            )
                            /
                            1000.0
                        ),
                    )
                )

        seed_bytes = (
            f"left_arm:{axis}"
            .encode(
                "utf-8"
            )
        )

        seed = int(
            hashlib.sha256(
                seed_bytes
            ).hexdigest()[:8],
            16,
        )

        jobs.append(
            AxisJob(
                limb="left_arm",
                axis=axis,
                moves=moves,
                target=target,
                is_approach_axis=(
                    axis == "z"
                ),
                seed=seed,
            )
        )

    return jobs


# ============================================================
# INTERLEAVED TRAJECTORY DISPLAY
# ============================================================

def execute_interleaved_plan(
    limb: str,
    jobs_by_axis: dict[str, AxisJob],
    results_by_axis: dict[
        str,
        AxisResult,
    ],
    agent: VisionRobotAgent,
):

    tangential = [
        axis
        for axis, job
        in jobs_by_axis.items()
        if not job.is_approach_axis
    ]

    approach = [
        axis
        for axis, job
        in jobs_by_axis.items()
        if job.is_approach_axis
    ]

    for axes in (
        tangential,
        approach,
    ):

        positions = {
            axis: 0
            for axis in axes
        }

        while True:

            active = [
                axis
                for axis in axes
                if positions[axis]
                <
                len(
                    results_by_axis[
                        axis
                    ].move_ids_used
                )
            ]

            if not active:

                break

            for axis in active:

                job = (
                    jobs_by_axis[
                        axis
                    ]
                )

                result = (
                    results_by_axis[
                        axis
                    ]
                )

                move_id = (
                    result.move_ids_used[
                        positions[axis]
                    ]
                )

                move = next(
                    move
                    for move
                    in job.moves
                    if move.move_id
                    == move_id
                )

                print(
                    f"[TRAJECTORY] "
                    f"{limb} "
                    f"axis={axis} "
                    f"move={move.move_id} "
                    f"displacement="
                    f"{move.displacement(axis):.6f} m"
                )

                positions[axis] += 1


# ============================================================
# DEMO
# ============================================================

def _demo():

    print(
        "Computing precision trajectories..."
    )

    jobs = create_demo_jobs()

    results = solve_all_limbs(
        jobs
    )

    jobs_by_limb = {
        "left_arm": {
            job.axis: job
            for job in jobs
        }
    }

    axis_results = {}

    for axis in AXES:

        key = (
            "left_arm",
            axis,
        )

        result = results.get(
            key
        )

        if result is None:

            result = AxisResult(
                limb="left_arm",
                axis=axis,
                found=False,
            )

        axis_results[
            axis
        ] = result

        print(
            f"[PLANNER] "
            f"{axis.upper()} "
            f"found={result.found} "
            f"moves="
            f"{len(result.move_ids_used)} "
            f"displacement="
            f"{result.displacement_m:.6f} m"
        )

    print()
    print(
        "Starting vision-guided agent..."
    )

    agent = VisionRobotAgent(
        width=WIDTH,
        height=HEIGHT,
        save_frames=True,
    )

    # The trajectory is available to the agent,
    # but the visual decision loop remains independently
    # human-interruptible.

    try:

        execute_interleaved_plan(
            limb="left_arm",
            jobs_by_axis=(
                jobs_by_limb[
                    "left_arm"
                ]
            ),
            results_by_axis=(
                axis_results
            ),
            agent=agent,
        )

        print(
            "\nTrajectory calculation complete."
        )

        print(
            "Starting camera/ontology decision loop."
        )

        agent.run()

    finally:

        agent.close()


# ============================================================
# MAIN
# ============================================================

if __name__ == "__main__":

    freeze_support()

    _demo()
```
:::

The key ordering in this complete version is:

**capture → perception → build shared ontology → planner → display the 0.5 ms snapshot → human decision → action.**

The displayed image is saved as `decision_XXXX_500us.png`, while the shared machine-readable state goes into `robot_world_model.json` and the temporary reasoning state into `robot_scratchpad.json`.

One technical caveat remains: **500 µs is requested from OpenCV; it is not guaranteed to be the sensor's actual exposure time** because webcam drivers expose different exposure units and may ignore manual exposure settings.

