Yes. I’d deviate from the original where it improves the architecture: keep the **n-gram model as the actual generator**, use a small **in-memory directed graph derived from the same corpus counts** for diagnostics/context inspection, and avoid introducing NetworkX, embeddings, vector databases, or another model.

The main structural changes are:

- `CorpusGraph` is built directly from the existing bigram/trigram counts.
- Graphs **do not alter probabilities** or secretly become another model.
- The graph provides diagnostics: transition density, context branching, top transitions, and DOT output.
- Generation is concentrated in `NGramModel`.
- Corpus search remains a separate built-in lexical operation.
- Removed unnecessary `random`.
- Removed global reload spaghetti by using a single `AppState`.
- Added actual EOS stopping.
- Fixed the "universal" distribution so the uniform component really gives every vocabulary token support.
- Added generation diagnostics showing the probability distribution at the current context.
- Uses only Python standard-library graph structures (`dict`, `Counter`, `defaultdict`, sets) rather than a graph package.

Here is the complete replacement:

:::writing{variant="standard" id="58321" title="algorithm.py — graph-supported stochastic n-gram model"}
```python
from __future__ import annotations

import argparse
import itertools
import json
import math
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Iterable

import gradio as gr
import numpy as np


# ============================================================
# Configuration
# ============================================================

MODEL_PATH = Path("model.json")
DEFAULT_CORPUS_FILE = Path("corpus.txt")

MAX_NEW_TOKENS = 80
DEFAULT_TEMPERATURE = 0.8
DEFAULT_TOP_K = 20

MIN_COUNT = 1
SMOOTHING_ALPHA = 0.05

TRIGRAM_WEIGHT = 0.55
BIGRAM_WEIGHT = 0.30
UNIGRAM_WEIGHT = 0.10
UNIFORM_WEIGHT = 0.05

IGNORED_TOKENS = {
    "<bos>",
    "<eos>",
    "<unk>",
}


# ============================================================
# Text primitives
# ============================================================

def tokenize(text: str) -> list[str]:
    """Minimal corpus tokenizer.

    Deliberately avoids an external NLP dependency.
    """
    return text.lower().split()


def split_sentences(text: str) -> list[str]:
    """Simple sentence segmentation.

    This is intentionally lightweight rather than using an
    external NLP parser.
    """
    normalized = (
        text
        .replace("!", ".")
        .replace("?", ".")
    )

    return [
        part.strip()
        for part in normalized.split(".")
        if part.strip()
    ]


def visible_tokens(tokens: Iterable[str]) -> list[str]:
    return [
        token
        for token in tokens
        if token not in IGNORED_TOKENS
    ]


def bag_of_words(tokens: Iterable[str]) -> Counter:
    return Counter(
        token
        for token in tokens
        if token not in IGNORED_TOKENS
    )


# ============================================================
# Corpus mathematics
# ============================================================

def cosine_similarity(
    a: dict[str, float],
    b: dict[str, float],
) -> float:

    if not a or not b:
        return 0.0

    common = a.keys() & b.keys()

    dot = math.fsum(
        a[key] * b[key]
        for key in common
    )

    norm_a = math.sqrt(
        math.fsum(
            value * value
            for value in a.values()
        )
    )

    norm_b = math.sqrt(
        math.fsum(
            value * value
            for value in b.values()
        )
    )

    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0

    return dot / (norm_a * norm_b)


def lexical_overlap(
    a: Iterable[str],
    b: Iterable[str],
) -> float:

    set_a = set(a) - IGNORED_TOKENS
    set_b = set(b) - IGNORED_TOKENS

    if not set_a or not set_b:
        return 0.0

    union = set_a | set_b

    if not union:
        return 0.0

    return len(set_a & set_b) / len(union)


# ============================================================
# Corpus references
# ============================================================

@dataclass
class CorpusReference:
    sentence: str
    tokens: list[str]
    vector: dict[str, float]
    frequency: int = 1


@dataclass
class Candidate:
    sentence: str
    symbolic_overlap: float
    vector_similarity: float
    frequency: int
    score: float
    rank: int = 0


# ============================================================
# Corpus search
# ============================================================

class CorpusSearch:
    """Corpus lookup using only lexical statistics.

    This is deliberately separate from generation.

    It does not provide embeddings, semantic models, or external
    knowledge. It only compares corpus word counts.
    """

    def __init__(
        self,
        lexical_weight: float = 0.5,
        vector_weight: float = 0.5,
    ) -> None:

        self.lexical_weight = lexical_weight
        self.vector_weight = vector_weight

        self.references: list[CorpusReference] = []

    def build_index(self, corpus_text: str) -> None:

        sentences = split_sentences(corpus_text)

        frequencies = Counter(
            sentence.lower()
            for sentence in sentences
        )

        self.references.clear()

        for sentence in sentences:

            tokens = tokenize(sentence)

            if not tokens:
                continue

            bow = bag_of_words(tokens)

            self.references.append(
                CorpusReference(
                    sentence=sentence,
                    tokens=tokens,
                    vector={
                        token: float(count)
                        for token, count in bow.items()
                    },
                    frequency=frequencies[
                        sentence.lower()
                    ],
                )
            )

    def analyze(
        self,
        prompt: str,
        limit: int = 5,
    ) -> list[Candidate]:

        prompt_tokens = tokenize(prompt)

        prompt_vector = {
            token: float(count)
            for token, count
            in bag_of_words(prompt_tokens).items()
        }

        candidates: list[Candidate] = []

        for reference in self.references:

            symbolic = lexical_overlap(
                prompt_tokens,
                reference.tokens,
            )

            vector = cosine_similarity(
                prompt_vector,
                reference.vector,
            )

            score = (
                self.lexical_weight * symbolic
                + self.vector_weight * vector
            )

            candidates.append(
                Candidate(
                    sentence=reference.sentence,
                    symbolic_overlap=symbolic,
                    vector_similarity=vector,
                    frequency=reference.frequency,
                    score=score,
                )
            )

        candidates.sort(
            key=lambda item: item.score,
            reverse=True,
        )

        candidates = candidates[:limit]

        for rank, candidate in enumerate(
            candidates,
            start=1,
        ):
            candidate.rank = rank

        return candidates


# ============================================================
# Graph support
# ============================================================

@dataclass
class GraphNode:
    token: str
    frequency: int


@dataclass
class GraphEdge:
    source: str
    target: str
    count: int


class CorpusGraph:
    """A tiny directed corpus graph.

    The graph is SUPPORTING infrastructure.

    It is derived entirely from observed corpus transitions.
    It does not modify generation probabilities.

    Representation:

        nodes[token] -> frequency

        edges[source][target] -> observed transition count
    """

    def __init__(self) -> None:

        self.nodes: Counter[str] = Counter()

        self.edges: dict[str, Counter] = defaultdict(
            Counter
        )

    def clear(self) -> None:

        self.nodes.clear()
        self.edges.clear()

    def build(
        self,
        corpus_text: str,
    ) -> None:

        self.clear()

        for sentence in split_sentences(corpus_text):

            words = visible_tokens(
                tokenize(sentence)
            )

            if not words:
                continue

            self.nodes.update(words)

            for source, target in itertools.pairwise(words):

                self.edges[source][target] += 1

    def edge_count(self) -> int:
        return sum(
            len(targets)
            for targets in self.edges.values()
        )

    def transition_count(self) -> int:
        return sum(
            sum(targets.values())
            for targets in self.edges.values()
        )

    def branching_factor(
        self,
        token: str,
    ) -> int:

        return len(
            self.edges.get(token, {})
        )

    def outgoing(
        self,
        token: str,
    ) -> Counter:

        return Counter(
            self.edges.get(token, {})
        )

    def top_edges(
        self,
        limit: int = 40,
    ) -> list[GraphEdge]:

        result: list[GraphEdge] = []

        for source, targets in self.edges.items():

            for target, count in targets.items():

                result.append(
                    GraphEdge(
                        source=source,
                        target=target,
                        count=count,
                    )
                )

        result.sort(
            key=lambda edge: edge.count,
            reverse=True,
        )

        return result[:limit]

    def diagnostics(self) -> str:

        if not self.nodes:
            return "No graph has been built."

        nodes = len(self.nodes)
        edges = self.edge_count()
        transitions = self.transition_count()

        average_branching = (
            edges / nodes
            if nodes
            else 0.0
        )

        lines = [
            f"Graph nodes: {nodes}",
            f"Directed edges: {edges}",
            f"Observed transitions: {transitions}",
            f"Average branching: {average_branching:.3f}",
            "",
            "Most frequent transitions:",
        ]

        for edge in self.top_edges(15):

            lines.append(
                f"{edge.source} -> "
                f"{edge.target} "
                f"[{edge.count}]"
            )

        return "\n".join(lines)

    def to_dot(
        self,
        limit: int = 40,
    ) -> str:

        lines = [
            "digraph Corpus {",
            '  rankdir=LR;',
            '  graph [overlap=false];',
            '  node [shape=ellipse];',
        ]

        for edge in self.top_edges(limit):

            source = json.dumps(
                edge.source,
                ensure_ascii=False,
            )

            target = json.dumps(
                edge.target,
                ensure_ascii=False,
            )

            label = json.dumps(
                str(edge.count)
            )

            lines.append(
                f"  {source} -> {target} "
                f"[label={label}];"
            )

        lines.append("}")

        return "\n".join(lines)


