@dataclass
class NGramModel:

    eos_token: str = "<eos>"
    unk_token: str = "<unk>"

    min_count: int = MIN_COUNT
    smoothing_alpha: float = SMOOTHING_ALPHA

    unigram: Counter = field(
        default_factory=Counter
    )

    bigram: dict[str, Counter] = field(
        default_factory=lambda: defaultdict(Counter)
    )

    trigram: dict[str, Counter] = field(
        default_factory=lambda: defaultdict(Counter)
    )

    vocabulary: list[str] = field(
        default_factory=list
    )

    finalized: bool = False

    # --------------------------------------------------------
    # Training
    # --------------------------------------------------------

    def ingest_text(
        self,
        text: str,
    ) -> None:

        for sentence in split_sentences(text):

            words = tokenize(sentence)

            if not words:
                continue

            sequence = [
                "<bos>",
                "<bos>",
                *words,
                self.eos_token,
            ]

            self.unigram.update(sequence)

            for left, right in itertools.pairwise(
                sequence
            ):
                self.bigram[left][right] += 1

            for first, second, third in zip(
                sequence,
                sequence[1:],
                sequence[2:],
            ):
                context = (
                    f"{first}\t{second}"
                )

                self.trigram[
                    context
                ][third] += 1

        self.finalized = False

    def finalize(self) -> None:

        self.vocabulary = sorted(
            token
            for token, count
            in self.unigram.items()
            if count >= self.min_count
        )

        if self.unk_token not in self.vocabulary:

            self.vocabulary.append(
                self.unk_token
            )

        self.finalized = True

    # --------------------------------------------------------
    # Distribution primitives
    # --------------------------------------------------------

    def _distribution(
        self,
        counts: Counter,
    ) -> dict[str, float]:

        if not counts:
            return {}

        alpha = max(
            float(self.smoothing_alpha),
            0.0,
        )

        total = counts.total()

        if total <= 0:
            return {}

        if alpha == 0.0:

            return {
                token: count / total
                for token, count
                in counts.items()
                if count > 0
            }

        denominator = (
            total
            + alpha * len(counts)
        )

        return {
            token: (
                count + alpha
            ) / denominator

            for token, count
            in counts.items()
        }

    def _uniform_distribution(
        self,
    ) -> dict[str, float]:

        vocabulary = (
            self.vocabulary
            or list(self.unigram)
        )

        if not vocabulary:
            return {}

        probability = (
            1.0 / len(vocabulary)
        )

        return {
            token: probability
            for token in vocabulary
        }

    # --------------------------------------------------------
    # Context
    # --------------------------------------------------------

    def resolve_context(
        self,
        tokens: list[str],
    ) -> tuple[str, str]:

        if not tokens:
            return "<bos>", "<bos>"

        previous = tokens[-1]

        previous_previous = (
            tokens[-2]
            if len(tokens) >= 2
            else "<bos>"
        )

        return (
            previous,
            previous_previous,
        )

    # --------------------------------------------------------
    # Universal distribution
    # --------------------------------------------------------

    def universal_distribution(
        self,
        previous: str,
        previous_previous: str,
    ) -> dict[str, float]:

        components: list[
            tuple[float, dict[str, float]]
        ] = []

        trigram_counts = self.trigram.get(
            f"{previous_previous}\t{previous}",
            Counter(),
        )

        bigram_counts = self.bigram.get(
            previous,
            Counter(),
        )

        if trigram_counts:

            components.append(
                (
                    TRIGRAM_WEIGHT,
                    self._distribution(
                        trigram_counts
                    ),
                )
            )

        if bigram_counts:

            components.append(
                (
                    BIGRAM_WEIGHT,
                    self._distribution(
                        bigram_counts
                    ),
                )
            )

        if self.unigram:

            components.append(
                (
                    UNIGRAM_WEIGHT,
                    self._distribution(
                        self.unigram
                    ),
                )
            )

        uniform = (
            self._uniform_distribution()
        )

        if uniform:

            components.append(
                (
                    UNIFORM_WEIGHT,
                    uniform,
                )
            )

        if not components:
            return {}

        weight_total = math.fsum(
            weight
            for weight, _ in components
        )

        combined: defaultdict[
            str,
            float
        ] = defaultdict(float)

        for weight, distribution in components:

            normalized_weight = (
                weight / weight_total
            )

            for token, probability in (
                distribution.items()
            ):

                combined[token] += (
                    normalized_weight
                    * probability
                )

        total_probability = math.fsum(
            combined.values()
        )

        if total_probability <= 0.0:
            return {}

        return {
            token: value / total_probability
            for token, value
            in combined.items()
        }

    # --------------------------------------------------------
    # Diagnostics
    # --------------------------------------------------------

    def distribution_report(
        self,
        tokens: list[str],
        top_k: int = 20,
    ) -> str:

        previous, previous_previous = (
            self.resolve_context(tokens)
        )

        distribution = (
            self.universal_distribution(
                previous,
                previous_previous,
            )
        )

        if not distribution:
            return "No distribution available."

        ranked = sorted(
            distribution.items(),
            key=lambda item: item[1],
            reverse=True,
        )[:top_k]

        lines = [
            f"Previous: {previous}",
            f"Previous-previous: {previous_previous}",
            f"Distribution size: {len(distribution)}",
            "",
            "Highest probabilities:",
        ]

        for token, probability in ranked:

            lines.append(
                f"{token:<25} "
                f"{probability:.6f}"
            )

        return "\n".join(lines)

    # --------------------------------------------------------
    # Sampling
    # --------------------------------------------------------

    def sample_next(
        self,
        tokens: list[str],
        temperature: float = DEFAULT_TEMPERATURE,
        top_k: int = DEFAULT_TOP_K,
    ) -> str:

        if not self.finalized:
            self.finalize()

        previous, previous_previous = (
            self.resolve_context(tokens)
        )

        distribution = (
            self.universal_distribution(
                previous,
                previous_previous,
            )
        )

        if not distribution:
            return self.eos_token

        words = np.asarray(
            list(distribution.keys()),
            dtype=object,
        )

        probabilities = np.asarray(
            list(distribution.values()),
            dtype=np.float64,
        )

        temperature = max(
            float(temperature),
            1e-5,
        )

        log_probabilities = np.log(
            np.maximum(
                probabilities,
                np.finfo(float).tiny,
            )
        )

        scaled = (
            log_probabilities
            / temperature
        )

        k = max(
            1,
            min(
                int(top_k),
                len(words),
            ),
        )

        if k < len(words):

            indices = np.argpartition(
                scaled,
                -k,
            )[-k:]

        else:

            indices = np.arange(
                len(words)
            )

        weights = np.exp(
            scaled[indices]
            - np.max(scaled[indices])
        )

        weight_sum = weights.sum()

        if weight_sum <= 0:
            return self.eos_token

        weights /= weight_sum

        return str(
            np.random.choice(
                words[indices],
                p=weights,
            )
        )

    # --------------------------------------------------------
    # Generation
    # --------------------------------------------------------

    def generate(
        self,
        prompt: str,
        max_new_tokens: int = MAX_NEW_TOKENS,
        temperature: float = DEFAULT_TEMPERATURE,
        top_k: int = DEFAULT_TOP_K,
    ) -> str:

        generated = tokenize(prompt)

        for _ in range(max_new_tokens):

            token = self.sample_next(
                generated,
                temperature=temperature,
                top_k=top_k,
            )

            if token == self.eos_token:
                break

            generated.append(token)

        return " ".join(
            visible_tokens(generated)
        )

    # --------------------------------------------------------
    # Persistence
    # --------------------------------------------------------

    def to_dict(self) -> dict:

        return {
            "eos_token": self.eos_token,
            "unk_token": self.unk_token,
            "min_count": self.min_count,
            "smoothing_alpha": (
                self.smoothing_alpha
            ),
            "unigram": dict(self.unigram),
            "bigram": {
                key: dict(value)
                for key, value
                in self.bigram.items()
            },
            "trigram": {
                key: dict(value)
                for key, value
                in self.trigram.items()
            },
            "vocabulary": self.vocabulary,
            "finalized": self.finalized,
        }

    @classmethod
    def from_dict(
        cls,
        data: dict,
    ) -> "NGramModel":

        model = cls(
            eos_token=data.get(
                "eos_token",
                "<eos>",
            ),
            unk_token=data.get(
                "unk_token",
                "<unk>",
            ),
            min_count=int(
                data.get(
                    "min_count",
                    MIN_COUNT,
                )
            ),
            smoothing_alpha=float(
                data.get(
                    "smoothing_alpha",
                    SMOOTHING_ALPHA,
                )
            ),
        )

        model.unigram = Counter(
            data.get("unigram", {})
        )

        model.bigram = defaultdict(
            Counter,
            {
                key: Counter(value)
                for key, value
                in data.get(
                    "bigram",
                    {},
                ).items()
            },
        )

        model.trigram = defaultdict(
            Counter,
            {
                key: Counter(value)
                for key, value
                in data.get(
                    "trigram",
                    {},
                ).items()
            },
        )

        model.vocabulary = list(
            data.get(
                "vocabulary",
                [],
            )
        )

        model.finalized = bool(
            data.get(
                "finalized",
                False,
            )
        )

        return model

    def save_json(
        self,
        path: Path,
    ) -> None:

        path.write_text(
            json.dumps(
                self.to_dict(),
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )

    @classmethod
    def load_json(
        cls,
        path: Path,
    ) -> "NGramModel":

        return cls.from_dict(
            json.loads(
                path.read_text(
                    encoding="utf-8"
                )
            )
        )


