@dataclass
class AppState:

    model: NGramModel | None = None
    search: CorpusSearch | None = None
    graph: CorpusGraph | None = None
    corpus_text: str = ""

    def load_corpus(
        self,
        text: str,
    ) -> None:

        self.corpus_text = text

        self.search = CorpusSearch()
        self.search.build_index(text)

        self.graph = CorpusGraph()
        self.graph.build(text)

    def train(
        self,
        text: str,
    ) -> NGramModel:

        model = NGramModel()

        model.ingest_text(text)
        model.finalize()

        model.save_json(
            MODEL_PATH
        )

        self.model = model
        self.load_corpus(text)

        return model

    def load_existing(self) -> bool:

        if not MODEL_PATH.exists():
            return False

        try:

            self.model = (
                NGramModel.load_json(
                    MODEL_PATH
                )
            )

            if not self.model.finalized:
                self.model.finalize()

        except Exception:
            self.model = None
            return False

        if DEFAULT_CORPUS_FILE.exists():

            text = (
                DEFAULT_CORPUS_FILE.read_text(
                    encoding="utf-8",
                    errors="replace",
                )
            )

            self.load_corpus(text)

        return True


STATE = AppState()


# ============================================================
# UI helpers
# ============================================================

def format_matches(
    prompt: str,
    limit: int = 5,
) -> str:

    if (
        STATE.search is None
        or not STATE.search.references
    ):
        return "No corpus index loaded."

    candidates = STATE.search.analyze(
        prompt,
        limit,
    )

    if not candidates:
        return "No corpus matches found."

    return "\n".join(
        (
            f"{candidate.rank}. "
            f"{candidate.sentence} "
            f"(score={candidate.score:.3f}, "
            f"overlap={candidate.symbolic_overlap:.3f}, "
            f"vector={candidate.vector_similarity:.3f})"
        )
        for candidate in candidates
    )


def train_model_from_file(
    corpus_file,
):

    if corpus_file is None:

        return (
            "No corpus uploaded.",
            "",
            "",
            "",
            "",
        )

    path = Path(
        corpus_file.name
        if hasattr(corpus_file, "name")
        else str(corpus_file)
    )

    if not path.exists():

        return (
            f"Corpus file not found: {path}",
            "",
            "",
            "",
            "",
        )

    corpus_text = path.read_text(
        encoding="utf-8",
        errors="replace",
    )

    model = STATE.train(
        corpus_text
    )

    sample = "\n".join(
        itertools.islice(
            corpus_text.splitlines(),
            5,
        )
    )

    summary = "\n".join(
        [
            f"Vocabulary: {len(model.vocabulary)}",
            f"Unigrams: {len(model.unigram)}",
            f"Bigram contexts: {len(model.bigram)}",
            f"Trigram contexts: {len(model.trigram)}",
        ]
    )

    graph_stats = (
        STATE.graph.diagnostics()
        if STATE.graph
        else "No graph."
    )

    dot = (
        STATE.graph.to_dot(40)
        if STATE.graph
        else "digraph Corpus {}"
    )

    return (
        f"Model trained and saved to {MODEL_PATH}.",
        sample,
        summary,
        graph_stats,
        dot,
    )


def generate_text(
    user_prompt: str,
):

    if STATE.model is None:

        return (
            "Model not loaded. "
            "Train a corpus first.",
            "",
            "",
        )

    prompt = (
        user_prompt.strip()
        if user_prompt
        else ""
    )

    generated = STATE.model.generate(
        prompt=prompt,
        max_new_tokens=MAX_NEW_TOKENS,
        temperature=DEFAULT_TEMPERATURE,
        top_k=DEFAULT_TOP_K,
    )

    matches = (
        format_matches(prompt)
        if prompt
        else "No prompt supplied."
    )

    diagnostics = (
        STATE.model.distribution_report(
            tokenize(prompt),
            top_k=15,
        )
    )

    return (
        matches,
        generated,
        diagnostics,
    )


def graph_report() -> tuple[str, str]:

    if STATE.graph is None:

        return (
            "No graph loaded.",
            "digraph Corpus {}",
        )

    return (
        STATE.graph.diagnostics(),
        STATE.graph.to_dot(40),
    )


